insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('marie-curie','marie-curie','玛丽·居里','Marie Curie','published','{"id":"marie-curie","slug":"marie-curie","nameZh":"玛丽·居里","nameEn":"Marie Curie","fields":["科学"],"regions":["波兰","法国"],"occupation":"物理学家、化学家","keywords":["科学","物理学家、化学家"],"summary":"玛丽·居里是出生于波兰、在法国从事研究的物理学家和化学家，以放射性研究闻名。她与皮埃尔·居里、亨利·贝克勒尔共享1903年诺贝尔物理学奖，又于1911年获诺贝尔化学奖。她与皮埃尔开展钋和镭的分离研究，并在第一次世界大战期间组织移动式X射线服务。","story":"居里的科研经历跨越波兰与法国。科学史研究所的传记记载，她曾在波兰担任家庭教师，后来赴巴黎继续学习，在索邦接受高等科学教育，并与皮埃尔·居里共同开展研究。贝克勒尔关于铀盐的观察，为她选择放射性作为研究主题提供了科学背景。\n她与皮埃尔通过反复的化学反应、结晶和测量，研究矿石中的放射性物质。1898年，两人宣布发现钋和镭。这段工作并不是只给新元素命名，还包括从混合材料中分离物质并检验其性质的实验过程。1903年，她与皮埃尔、贝克勒尔共享诺贝尔物理学奖；1911年，她又获得诺贝尔化学奖。\n科学史研究所还记录了她在第一次世界大战期间组织便携式X射线设备服务的工作，使这份档案能够同时呈现实验室研究和医疗技术应用。人物经历按可读取的机构传记整理，保留合作研究者的贡献。","achievements":["与皮埃尔·居里、贝克勒尔共享1903年诺贝尔物理学奖。","1911年获得诺贝尔化学奖。"],"facts":[{"claim":"物理学家、化学家；与皮埃尔·居里、贝克勒尔共享1903年诺贝尔物理学奖。","sourceUrls":["https://www.sciencehistory.org/education/scientific-biographies/marie-sklodowska-curie/"]},{"claim":"物理学家、化学家；1911年获得诺贝尔化学奖。","sourceUrls":["https://www.sciencehistory.org/education/scientific-biographies/marie-sklodowska-curie/"]}],"sources":[{"title":"Science History Institute：Marie Sklodowska Curie","url":"https://www.sciencehistory.org/education/scientific-biographies/marie-sklodowska-curie/","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"published","updatedAt":"2026-11-09","featured":true,"lastVerifiedAt":"2026-11-09","reviewedAt":"2026-11-09","editorialNotes":["本页为机构资料的中文编辑整理；代表事实与时间线分别关联来源。未采用无法确认的私人对话、个人动机和图像授权。","未采用来源中需要进一步医学史复核的死因表述。","此处不采用来源中可能需要进一步医学史核对的死因表述，也不从获奖结果倒推她的个人动机。"],"timeline":[{"year":1903,"description":"物理学家、化学家；与皮埃尔·居里、贝克勒尔共享1903年诺贝尔物理学奖。","sourceUrls":["https://www.sciencehistory.org/education/scientific-biographies/marie-sklodowska-curie/"]},{"year":1911,"description":"物理学家、化学家；1911年获得诺贝尔化学奖。","sourceUrls":["https://www.sciencehistory.org/education/scientific-biographies/marie-sklodowska-curie/"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('tu-youyou','tu-youyou','屠呦呦','Tu Youyou','published','{"id":"tu-youyou","slug":"tu-youyou","nameZh":"屠呦呦","nameEn":"Tu Youyou","fields":["医学"],"regions":["中国"],"keywords":["青蒿素","疟疾","药学"],"summary":"屠呦呦是中国药学研究者，长期从事中药研究。她与团队改进青蒿提取方法，分离出抗疟有效成分青蒿素，并参与验证其临床效果。她于2011年获得拉斯克临床医学研究奖，2015年获诺贝尔生理学或医学奖。其工作连接传统文献研究、实验提取与现代药物研发。","achievements":["与团队分离青蒿素并验证其抗疟临床效果。","2015年获得诺贝尔生理学或医学奖。"],"story":"屠呦呦的研究经历可以从药学教育与长期实验工作展开。国家科技奖励工作办公室的档案记载，她于1955年从北京医学院药学专业毕业，同年进入中医研究机构工作。此后，她参与的抗疟研究把文献线索与实验检测结合起来，研究对象包括青蒿及其提取物。\n研究中的关键进展是改进提取工艺。她参考传统医药文献，调整常规方法，采用低温提取，随后与团队分离出有效纯化合物青蒿素，并验证提取物和青蒿素的临床效果。结构研究还涉及其他机构合作，因此这段历程需要同时保留个人贡献与团队协作。\n2011年，她获得拉斯克临床医学研究奖；2015年，她因抗疟新疗法相关发现获得诺贝尔生理学或医学奖。北京大学的获奖报道也确认了该奖项。从提取物到纯化合物，再到结构研究与临床效果验证，抗疟药物研发需要不同阶段的证据，也依赖跨机构合作。","sources":[{"title":"国家科技奖励工作办公室：Tu Youyou","url":"https://www.nosta.gov.cn/pc/en/awards/awardees1/1456.shtml","checkedAt":"2026-11-09"},{"title":"北京大学：屠呦呦获2015年诺贝尔生理学或医学奖","url":"https://english.pku.edu.cn/news_events/news/focus/3964.html","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"published","updatedAt":"2026-11-09","featured":true,"occupation":"药学研究者","facts":[{"claim":"1955年药学专业毕业并进入中医研究机构工作。","sourceUrls":["https://www.nosta.gov.cn/pc/en/awards/awardees1/1456.shtml"]},{"claim":"与团队分离青蒿素并验证其抗疟临床效果。","sourceUrls":["https://www.nosta.gov.cn/pc/en/awards/awardees1/1456.shtml"]},{"claim":"2015年获得诺贝尔生理学或医学奖。","sourceUrls":["https://www.nosta.gov.cn/pc/en/awards/awardees1/1456.shtml","https://english.pku.edu.cn/news_events/news/focus/3964.html"]}],"lastVerifiedAt":"2026-11-09","reviewedAt":"2026-11-09","editorialNotes":["本页为机构资料的中文编辑整理；代表事实与时间线分别关联来源。未采用无法确认的私人对话、个人动机和图像授权。","这里呈现的是有档案支持的教育、实验与获奖脉络，不将药物研发简化成某一次灵感，也不补写研究者未被资料证实的私人动机。"],"timeline":[{"year":1955,"description":"1955年药学专业毕业并进入中医研究机构工作。","sourceUrls":["https://www.nosta.gov.cn/pc/en/awards/awardees1/1456.shtml"]},{"year":2015,"description":"2015年获得诺贝尔生理学或医学奖。","sourceUrls":["https://www.nosta.gov.cn/pc/en/awards/awardees1/1456.shtml","https://english.pku.edu.cn/news_events/news/focus/3964.html"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('ada-lovelace','ada-lovelace','阿达·洛夫莱斯','Ada Lovelace','published','{"id":"ada-lovelace","slug":"ada-lovelace","nameZh":"阿达·洛夫莱斯","nameEn":"Ada Lovelace","fields":["数学"],"regions":["英国"],"occupation":"数学研究者、计算先驱","keywords":["数学","数学研究者、计算先驱"],"summary":"阿达·洛夫莱斯是英国数学研究者和早期计算先驱。1843年，她翻译梅纳布雷亚介绍巴贝奇分析机的论文，并附上大量笔记，讨论机器的运算方式和潜力。她曾通过与德摩根通信学习高等数学，相关手稿保存在牛津博德利图书馆，为研究其数学训练与计算思想提供了材料。","story":"阿达·洛夫莱斯的计算研究与十九世纪数学学习和机械计算设计有关。英国工程技术学会的档案记载，她年轻时认识查尔斯·巴贝奇，接触用于自动制作数表的差分机，随后持续关注他的机器设计。分析机则是面向更一般运算任务的可编程机械装置，两种设计不应混为一谈。\n1843年，她翻译梅纳布雷亚关于分析机的论文，并增加说明机器操作的笔记。IET将其中的计算方案称为最早的计算机程序之一。\n克雷数学研究所提供的数学手稿介绍补充了她的学习过程。1840至1841年，她与德摩根通信，学习包括微积分在内的更高等内容，相关材料保存在博德利图书馆的家族档案中。由此可以把翻译、数学训练和机器笔记放在同一条学术脉络里。这些通信保存了她从基础几何走向微积分的学习过程，也留下了德摩根如何指出知识缺口和引导进一步学习的记录。翻译与笔记由此有了持续数学训练的背景。","achievements":["1843年翻译梅纳布雷亚介绍分析机的论文并增加笔记。","笔记中包含被IET称为最早计算机程序之一的方案。"],"facts":[{"claim":"1843年翻译梅纳布雷亚介绍分析机的论文并增加笔记。","sourceUrls":["https://www.theiet.org/membership/library-and-archives/the-iet-archives/biographies/ada-countess-of-lovelace"]},{"claim":"笔记中包含被IET称为最早计算机程序之一的方案。","sourceUrls":["https://www.theiet.org/membership/library-and-archives/the-iet-archives/biographies/ada-countess-of-lovelace"]}],"sources":[{"title":"IET：Ada Countess of Lovelace","url":"https://www.theiet.org/membership/library-and-archives/the-iet-archives/biographies/ada-countess-of-lovelace","checkedAt":"2026-11-09"},{"title":"Clay Mathematics Institute：数学手稿","url":"https://www.claymath.org/online-resources/ada-lovelaces-mathematical-papers/","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"published","updatedAt":"2026-11-09","featured":true,"lastVerifiedAt":"2026-11-09","reviewedAt":"2026-11-09","editorialNotes":["本页为机构资料的中文编辑整理；代表事实与时间线分别关联来源。未采用无法确认的私人对话、个人动机和图像授权。","“最早计算机程序之一”沿用IET的限定表述，不宣称已经运行建成的现代计算机。","这里沿用这一有限表述，不把后来形成的程序员职业身份完整套用到当时，也不声称她已经运行了一台建成的现代计算机。","本档案只记录有来源的学习与写作活动，不用未经证实的名言或个人动机解释她的贡献。"],"timeline":[{"year":1843,"description":"1843年翻译梅纳布雷亚介绍分析机的论文并增加笔记。","sourceUrls":["https://www.theiet.org/membership/library-and-archives/the-iet-archives/biographies/ada-countess-of-lovelace"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('katherine-johnson','katherine-johnson','凯瑟琳·约翰逊','Katherine Johnson','published','{"id":"katherine-johnson","slug":"katherine-johnson","nameZh":"凯瑟琳·约翰逊","nameEn":"Katherine Johnson","fields":["数学"],"regions":["美国"],"keywords":["航天","轨道计算","NASA"],"summary":"凯瑟琳·约翰逊是美国数学家，1953年进入美国国家航空咨询委员会兰利实验室工作。她为1961年艾伦·谢泼德的载人飞行进行轨迹分析，并在1962年约翰·格伦飞行前复核电子计算结果。她还参与阿波罗计划相关计算，1986年退休，2015年获总统自由勋章。","achievements":["为1961年艾伦·谢泼德的 Freedom 7 任务进行轨迹分析。","在1962年约翰·格伦 Friendship 7 飞行前手工复核轨道计算。"],"story":"凯瑟琳·约翰逊的职业生涯与航空研究向载人航天发展的过程相连。NASA的传记记载，她于1937年从西弗吉尼亚州立学院毕业，随后从事教学。1953年，她进入美国国家航空咨询委员会的兰利实验室，最初处理飞行试验数据，后来逐渐参与航天任务的数学工作。\n1960年，她与工程师特德·斯科平斯基共同署名一份研究报告，讨论如何使卫星抵达指定地面位置。1961年，她为艾伦·谢泼德的Freedom 7任务进行轨迹分析。次年，约翰·格伦准备进行轨道飞行时，她又用机械计算器复核已经输入电子计算机的轨道方程与数值。\n她的工作并未止步于这两次任务，还涉及阿波罗计划中登月舱与绕月指令舱的同步计算。1986年，她从兰利退休；2015年获得总统自由勋章。这些记录展示了数学分析在任务准备与结果复核中的具体作用。","sources":[{"title":"NASA：Katherine Johnson Biography","url":"https://www.nasa.gov/centers-and-facilities/langley/katherine-johnson-biography/","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"published","updatedAt":"2026-11-09","featured":true,"occupation":"数学家","facts":[{"claim":"1953年进入NACA兰利实验室工作，职业为数学家。","sourceUrls":["https://www.nasa.gov/centers-and-facilities/langley/katherine-johnson-biography/"]},{"claim":"为1961年艾伦·谢泼德的 Freedom 7 任务进行轨迹分析。","sourceUrls":["https://www.nasa.gov/centers-and-facilities/langley/katherine-johnson-biography/"]},{"claim":"在1962年约翰·格伦 Friendship 7 飞行前手工复核轨道计算。","sourceUrls":["https://www.nasa.gov/centers-and-facilities/langley/katherine-johnson-biography/"]}],"lastVerifiedAt":"2026-11-09","reviewedAt":"2026-11-09","editorialNotes":["本页为机构资料的中文编辑整理；代表事实与时间线分别关联来源。未采用无法确认的私人对话、个人动机和图像授权。","不同NASA页面的论文总数不同，未采用累计论文数。","档案之外的对话和个人心理不在此补写，研究报告数量在不同NASA页面存在差异，本档案暂不采用该数字。"],"timeline":[{"year":1953,"description":"1953年进入NACA兰利实验室工作，职业为数学家。","sourceUrls":["https://www.nasa.gov/centers-and-facilities/langley/katherine-johnson-biography/"]},{"year":1961,"description":"为1961年艾伦·谢泼德的 Freedom 7 任务进行轨迹分析。","sourceUrls":["https://www.nasa.gov/centers-and-facilities/langley/katherine-johnson-biography/"]},{"year":1962,"description":"在1962年约翰·格伦 Friendship 7 飞行前手工复核轨道计算。","sourceUrls":["https://www.nasa.gov/centers-and-facilities/langley/katherine-johnson-biography/"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('rosalind-franklin','rosalind-franklin','罗莎琳德·富兰克林','Rosalind Franklin','published','{"id":"rosalind-franklin","slug":"rosalind-franklin","nameZh":"罗莎琳德·富兰克林","nameEn":"Rosalind Franklin","fields":["科学"],"regions":["英国"],"occupation":"生物物理学家、晶体学研究者","keywords":["科学","生物物理学家、晶体学研究者"],"summary":"罗莎琳德·富兰克林是英国生物物理学家，以X射线晶体学研究闻名。她与研究学生雷蒙德·戈斯林获得DNA的51号照片，为理解双螺旋结构提供了重要实验资料。1953年离开伦敦国王学院后，她在伯克贝克学院建立团队研究病毒结构，相关成果成为结构病毒学的基础之一。","story":"富兰克林接受过剑桥的科学教育，并在巴黎积累X射线衍射经验。她在伦敦国王学院研究DNA时，重视样品条件与实验图像之间的关系。校方专题记录，通过控制含水量，她区分DNA的A型和B型；1952年5月，她与研究学生雷蒙德·戈斯林取得B型DNA的51号照片。\n照片是结构研究的一部分，不能替代样品处理、测量和分析。\n1953年，她离开国王学院，在伯克贝克学院组织团队研究病毒结构。其研究生涯因此不应只以DNA争议概括，也包括后来在病毒领域的实验与团队工作。在DNA研究中，实验图像、样品状态和结构模型相互联系。国王学院的档案记载，威尔金斯曾在她不知情也未同意的情况下向沃森展示51号照片。1953年沃森与克里克建立模型时，这些实验材料成为重要依据。她随后研究病毒结构，团队在她1958年去世前发表的论文也留下了这一阶段的成果。","achievements":["与研究学生雷蒙德·戈斯林取得1952年5月的DNA 51号照片。","1953年离开国王学院后，在伯克贝克学院建立病毒结构研究团队。"],"facts":[{"claim":"与研究学生雷蒙德·戈斯林取得1952年5月的DNA 51号照片。","sourceUrls":["https://www.kcl.ac.uk/people/rosalind-franklin"]},{"claim":"1953年离开国王学院后，在伯克贝克学院建立病毒结构研究团队。","sourceUrls":["https://www.kcl.ac.uk/people/rosalind-franklin"]}],"sources":[{"title":"King’s College London：Rosalind Franklin档案","url":"https://www.kcl.ac.uk/people/rosalind-franklin","checkedAt":"2026-11-09"},{"title":"King’s College London：Photo 51专题","url":"https://www.kcl.ac.uk/photo-51-and-the-discovery-of-dna","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"published","updatedAt":"2026-11-09","featured":true,"lastVerifiedAt":"2026-11-09","reviewedAt":"2026-11-09","editorialNotes":["本页为机构资料的中文编辑整理；代表事实与时间线分别关联来源。未采用无法确认的私人对话、个人动机和图像授权。","两个校方页面的入职年份有差异，未将具体入职年写入时间线。","国王学院档案也明确将戈斯林列入研究过程，因此本档案保留共同工作的表述，不把全部实验过程缩成一个人独自拍照的故事。","关于照片如何被其他研究者看到，校方有相关历史说明，但这里不增加未见资料支持的私人对话。","两篇校方页面对加入国王学院的年份表述不同，本批未采用具体入职年份；档案仅保留能够一致确认的实验、合作与研究方向，避免用荣誉归属争论代替科学工作本身。"],"timeline":[{"year":1952,"description":"与研究学生雷蒙德·戈斯林取得1952年5月的DNA 51号照片。","sourceUrls":["https://www.kcl.ac.uk/people/rosalind-franklin"]},{"year":1953,"description":"1953年离开国王学院后，在伯克贝克学院建立病毒结构研究团队。","sourceUrls":["https://www.kcl.ac.uk/people/rosalind-franklin"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('jane-goodall','jane-goodall','珍·古道尔','Jane Goodall','published','{"id":"jane-goodall","slug":"jane-goodall","nameZh":"珍·古道尔","nameEn":"Jane Goodall","fields":["科学"],"regions":["英国","坦桑尼亚"],"occupation":"动物行为学家、自然保护倡导者","keywords":["科学","动物行为学家、自然保护倡导者"],"summary":"珍·古道尔是英国动物行为学家和自然保护倡导者。她于1960年在如今坦桑尼亚的贡贝开始黑猩猩研究，观察到黑猩猩使用工具，并于1965年完成剑桥博士论文。1977年，她创办珍·古道尔研究会，后来建立根与芽青少年项目，将动物研究、社区保护和环境教育联系起来。","story":"古道尔的研究生涯与东非野外工作相连。珍·古道尔研究会的生平档案记载，她早年在肯尼亚与路易斯·利基接触，后来获得在贡贝研究野生黑猩猩的机会。1960年7月14日，她首次抵达贡贝，开始观察黑猩猩在自然环境中的行为。\n她关于黑猩猩使用工具的观察成为这一研究的重要发现。之后，她进入剑桥大学学习动物行为学，并于1965年完成有关贡贝自由生活黑猩猩行为的博士论文。原先短期安排的野外研究逐渐发展为持续多年的项目，因此人物故事也需要保留长期观察和后续研究团队的作用。\n1977年，她建立珍·古道尔研究会，最初支持贡贝研究；1991年，她又创办根与芽项目，支持青年参与动物、环境和社区行动。她于2025年去世，机构继续其研究和保护工作。","achievements":["1960年7月14日抵达贡贝开展黑猩猩研究，观察到黑猩猩使用工具。","1977年创办珍·古道尔研究会。"],"facts":[{"claim":"1960年7月14日抵达贡贝开展黑猩猩研究，观察到黑猩猩使用工具。","sourceUrls":["https://janegoodall.org/remembering-jane/"]},{"claim":"1977年创办珍·古道尔研究会。","sourceUrls":["https://janegoodall.org/remembering-jane/"]}],"sources":[{"title":"Jane Goodall Institute：纪念与生平档案","url":"https://janegoodall.org/remembering-jane/","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"published","updatedAt":"2026-11-09","featured":true,"lastVerifiedAt":"2026-11-09","reviewedAt":"2026-11-09","editorialNotes":["本页为机构资料的中文编辑整理；代表事实与时间线分别关联来源。未采用无法确认的私人对话、个人动机和图像授权。","本档案采用该机构的纪念资料，避免把早期传记中的旅行日程或职位表述当作现状；不补写丛林中的对话与动机，也不将整个组织的长期成果归为她个人单独完成。"],"timeline":[{"year":1960,"description":"1960年7月14日抵达贡贝开展黑猩猩研究，观察到黑猩猩使用工具。","sourceUrls":["https://janegoodall.org/remembering-jane/"]},{"year":1977,"description":"1977年创办珍·古道尔研究会。","sourceUrls":["https://janegoodall.org/remembering-jane/"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('wang-zhenyi','wang-zhenyi','王贞仪','Wang Zhenyi','published','{"id":"wang-zhenyi","slug":"wang-zhenyi","nameZh":"王贞仪","nameEn":"Wang Zhenyi","fields":["数学"],"regions":["中国"],"occupation":"数学、天文学研究者、诗人","keywords":["数学","数学、天文学研究者、诗人"],"summary":"王贞仪是清代数学、天文学研究者和诗人，生活于1768至1797年。她撰写有关数学与天文的文章，《月食解》运用自绘图说明月相和月食原理。其部分作品保存于《德风亭初集》，涉及勾股、三角与地球形状等议题。她的研究记录体现了清代女性参与科学知识写作的经历。","story":"王贞仪生活于清代，研究兴趣涉及天文、数学和诗文。香港太空馆的专题介绍，她在家庭教育中接触广泛读物，后来撰写多种有关自然现象与数学问题的文章。对这类历史人物，现存著作和后人的整理是理解其工作的主要线索，不能把现代研究机构的职业体系直接套用到她的生活中。\n太空馆指出，部分作品收入仍可见到的《德风亭初集》，其中包括《月食解》以及讨论勾股、三角、岁差与地球形状的文章。在《月食解》中，她利用自己绘制的图示解释月相与月食。这一事实说明她不仅接触天文知识，也尝试通过书写和图像表达自然原理。人物记录同时保留英文转写姓名，避免与同名的现代医学研究者混淆。她的文章把对天空现象的观察与数学解释联系起来，图示则成为传达原理的方法。留下来的篇章让后人能够从具体论述认识她，而不只依靠生平传说。","achievements":["撰写《月食解》，用自绘图解释月相和月食。","部分数学、天文作品保存于《德风亭初集》，包括勾股与三角相关讨论。"],"facts":[{"claim":"撰写《月食解》，用自绘图解释月相和月食。","sourceUrls":["https://hk.space.museum/en/web/spm/resources/curators-blog/2021/03/wang-zhenyi-an-extraordinary-woman-astronomer-from-the-qing-dynasty.html"]},{"claim":"部分数学、天文作品保存于《德风亭初集》，包括勾股与三角相关讨论。","sourceUrls":["https://hk.space.museum/en/web/spm/resources/curators-blog/2021/03/wang-zhenyi-an-extraordinary-woman-astronomer-from-the-qing-dynasty.html"]}],"sources":[{"title":"Hong Kong Space Museum：清代女天文学家王贞仪","url":"https://hk.space.museum/en/web/spm/resources/curators-blog/2021/03/wang-zhenyi-an-extraordinary-woman-astronomer-from-the-qing-dynasty.html","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"published","updatedAt":"2026-11-09","featured":true,"lastVerifiedAt":"2026-11-09","reviewedAt":"2026-11-09","editorialNotes":["本页为机构资料的中文编辑整理；代表事实与时间线分别关联来源。未采用无法确认的私人对话、个人动机和图像授权。","无确切年份的著述不补造时间线日期；不要与同名现代医学研究者混淆。","她1797年去世，许多著作后来散失，因此本档案没有依据网络流传的作品数量构造完整书目，也不增写具体实验场景。","这里采用博物馆能够支持的生卒、作品与研究主题，未将当时的学术表达改写成未经核对的现代定理首创权或国际获奖经历。"],"timeline":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('grace-hopper','grace-hopper','格蕾丝·霍珀','Grace Hopper','published','{"id":"grace-hopper","slug":"grace-hopper","nameZh":"格蕾丝·霍珀","nameEn":"Grace Hopper","fields":["数学"],"regions":["美国"],"occupation":"数学家、计算机科学先驱、海军军官","keywords":["数学","数学家、计算机科学先驱、海军军官"],"summary":"格蕾丝·霍珀是美国数学家、计算机科学先驱和海军军官。她于1934年获得耶鲁大学数学博士学位，曾在瓦萨学院教授数学，后来参与哈佛Mark I计算工作。1952年，她开发A-0系统，随后与团队推进使用英文指令的FLOW-MATIC，并参与商业编程语言标准化讨论。","story":"霍珀的早期职业建立在数学教育之上。耶鲁大学传记记载，她于1928年从瓦萨学院毕业，1930年获耶鲁数学硕士，1934年完成博士学位。在继续深造的同时，她在瓦萨教授数学，后来以海军预备役军官身份进入计算工作。\n在哈佛，她加入Mark I团队，从事计算并编写使用手册。战后，她继续研究计算机，1949年进入埃克特—莫奇利公司担任高级数学家。在UNIVAC相关工作中，她探索让计算机承担更多编码与转换任务的自动编程方法，1952年开发A-0系统。\n此后，她与团队推进使用英文词语指令的FLOW-MATIC，并于1959年参与商业数据处理语言的标准化会议。这些工作涉及不同阶段、系统与合作者，不宜将其简化为她独力发明所有高级语言。","achievements":["1934年获得耶鲁大学数学博士学位。","1952年开发A-0自动编程系统。"],"facts":[{"claim":"1934年获得耶鲁大学数学博士学位。","sourceUrls":["https://president.yale.edu/biography-grace-murray-hopper"]},{"claim":"1952年开发A-0自动编程系统。","sourceUrls":["https://president.yale.edu/biography-grace-murray-hopper"]}],"sources":[{"title":"Yale：Grace Murray Hopper传记","url":"https://president.yale.edu/biography-grace-murray-hopper","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"published","updatedAt":"2026-11-09","featured":true,"lastVerifiedAt":"2026-11-09","reviewedAt":"2026-11-09","editorialNotes":["本页为机构资料的中文编辑整理；代表事实与时间线分别关联来源。未采用无法确认的私人对话、个人动机和图像授权。","A-0的历史编译器称谓不等同于今天所有编译工具的定义。","A-0在早期计算史中的编译器称谓也与今天的工具定义存在语境差异，本档案保留系统名称和年份，不据此扩展未经核实的技术优先权断言。","这里没有补写实验室对白、名言或个人动机。"],"timeline":[{"year":1934,"description":"1934年获得耶鲁大学数学博士学位。","sourceUrls":["https://president.yale.edu/biography-grace-murray-hopper"]},{"year":1952,"description":"1952年开发A-0自动编程系统。","sourceUrls":["https://president.yale.edu/biography-grace-murray-hopper"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('chien-shiung-wu','chien-shiung-wu','吴健雄','Chien-Shiung Wu','published','{"id":"chien-shiung-wu","slug":"chien-shiung-wu","nameZh":"吴健雄","nameEn":"Chien-Shiung Wu","fields":["科学"],"regions":["中国","美国"],"occupation":"实验物理学家","keywords":["科学","实验物理学家"],"summary":"吴健雄是出生于中国、在美国从事研究的实验物理学家，1940年获得加利福尼亚大学伯克利分校博士学位。她与同事在1956年至1957年开展实验，为弱相互作用中的宇称不守恒提供证据。她长期在哥伦比亚大学工作，著有《贝塔衰变》，并于1978年获得首届沃尔夫物理学奖。","story":"吴健雄于1936年前往美国，1940年从加利福尼亚大学伯克利分校获得博士学位。哥伦比亚大学的校史档案记载，她于1944年加入该校，此后长期从事实验物理研究，特别关注贝塔衰变等问题。她的研究经历包含实验装置、测量方法与物理理论之间的联系。\n1956年至1957年初，她与同事设计并开展实验，检验李政道和杨振宁提出的关于弱相互作用对称性的假说。结果为宇称在特定弱相互作用过程中不守恒提供了实验证据。这个结论有明确的物理适用范围，不应改写成所有自然过程都没有镜像对称性，也不能抹去参与实验的其他研究者。\n她后来继续在哥伦比亚大学开展研究，1965年出版《贝塔衰变》，并于1978年获得首届沃尔夫物理学奖。校史资料也列出她的教学与其他研究方向。","achievements":["1956年至1957年初与同事完成检验弱相互作用宇称对称性的实验。","1978年获得首届沃尔夫物理学奖。"],"facts":[{"claim":"1956年至1957年初与同事完成检验弱相互作用宇称对称性的实验。","sourceUrls":["https://www.c250.columbia.edu/c250_celebrates/remarkable_columbians/chien-shiung_wu.html"]},{"claim":"1978年获得首届沃尔夫物理学奖。","sourceUrls":["https://www.c250.columbia.edu/c250_celebrates/remarkable_columbians/chien-shiung_wu.html"]}],"sources":[{"title":"Columbia：Chien-Shiung Wu校史档案","url":"https://www.c250.columbia.edu/c250_celebrates/remarkable_columbians/chien-shiung_wu.html","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"published","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":"2026-11-09","editorialNotes":["本页为机构资料的中文编辑整理；代表事实与时间线分别关联来源。未采用无法确认的私人对话、个人动机和图像授权。","本档案采用可核对的教育、实验和出版记录，不把诺贝尔奖归属争议转换成未有证据的私人心理描写，也不采用尚未在本批另行交叉核对的学会任职年份。"],"timeline":[{"year":1978,"description":"1978年获得首届沃尔夫物理学奖。","sourceUrls":["https://www.c250.columbia.edu/c250_celebrates/remarkable_columbians/chien-shiung_wu.html"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('sally-ride','sally-ride','萨莉·赖德','Sally Ride','published','{"id":"sally-ride","slug":"sally-ride","nameZh":"萨莉·赖德","nameEn":"Sally Ride","fields":["探索"],"regions":["美国"],"occupation":"宇航员、物理学家","keywords":["探索","宇航员、物理学家"],"summary":"萨莉·赖德是美国宇航员和物理学家。她于1978年加入NASA宇航员队伍，1983年乘挑战者号执行STS-7任务，成为首位进入太空的美国女性。1984年，她再次执行STS-41G任务。离开NASA后，她在加利福尼亚大学圣迭戈分校从事学术工作，并参与科学教育。","story":"赖德于1978年入选NASA宇航员队伍，那一届首次纳入女性成员。NASA人物档案记载，她经历多年训练后被安排执行STS-7任务。1983年6月18日，她与同组成员乘挑战者号升空，成为首位进入太空的美国女性。这个称谓需要保留美国的范围，不能写成世界首位女性宇航员。\nSTS-7在为期六天的飞行中部署通信卫星并进行科学实验。1984年，她再次乘挑战者号执行STS-41G任务，任务涉及地球辐射收支卫星部署、地球观测和卫星加注技术演示。两次任务使这份档案不仅有首次飞行的纪录，也有具体的科研与操作背景。\n此后，她参与挑战者号事故调查，并从事NASA长期与战略规划相关工作。离开NASA后，她在加利福尼亚大学圣迭戈分校开展学术工作，2001年创办Sally Ride Science，参与科学、数学和技术教育。","achievements":["1983年6月18日执行STS-7任务，成为首位进入太空的美国女性。","1984年执行STS-41G航天飞机任务。"],"facts":[{"claim":"宇航员、物理学家；1983年6月18日执行STS-7任务，成为首位进入太空的美国女性。","sourceUrls":["https://science.nasa.gov/people/sally-ride/"]},{"claim":"宇航员、物理学家；1984年执行STS-41G航天飞机任务。","sourceUrls":["https://science.nasa.gov/people/sally-ride/"]}],"sources":[{"title":"NASA Science：Sally Ride人物档案","url":"https://science.nasa.gov/people/sally-ride/","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"published","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":"2026-11-09","editorialNotes":["本页为机构资料的中文编辑整理；代表事实与时间线分别关联来源。未采用无法确认的私人对话、个人动机和图像授权。","NASA页面对离开机构年份有不同口径，未采用；首位美国女性不等同于世界首位。","上述经历依据NASA公开档案整理，不复写其中的采访对白，也不添加发射时的私人心理描写；涉及具体职务和任务的事实与对应来源一并保留。"],"timeline":[{"year":1983,"description":"宇航员、物理学家；1983年6月18日执行STS-7任务，成为首位进入太空的美国女性。","sourceUrls":["https://science.nasa.gov/people/sally-ride/"]},{"year":1984,"description":"宇航员、物理学家；1984年执行STS-41G航天飞机任务。","sourceUrls":["https://science.nasa.gov/people/sally-ride/"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('maryam-mirzakhani','maryam-mirzakhani','玛丽亚姆·米尔扎哈尼','Maryam Mirzakhani','verified','{"id":"maryam-mirzakhani","slug":"maryam-mirzakhani","nameZh":"玛丽亚姆·米尔扎哈尼","nameEn":"Maryam Mirzakhani","fields":["数学"],"regions":["伊朗","美国"],"occupation":"数学家","keywords":["数学","数学家"],"summary":"玛丽亚姆·米尔扎哈尼是伊朗数学家，曾任斯坦福大学数学教授，研究几何与动力系统。她于2014年获得菲尔兹奖，成为该奖首位女性得主。其工作涉及曲面及其模空间，连接几何结构与动力学问题。她于2004年获得哈佛大学博士学位，并在2015年访问普林斯顿高等研究院。","story":"米尔扎哈尼的研究对象包括曲面及其模空间。这里的曲面可以帮助理解球面、环面和双曲几何对象，而模空间则为比较不同几何结构提供数学框架。斯坦福大学的获奖报道把她的贡献放在几何与动力系统的交叉领域，强调其成果对曲面研究的重要性。\n2014年，她作为斯坦福大学数学教授获得菲尔兹奖，成为这一奖项创设以来首位女性得主。这是一项针对数学成果的荣誉；理解她的工作，也需要看到定理与抽象结构之间的联系，而不只记住获奖身份。\n高等研究院的学者档案补充了她的学术经历：2004年获得哈佛大学博士学位，2015年秋以研究成员身份访问该院，并与阿列克斯·埃斯金、阿米尔·穆罕默迪合作研究轨道闭包等问题。上述资料勾勒出从博士训练、大学研究到跨机构合作的路径。本档案不沿用旧网页中关于她是唯一女性获奖者的时效性说法，也不推测她在研究过程中的私人感受。","achievements":["2014年获菲尔兹奖，成为首位女性得主。","任斯坦福大学数学教授，研究几何与动力系统。"],"facts":[{"claim":"数学家；2014年获菲尔兹奖，成为首位女性得主。","sourceUrls":["https://news.stanford.edu/stories/2014/08/stanfords-maryam-mirzakhani-wins-fields-medal"]},{"claim":"数学家；任斯坦福大学数学教授，研究几何与动力系统。","sourceUrls":["https://news.stanford.edu/stories/2014/08/stanfords-maryam-mirzakhani-wins-fields-medal"]}],"sources":[{"title":"Stanford：2014年菲尔兹奖报道","url":"https://news.stanford.edu/stories/2014/08/stanfords-maryam-mirzakhani-wins-fields-medal","checkedAt":"2026-11-09"},{"title":"IAS：学者档案","url":"https://www.ias.edu/scholars/maryam-mirzakhani","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":2014,"description":"数学家；2014年获菲尔兹奖，成为首位女性得主。","sourceUrls":["https://news.stanford.edu/stories/2014/08/stanfords-maryam-mirzakhani-wins-fields-medal"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('elizabeth-blackwell','elizabeth-blackwell','伊丽莎白·布莱克韦尔','Elizabeth Blackwell','verified','{"id":"elizabeth-blackwell","slug":"elizabeth-blackwell","nameZh":"伊丽莎白·布莱克韦尔","nameEn":"Elizabeth Blackwell","fields":["医学"],"regions":["英国","美国"],"occupation":"医生、医学教育倡导者","keywords":["医学","医生、医学教育倡导者"],"summary":"伊丽莎白·布莱克韦尔是出生于英国、在美国接受医学教育的医生。她于1849年从日内瓦医学院毕业，后来创办纽约妇女儿童医院，并参与建立其医学院。她也在英国推动女性医学教育，名字进入英国医生名册，其职业经历涉及临床服务、卫生教育与女性进入医学专业的机会。","story":"布莱克韦尔出生于英国布里斯托尔，1832年随家人迁往美国。霍巴特与威廉史密斯学院的传记保存了她接受医学教育的经过：她在申请阶段遭到多所学校拒绝，1847年进入日内瓦医学院，并于1849年1月23日毕业。\n获得学位之后，她继续从事医疗服务和教育建设。她创办纽约妇女儿童医院，并参与建立附属医学院。这些机构使她的经历不只是一项个人学位记录，也与女性接受专业训练、患者获得医疗服务的渠道相连。回到英国后，她参与创办国家健康协会，在英国第一所女性医学院任教，并成为首位进入英国医生名册的女性。\n学院资料还记载她推广预防医学、卫生和抗菌观念的工作。本档案依据校方档案整理可确认的求学、建院和教学经历。关于当年学生为什么投票同意录取她，来源自身列出了不同版本，因此这里不把某一种心理解释写成事实；也不补写她与同学、患者之间未经证实的对话。","achievements":["1849年1月23日从日内瓦医学院毕业。","创办纽约妇女儿童医院，并参与建立其医学院。"],"facts":[{"claim":"医生、医学教育倡导者；1849年1月23日从日内瓦医学院毕业。","sourceUrls":["https://www.hws.edu/about/history/elizabeth-blackwell/biography.aspx"]},{"claim":"医生、医学教育倡导者；创办纽约妇女儿童医院，并参与建立其医学院。","sourceUrls":["https://www.hws.edu/about/history/elizabeth-blackwell/biography.aspx"]}],"sources":[{"title":"Hobart and William Smith Colleges：Blackwell传记","url":"https://www.hws.edu/about/history/elizabeth-blackwell/biography.aspx","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1849,"description":"医生、医学教育倡导者；1849年1月23日从日内瓦医学院毕业。","sourceUrls":["https://www.hws.edu/about/history/elizabeth-blackwell/biography.aspx"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('billie-jean-king','billie-jean-king','比利·简·金','Billie Jean King','verified','{"id":"billie-jean-king","slug":"billie-jean-king","nameZh":"比利·简·金","nameEn":"Billie Jean King","fields":["体育"],"regions":["美国"],"occupation":"网球运动员","keywords":["体育","网球运动员"],"summary":"比利·简·金是美国网球运动员，也是体育平等倡导者。她在职业生涯中共获得39项大满贯冠军，包含单打、女双和混双项目。1973年，她推动成立女子网球协会并担任首任主席，同时争取男女同等奖金。她于1974年创办女子体育基金会，将竞技影响力延伸到女性参与体育的机会。","story":"比利·简·金出生于美国加利福尼亚州长滩，早年在当地公共球场练习网球。她的官方传记记录，1961年，她与凯伦·汉策·萨斯曼合作夺得温布尔登女双冠军；1966年，她又获得个人首个温布尔登单打冠军。此后，她的比赛成绩延伸到多个大满贯赛事。\n官方档案将她的39项大满贯冠军按不同赛事汇总，这一数字包括单打、女子双打和混合双打，不能被误写为39项单打冠军。1972年，她在美国、法国和温布尔登的大满贯比赛中取得单打冠军。竞技表现之外，她还持续参与职业网球组织建设和奖金平等倡议。\n1973年，她推动女子网球协会成立并担任首任主席，同年美国公开赛开始实行男女同等奖金。1974年，她创办女子体育基金会，并参与创建男女共同参赛的团体赛事。她的档案因此同时涉及比赛结果与体育制度建设。这里依据官方传记保留事件与年份，不把体育平等的变化归功于某个人独力完成，也不补写赛场上的内心独白。","achievements":["职业生涯获得39项大满贯冠军，含单打、女双和混双。","1973年推动成立女子网球协会并任首任主席。"],"facts":[{"claim":"网球运动员；职业生涯获得39项大满贯冠军，含单打、女双和混双。","sourceUrls":["https://www.billiejeanking.com/biography/"]},{"claim":"网球运动员；1973年推动成立女子网球协会并任首任主席。","sourceUrls":["https://www.billiejeanking.com/biography/"]}],"sources":[{"title":"Billie Jean King：官方传记","url":"https://www.billiejeanking.com/biography/","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1973,"description":"网球运动员；1973年推动成立女子网球协会并任首任主席。","sourceUrls":["https://www.billiejeanking.com/biography/"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('madam-cj-walker','madam-cj-walker','C·J·沃克夫人','Madam C. J. Walker','verified','{"id":"madam-cj-walker","slug":"madam-cj-walker","nameZh":"C·J·沃克夫人","nameEn":"Madam C. J. Walker","fields":["商业"],"regions":["美国"],"occupation":"企业家、教育者、慈善家","keywords":["商业","企业家、教育者、慈善家"],"summary":"C·J·沃克夫人原名萨拉·布里德洛夫，是美国非裔企业家、教育者和慈善家。她经营面向非裔消费者的护发与美容产品，通过邮购、代理销售和培训扩大业务。1908年，她在匹兹堡开设美容学校；1910年迁至印第安纳波利斯并正式建立制造公司，其企业史也反映了非裔女性的就业与经营活动。","story":"史密森尼的沃克收藏项目把个人经历、公司材料和二十世纪初的美国非裔美容文化联系起来。沃克原名萨拉·布里德洛夫，1905年迁往丹佛，曾为另一位美容业企业家安妮·特恩博·马龙担任销售代理。1906年结婚后，她使用沃克夫人的名称经营业务。\n她随后离开原公司，与丈夫通过邮购销售自己的护发产品。随着业务增长，企业不仅出售产品，也培训能够提供护发服务与进行销售的代理人。1908年，她将邮购业务移至匹兹堡，并开设以女儿命名的美容学校；1910年再次迁往印第安纳波利斯，正式建立制造公司。\n1913年，协助管理公司的女儿推动在哈莱姆设立分支，沃克于1916年前往当地生活。收藏项目保留的公司和代理人材料，为理解产品、培训及销售网络提供了线索。本档案强调这些具体的经营活动，不采用未经本批独立核对的财富排名，也不把影视作品中的场景、台词和竞争关系当作她本人的历史经历。","achievements":["1908年在匹兹堡开设Lelia美容学校，培训女性代理人。","1910年在印第安纳波利斯正式建立Madam C.J. Walker Manufacturing Company。"],"facts":[{"claim":"企业家、教育者、慈善家；1908年在匹兹堡开设Lelia美容学校，培训女性代理人。","sourceUrls":["https://transcription.si.edu/initiatives/madam-c-j-walker-collection"]},{"claim":"企业家、教育者、慈善家；1910年在印第安纳波利斯正式建立Madam C.J. Walker Manufacturing Company。","sourceUrls":["https://transcription.si.edu/initiatives/madam-c-j-walker-collection"]}],"sources":[{"title":"Smithsonian：Madam C. J. Walker Collection","url":"https://transcription.si.edu/initiatives/madam-c-j-walker-collection","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1908,"description":"企业家、教育者、慈善家；1908年在匹兹堡开设Lelia美容学校，培训女性代理人。","sourceUrls":["https://transcription.si.edu/initiatives/madam-c-j-walker-collection"]},{"year":1910,"description":"企业家、教育者、慈善家；1910年在印第安纳波利斯正式建立Madam C.J. Walker Manufacturing Company。","sourceUrls":["https://transcription.si.edu/initiatives/madam-c-j-walker-collection"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('toni-morrison','toni-morrison','托妮·莫里森','Toni Morrison','verified','{"id":"toni-morrison","slug":"toni-morrison","nameZh":"托妮·莫里森","nameEn":"Toni Morrison","fields":["文学"],"regions":["美国"],"occupation":"小说家、编辑、大学教师","keywords":["文学","小说家、编辑、大学教师"],"summary":"托妮·莫里森是美国小说家、编辑和大学教师，作品包括《最蓝的眼睛》《所罗门之歌》和《宠儿》。她于1988年凭《宠儿》获普利策奖，1993年获诺贝尔文学奖。1989年，她加入普林斯顿大学任人文学科教授，并创办普林斯顿艺术工作坊项目，促进学生与艺术家共同创作。","story":"莫里森的职业经历同时涉及出版、文学写作和大学教育。普林斯顿大学的学者档案记载，她在霍华德大学获得英语学士学位，在康奈尔大学取得美国文学硕士学位，进入普林斯顿之前曾在兰登书屋担任资深编辑，也曾在多所大学任教。\n她的小说作品包括《最蓝的眼睛》《秀拉》《所罗门之歌》和《宠儿》。1988年，《宠儿》获得普利策奖；1993年，她获得诺贝尔文学奖。这两项记录应当分别归于作品奖项和作家获奖经历，而不能把《宠儿》表述为单独获得诺贝尔奖的小说。\n1989年，莫里森加入普林斯顿大学，担任人文学科教授，并成为普林斯顿艺术工作坊项目的创始负责人。该项目将艺术家与学生聚集在工作坊环境中完成创作，为她的教学经历提供了具体例证。校方资料还列出儿童文学、散文和歌词等写作。本档案不把较早页面上的作品数量视为最终全集，也不依据小说人物推断作家的私人经历；这里记录的是机构档案能够支持的教育、出版和获奖脉络。","achievements":["1988年凭《宠儿》获得普利策奖。","1993年获得诺贝尔文学奖。"],"facts":[{"claim":"小说家、编辑、大学教师；1988年凭《宠儿》获得普利策奖。","sourceUrls":["https://aas.princeton.edu/people/toni-morrison"]},{"claim":"小说家、编辑、大学教师；1993年获得诺贝尔文学奖。","sourceUrls":["https://aas.princeton.edu/people/toni-morrison"]}],"sources":[{"title":"Princeton：Toni Morrison学者档案","url":"https://aas.princeton.edu/people/toni-morrison","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1988,"description":"小说家、编辑、大学教师；1988年凭《宠儿》获得普利策奖。","sourceUrls":["https://aas.princeton.edu/people/toni-morrison"]},{"year":1993,"description":"小说家、编辑、大学教师；1993年获得诺贝尔文学奖。","sourceUrls":["https://aas.princeton.edu/people/toni-morrison"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('frida-kahlo','frida-kahlo','弗里达·卡洛','Frida Kahlo','verified','{"id":"frida-kahlo","slug":"frida-kahlo","nameZh":"弗里达·卡洛","nameEn":"Frida Kahlo","fields":["艺术"],"regions":["墨西哥"],"occupation":"画家","keywords":["艺术","画家"],"summary":"弗里达·卡洛是墨西哥画家，以自画像及具有个人经历色彩的作品闻名。她在严重交通事故后的恢复期间开始油画创作，作品运用墨西哥民间艺术的色彩与形式。1938年，她在纽约朱利安·利维画廊举办首次个人展览。她也曾在墨西哥艺术学校任教，留下《两个弗里达》等作品。","story":"卡洛1907年出生于墨西哥城科约阿坎，故居后来成为弗里达·卡洛博物馆。博物馆传记记载，她在1925年遭遇严重交通事故，恢复期间开始绘画。美国国家女性艺术博物馆也记录了她在康复阶段转向油画创作的经历，并指出自画像与静物画在其作品中的位置。\n她的绘画与墨西哥民间艺术的鲜明色彩、平面化形式相关。1929年，她与壁画家迭戈·里维拉结婚，后来曾在美国和法国活动。1938年，她在纽约朱利安·利维画廊举办首次个人展览。与作品相连的生平资料，可以帮助读者理解展览和跨国艺术交流，却不能替代对画面本身的观察。\n故居博物馆还记载她在拉埃斯梅拉达艺术学校任教，并列出《两个弗里达》等作品。她去世后的声誉与艺术史研究、展览和出版活动持续相关。本档案保留可核对的创作、展览和教学事实，不用想象的痛苦独白解释每一幅画，也不复制作品图像；本批没有确认可供网站使用的图像许可，因此继续采用统一占位图。","achievements":["1938年在纽约朱利安·利维画廊举办首次个人展览。","在恢复期间开始油画创作，绘制自画像与静物画。"],"facts":[{"claim":"画家；1938年在纽约朱利安·利维画廊举办首次个人展览。","sourceUrls":["https://nmwa.org/art/artists/frida-kahlo/"]},{"claim":"画家；在恢复期间开始油画创作，绘制自画像与静物画。","sourceUrls":["https://nmwa.org/art/artists/frida-kahlo/"]}],"sources":[{"title":"NMWA：Frida Kahlo艺术家档案","url":"https://nmwa.org/art/artists/frida-kahlo/","checkedAt":"2026-11-09"},{"title":"Museo Frida Kahlo：英文传记PDF","url":"https://www.museofridakahlo.org.mx/wp/wp-content/uploads/2022/08/Biografias-Frida-Kahlo-ingles.pdf","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1938,"description":"画家；1938年在纽约朱利安·利维画廊举办首次个人展览。","sourceUrls":["https://nmwa.org/art/artists/frida-kahlo/"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('maria-montessori','maria-montessori','玛丽亚·蒙台梭利','Maria Montessori','verified','{"id":"maria-montessori","slug":"maria-montessori","nameZh":"玛丽亚·蒙台梭利","nameEn":"Maria Montessori","fields":["教育"],"regions":["意大利"],"occupation":"医生、教育家","keywords":["教育","医生、教育家"],"summary":"玛丽亚·蒙台梭利是意大利医生和教育家。她于1896年完成医学训练，随后把儿童观察与教育材料实验结合起来。1907年，她在罗马圣洛伦佐区开设第一所儿童之家；1909年举办教育培训课程，并将讲义整理成书。她的教育实践后来通过学校、培训与出版传播至多个国家。","story":"蒙台梭利1870年出生于意大利，后来在罗马学习自然科学与医学。国际蒙台梭利协会的传记记载，她于1896年成为意大利早期女性医生之一，并在医院及大学精神科研究环境中接触儿童。她随后将工作重心逐渐移向教育，试验教学材料，并记录儿童的反应。\n1907年1月6日，第一所儿童之家在罗马圣洛伦佐区开放。她将此前发展的一些教育材料带入新环境，通过观察儿童的活动，保留能够引起持续参与的材料。这段经历是她教育方法形成的重要实践背景，不能只理解为一套已经写成的规则被搬进教室。\n1909年，她举办首期培训课程，并将相关笔记整理成书；该书于1912年以英文出版。此后，不同国家出现了相关学校、协会和培训项目，她也通过旅行、课程和讲演传播教育方法。这里依据协会历史档案叙述医学教育、课堂观察和教师培训之间的联系，不把传记中的课堂效果推演成对所有儿童都成立的保证，也不添加未经记录的师生对话或个人动机。","achievements":["1896年完成医学训练，成为意大利早期女性医生之一。","1907年1月6日在罗马开设第一所儿童之家。"],"facts":[{"claim":"医生、教育家；1896年完成医学训练，成为意大利早期女性医生之一。","sourceUrls":["https://montessori-ami.org/node/1820"]},{"claim":"医生、教育家；1907年1月6日在罗马开设第一所儿童之家。","sourceUrls":["https://montessori-ami.org/node/1820"]}],"sources":[{"title":"AMI：Maria Montessori传记","url":"https://montessori-ami.org/node/1820","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1896,"description":"医生、教育家；1896年完成医学训练，成为意大利早期女性医生之一。","sourceUrls":["https://montessori-ami.org/node/1820"]},{"year":1907,"description":"医生、教育家；1907年1月6日在罗马开设第一所儿童之家。","sourceUrls":["https://montessori-ami.org/node/1820"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('wangari-maathai','wangari-maathai','旺加里·马塔伊','Wangari Maathai','verified','{"id":"wangari-maathai","slug":"wangari-maathai","nameZh":"旺加里·马塔伊","nameEn":"Wangari Maathai","fields":["公共事务"],"regions":["肯尼亚"],"occupation":"环境行动者、大学教师","keywords":["公共事务","环境行动者、大学教师"],"summary":"旺加里·马塔伊是肯尼亚环境行动者和大学教师，曾在内罗毕大学研究并教授兽医解剖学。她于1977年创立绿带运动，把环境保护与社区参与联系起来，回应乡村妇女面临的水源、食物和薪柴问题。2004年，她获得诺贝尔和平奖，其公共工作涉及生态保护、民主与社区赋权。","story":"马塔伊的学术训练始于生物科学。绿带运动的个人档案记载，她先后在美国获得学士与硕士学位，之后在德国和肯尼亚继续研究，1971年于内罗毕大学获得博士学位，并在该校教授兽医解剖学。她于1976年担任系主任，次年成为副教授。\n1977年，她在肯尼亚全国妇女理事会支持下创立绿带运动。组织历史说明，乡村妇女当时反映溪流水量减少、食物供应不稳，以及获取薪柴需要走更远的路。植树与社区参与由此成为回应生活需求和环境退化的具体行动，而非只有抽象环保口号。\n随着组织发展，相关工作延伸到社区教育、公共空间保护和环境正义。2004年，马塔伊获得诺贝尔和平奖，绿带运动也因此获得更广泛关注。本档案将学术职位、组织创立和公共行动分别记录，不把整个组织的长期成果归为个人单独完成，也不使用未经本批核对的植树总量。其人物形象采用统一占位图，来源网页上的照片未因可浏览而被视为可自由转载。","achievements":["1971年获内罗毕大学博士学位，并在该校教授兽医解剖学。","2004年获得诺贝尔和平奖。"],"facts":[{"claim":"环境行动者、大学教师；1971年获内罗毕大学博士学位，并在该校教授兽医解剖学。","sourceUrls":["https://www.greenbeltmovement.org/wangari-maathai/"]},{"claim":"环境行动者、大学教师；2004年获得诺贝尔和平奖。","sourceUrls":["https://www.greenbeltmovement.org/wangari-maathai/"]},{"claim":"1977年创立绿带运动。","sourceUrls":["https://www.greenbeltmovement.org/history/"]}],"sources":[{"title":"Green Belt Movement：Wangari Maathai档案","url":"https://www.greenbeltmovement.org/wangari-maathai/","checkedAt":"2026-11-09"},{"title":"Green Belt Movement：组织历史","url":"https://www.greenbeltmovement.org/history/","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1971,"description":"环境行动者、大学教师；1971年获内罗毕大学博士学位，并在该校教授兽医解剖学。","sourceUrls":["https://www.greenbeltmovement.org/wangari-maathai/"]},{"year":1977,"description":"1977年创立绿带运动。","sourceUrls":["https://www.greenbeltmovement.org/history/"]},{"year":2004,"description":"环境行动者、大学教师；2004年获得诺贝尔和平奖。","sourceUrls":["https://www.greenbeltmovement.org/wangari-maathai/"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('florence-nightingale','florence-nightingale','弗洛伦斯·南丁格尔','Florence Nightingale','verified','{"id":"florence-nightingale","slug":"florence-nightingale","nameZh":"弗洛伦斯·南丁格尔","nameEn":"Florence Nightingale","fields":["医学"],"regions":["英国"],"occupation":"护士、护理改革者","keywords":["医学","护士、护理改革者"],"summary":"弗洛伦斯·南丁格尔是英国护士和护理改革者。她在克里米亚战争期间组织伤病士兵护理，后来利用统计图表推动卫生改革。1860年，她在伦敦圣托马斯医院建立护理培训学校。她的工作涉及医院环境、护理教育和公共卫生，并通过著述与机构建设影响护理专业的发展。","story":"南丁格尔的护理工作与战争医疗和医院改革相连。伦敦南丁格尔博物馆记载，1854年，她率护士团队前往斯库塔里，组织军医院护理，改善食物、床位、物资与清洁条件。战地服务是她经历的重要部分，但她的工作也延伸到战争结束后的政策与专业教育。\n返回英国后，她利用统计图表说明疾病造成的死亡问题，参与推动军队卫生状况调查，并持续撰写有关医院规划、护理和卫生的材料。博物馆将统计传播与制度改革联系起来，这比单独记住提灯形象更能呈现她所从事的具体工作。\n1860年，利用公众捐助形成的基金，护理培训学校在圣托马斯医院建立。伦敦国王学院的学院历史也确认了这一时间与学校传承，首批护士同年开始训练。后来的培训与学校建设将个人经验转化为可延续的专业实践。本档案不采用未经本批核对的死亡率降幅，也不把复杂的医院改良归因于单一措施；所写内容限于已读取的博物馆与大学历史资料。","achievements":["1860年在伦敦圣托马斯医院建立护理培训学校。","使用统计图表说明军队健康问题并推动医疗卫生改革。"],"facts":[{"claim":"1860年在伦敦圣托马斯医院建立护理培训学校。","sourceUrls":["https://www.florence-nightingale.co.uk/about-florence-nightingale/"]},{"claim":"使用统计图表说明军队健康问题并推动医疗卫生改革。","sourceUrls":["https://www.florence-nightingale.co.uk/about-florence-nightingale/"]}],"sources":[{"title":"Florence Nightingale Museum：人物传记","url":"https://www.florence-nightingale.co.uk/about-florence-nightingale/","checkedAt":"2026-11-09"},{"title":"King’s College London：护理学院历史","url":"https://www.kcl.ac.uk/nmpc/about-us/history","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1860,"description":"1860年在伦敦圣托马斯医院建立护理培训学校。","sourceUrls":["https://www.florence-nightingale.co.uk/about-florence-nightingale/"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('wilma-rudolph','wilma-rudolph','威尔玛·鲁道夫','Wilma Rudolph','verified','{"id":"wilma-rudolph","slug":"wilma-rudolph","nameZh":"威尔玛·鲁道夫","nameEn":"Wilma Rudolph","fields":["体育"],"regions":["美国"],"occupation":"田径短跑运动员","keywords":["体育","田径短跑运动员"],"summary":"威尔玛·鲁道夫是美国田径短跑运动员。她在1956年墨尔本奥运会获得女子4×100米接力铜牌，1960年罗马奥运会夺得女子100米、200米和4×100米接力三枚金牌。她在田纳西州立大学训练，退役后参与青少年工作，并通过基金会与教练岗位继续服务体育。","story":"鲁道夫的竞技经历可以从两届奥运会的项目记录展开。美国田径协会档案记载，她十六岁时入选奥运队，1956年在墨尔本随美国队获得女子4×100米接力铜牌。她后来进入田纳西州立大学，接受埃德·坦普尔指导，在短跑项目继续训练和比赛。\n1960年罗马奥运会，她分别夺得女子100米、200米和4×100米接力金牌，成为首位在同届奥运会赢得三枚金牌的美国女性。三个项目包含个人短跑与团队接力，因此记录应当保留项目区别，也保留接力队友共同完成比赛的事实，不能将三项成绩都写成个人赛冠军。\n协会资料还列出她获得的美国业余体育荣誉，以及退役后的青少年服务。她参与以自己名字命名的基金会，后来担任德波大学田径教练，并于1983年入选美国奥林匹克名人堂。这里将比赛、训练与后续职业分开记录，不将童年疾病经历加工成虚构的康复场景，也不编造教练和家人的鼓励对白；人物形象仍使用统一占位图。","achievements":["1956年获奥运会女子4×100米接力铜牌。","1960年罗马奥运会获女子100米、200米和4×100米接力金牌。"],"facts":[{"claim":"1956年获奥运会女子4×100米接力铜牌。","sourceUrls":["https://www.usatf.org/athlete-bios/wilma-rudolph"]},{"claim":"1960年罗马奥运会获女子100米、200米和4×100米接力金牌。","sourceUrls":["https://www.usatf.org/athlete-bios/wilma-rudolph"]}],"sources":[{"title":"USA Track & Field：Wilma Rudolph运动员档案","url":"https://www.usatf.org/athlete-bios/wilma-rudolph","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1956,"description":"1956年获奥运会女子4×100米接力铜牌。","sourceUrls":["https://www.usatf.org/athlete-bios/wilma-rudolph"]},{"year":1960,"description":"1960年罗马奥运会获女子100米、200米和4×100米接力金牌。","sourceUrls":["https://www.usatf.org/athlete-bios/wilma-rudolph"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('estee-lauder','estee-lauder','雅诗·兰黛','Estée Lauder','verified','{"id":"estee-lauder","slug":"estee-lauder","nameZh":"雅诗·兰黛","nameEn":"Estée Lauder","fields":["商业"],"regions":["美国"],"occupation":"企业家、化妆品公司共同创办人","keywords":["商业","企业家、化妆品公司共同创办人"],"summary":"雅诗·兰黛是美国企业家，1946年与约瑟夫·兰黛共同创办化妆品公司。她早期在美容院示范并销售护肤和彩妆产品，1947年取得萨克斯第五大道百货的重要订单。其经营工作包括产品演示、顾客试用、销售培训及百货渠道拓展，她于1995年退休，2004年去世。","story":"雅诗·兰黛的商业经历由产品制作与面对面销售逐步展开。公司创办人档案记载，她年轻时从从事化学工作的舅舅那里学习制作护肤霜，后来在美容院向顾客示范护肤和彩妆产品。这些经历提供了她进入美容行业的背景，但不能据此推断任何产品的实际医学效果。\n1946年，她与丈夫约瑟夫共同创办公司，次年取得来自萨克斯第五大道百货的重要订单。公司历史还记录，她通过赠送试用品、在柜台演示和培训美容顾问拓展销售，并前往不同城市接触商店采购人员及消费者。这里将这些做法视为企业经营活动，不把品牌宣传中的天赋或成功评价当作可独立验证的心理事实。\n随着家族成员加入，企业逐渐发展为多品牌公司。创办人档案记载她于1995年退休、2004年去世。本批资料集中于创办年份、早期渠道与销售实践，不采用当前营收、员工人数或品牌规模作为她个人任职时期的成绩，也不复制官网上的广告语。人物记录注明公司自述来源的性质，图片继续使用原创占位图。","achievements":["1946年与约瑟夫·兰黛共同创办公司。","1947年取得萨克斯第五大道百货的重要产品订单。"],"facts":[{"claim":"1946年与约瑟夫·兰黛共同创办公司。","sourceUrls":["https://www.elcompanies.com/en/who-we-are/our-heritage/our-founder"]},{"claim":"1947年取得萨克斯第五大道百货的重要产品订单。","sourceUrls":["https://www.elcompanies.com/en/who-we-are/our-heritage/our-founder"]}],"sources":[{"title":"The Estée Lauder Companies：创办人档案","url":"https://www.elcompanies.com/en/who-we-are/our-heritage/our-founder","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1946,"description":"1946年与约瑟夫·兰黛共同创办公司。","sourceUrls":["https://www.elcompanies.com/en/who-we-are/our-heritage/our-founder"]},{"year":1947,"description":"1947年取得萨克斯第五大道百货的重要产品订单。","sourceUrls":["https://www.elcompanies.com/en/who-we-are/our-heritage/our-founder"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('jane-austen','jane-austen','简·奥斯汀','Jane Austen','verified','{"id":"jane-austen","slug":"jane-austen","nameZh":"简·奥斯汀","nameEn":"Jane Austen","fields":["文学"],"regions":["英国"],"occupation":"小说家","keywords":["文学","小说家"],"summary":"简·奥斯汀是英国小说家，1775年出生于汉普郡。她的《理智与情感》于1811年出版，《傲慢与偏见》于1813年出版。1809年迁居乔顿后，她修订早期作品并继续创作。《诺桑觉寺》和《劝导》在她去世后出版，留下的少年习作与书信也成为理解其写作历程的重要材料。","story":"奥斯汀成长于汉普郡的一个牧师家庭，少年时期就为家人和朋友写故事、片段与戏仿作品。故居博物馆介绍，这些早期手稿保存在不同笔记本中，显示她在正式出版小说之前已经持续尝试叙事与语言。她的写作并非从第一部书出版时才开始。\n1809年，她与母亲、姐姐及友人迁至乔顿，随后修订早期作品。1811年，《理智与情感》出版，书上未署她的姓名；1813年，《傲慢与偏见》问世。时间线把作品初稿、改写与出版分开记录，因此本档案也避免把一个出版年份当作整部小说完成的唯一时间。\n此后，她继续创作《曼斯菲尔德庄园》《爱玛》和后来的《劝导》等作品。1817年，她迁往温彻斯特就医并去世，《诺桑觉寺》和《劝导》在同年晚些时候出版。故居资料指出，她在巴斯时期写作变化的原因仍有推测成分，因此这里不把失落、恋爱或居住感受写成确定动机，也不根据小说情节反推作家的私人经历。","achievements":["《理智与情感》于1811年出版，未署作者姓名。","《傲慢与偏见》于1813年出版。"],"facts":[{"claim":"《理智与情感》于1811年出版，未署作者姓名。","sourceUrls":["https://janeaustens.house/jane-austen/timeline/"]},{"claim":"《傲慢与偏见》于1813年出版。","sourceUrls":["https://janeaustens.house/jane-austen/timeline/"]}],"sources":[{"title":"Jane Austen’s House：生平时间线","url":"https://janeaustens.house/jane-austen/timeline/","checkedAt":"2026-11-09"},{"title":"Jane Austen’s House：人物传记","url":"https://janeaustens.house/jane-austen/jane-austen-a-life/","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1811,"description":"《理智与情感》于1811年出版，未署作者姓名。","sourceUrls":["https://janeaustens.house/jane-austen/timeline/"]},{"year":1813,"description":"《傲慢与偏见》于1813年出版。","sourceUrls":["https://janeaustens.house/jane-austen/timeline/"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('georgia-okeeffe','georgia-okeeffe','乔治娅·欧姬芙','Georgia O’Keeffe','verified','{"id":"georgia-okeeffe","slug":"georgia-okeeffe","nameZh":"乔治娅·欧姬芙","nameEn":"Georgia O’Keeffe","fields":["艺术"],"regions":["美国"],"occupation":"画家","keywords":["艺术","画家"],"summary":"乔治娅·欧姬芙是美国画家，以抽象作品、花卉、纽约建筑与新墨西哥景观绘画闻名。1916年，阿尔弗雷德·施蒂格利茨首次展出她的作品。她于1929年前往新墨西哥北部，此后多次在那里生活与创作，并于1949年定居。她的艺术生涯跨越不同地区、媒介和观察主题。","story":"欧姬芙出生于美国威斯康星州，曾在芝加哥艺术学院和纽约艺术学生联盟学习。欧姬芙博物馆的传记记载，她后来接触阿瑟·韦斯利·道的艺术观念，并在西得克萨斯任教期间尝试抽象炭笔画。这些作品显示了她从传统绘画训练转向新的形式实验。\n她将部分画作寄给纽约的朋友，朋友又将作品介绍给施蒂格利茨，后者于1916年首次展出她的作品。到二十世纪二十年代中期，她已因纽约摩天楼与花卉画受到关注。她的主题并不只有花朵，也涉及城市、抽象结构以及不同地区的景观。\n1929年，她开始前往新墨西哥北部，之后多年在当地度过夏季并工作，1949年在那里定居。后来旅行与空中视角又带来新的绘画题材。博物馆资料也记载她晚年在视力受损后借助他人协助继续创作。本档案不把所有作品解释为单一象征，也不增加未经记录的创作独白；作品及肖像的网页展示未被视为转载授权，因此不下载或公开使用这些图像。","achievements":["1916年由施蒂格利茨首次展出作品。","1929年前往新墨西哥北部，1949年在当地定居。"],"facts":[{"claim":"1916年由施蒂格利茨首次展出作品。","sourceUrls":["https://www.okeeffemuseum.org/about-georgia-okeeffe/"]},{"claim":"1929年前往新墨西哥北部，1949年在当地定居。","sourceUrls":["https://www.okeeffemuseum.org/about-georgia-okeeffe/"]}],"sources":[{"title":"Georgia O’Keeffe Museum：艺术家传记","url":"https://www.okeeffemuseum.org/about-georgia-okeeffe/","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1916,"description":"1916年由施蒂格利茨首次展出作品。","sourceUrls":["https://www.okeeffemuseum.org/about-georgia-okeeffe/"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('malala-yousafzai','malala-yousafzai','马拉拉·优素福扎伊','Malala Yousafzai','verified','{"id":"malala-yousafzai","slug":"malala-yousafzai","nameZh":"马拉拉·优素福扎伊","nameEn":"Malala Yousafzai","fields":["教育"],"regions":["巴基斯坦","英国"],"occupation":"女童教育倡导者","keywords":["教育","女童教育倡导者"],"summary":"马拉拉·优素福扎伊出生于巴基斯坦，是女童教育倡导者。她曾为BBC乌尔都语博客记录经历，并公开支持女孩上学的权利。2013年，她在联合国发表教育倡议演讲；2014年获诺贝尔和平奖。她与父亲共同建立马拉拉基金，后来在牛津大学学习，并于2020年毕业。","story":"马拉拉出生于巴基斯坦明戈拉，父亲在当地从事教育工作。马拉拉基金的公开生平介绍，她在斯瓦特地区女孩受教育受到限制时，公开倡导学习权利，并为BBC乌尔都语博客记录自己的经历。这些是她早期参与公共议题的有据记录。\n2012年，她在放学途中遭枪击，随后在英国接受治疗和康复。这里保留事件及其对求学路径的影响，不描写没有来源的现场对白或身体感受。2013年7月12日，她在联合国发言，呼吁儿童获得教育机会，并与父亲共同建立马拉拉基金。\n2014年，她获得诺贝尔和平奖。此后的基金工作包括与推动女童教育的组织和行动者合作，通过倡议和资助支持教育权利。她于2017年开始在牛津大学学习哲学、政治与经济，2020年毕业。她的档案因此同时包含倡议工作和继续受教育的经历，不把组织整体成果写成个人独力完成。基金页面的周年标注存在需要进一步厘清的时间口径，本批未使用周年数字推算成立日期。","achievements":["2013年7月12日在联合国呼吁儿童获得教育机会。","2014年获得诺贝尔和平奖。"],"facts":[{"claim":"2013年7月12日在联合国呼吁儿童获得教育机会。","sourceUrls":["https://malala.org/malalas-story"]},{"claim":"2014年获得诺贝尔和平奖。","sourceUrls":["https://malala.org/malalas-story"]}],"sources":[{"title":"Malala Fund：Malala’s Story","url":"https://malala.org/malalas-story","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":2013,"description":"2013年7月12日在联合国呼吁儿童获得教育机会。","sourceUrls":["https://malala.org/malalas-story"]},{"year":2014,"description":"2014年获得诺贝尔和平奖。","sourceUrls":["https://malala.org/malalas-story"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('eleanor-roosevelt','eleanor-roosevelt','埃莉诺·罗斯福','Eleanor Roosevelt','verified','{"id":"eleanor-roosevelt","slug":"eleanor-roosevelt","nameZh":"埃莉诺·罗斯福","nameEn":"Eleanor Roosevelt","fields":["公共事务"],"regions":["美国"],"occupation":"公共事务活动家、联合国代表、作家","keywords":["公共事务","公共事务活动家、联合国代表、作家"],"summary":"埃莉诺·罗斯福是美国公共事务活动家、联合国代表和作家，曾任美国第一夫人。1945年，她受杜鲁门任命加入联合国工作，后来担任人权委员会主席，参与推动《世界人权宣言》起草和通过。她还通过专栏、演讲与社会服务参与公共讨论，其活动涉及人权、劳动和女性处境。","story":"埃莉诺·罗斯福早年在纽约参与社会服务并从事教学。罗斯福总统图书馆的传记记录，她在第一夫人任内走访救济项目、工作场所和社区，了解生活与劳动状况，并通过公共活动表达对贫困者和少数群体权益的关注。这些活动构成她公共生涯的一部分。\n1945年，她在丈夫去世后继续参与公共事务，受杜鲁门任命进入联合国代表团。她担任人权委员会主席，参与《世界人权宣言》的起草和推动工作。1948年12月10日，宣言由联合国大会通过。这是多国代表共同完成的过程，不能把整份宣言归为某一个人单独撰写。\n她也长期撰写《我的一天》专栏，并通过演讲、广播与电视参与社会讨论。1961年，她再次获任联合国代表，并担任总统妇女地位委员会主席。这里依据图书馆资料记录公开职位与活动，不使用虚构的家庭谈话解释政策立场。传记正文与时间线对退出代表团的年份口径不同，本批不采用该具体年份，避免把尚未厘清的时间差写入人物资料。","achievements":["1945年受杜鲁门任命担任美国驻联合国代表。","担任人权委员会主席，参与推动1948年《世界人权宣言》。"],"facts":[{"claim":"1945年受杜鲁门任命担任美国驻联合国代表。","sourceUrls":["https://www.fdrlibrary.org/er-biography"]},{"claim":"担任人权委员会主席，参与推动1948年《世界人权宣言》。","sourceUrls":["https://www.fdrlibrary.org/er-biography"]}],"sources":[{"title":"FDR Presidential Library：Eleanor Roosevelt传记","url":"https://www.fdrlibrary.org/er-biography","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1945,"description":"1945年受杜鲁门任命担任美国驻联合国代表。","sourceUrls":["https://www.fdrlibrary.org/er-biography"]},{"year":1948,"description":"担任人权委员会主席，参与推动1948年《世界人权宣言》。","sourceUrls":["https://www.fdrlibrary.org/er-biography"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('mae-jemison','mae-jemison','梅·杰米森','Mae Jemison','verified','{"id":"mae-jemison","slug":"mae-jemison","nameZh":"梅·杰米森","nameEn":"Mae Jemison","fields":["探索"],"regions":["美国"],"occupation":"医生、工程师、宇航员","keywords":["探索","医生、工程师、宇航员"],"summary":"梅·杰米森是美国医生、工程师和宇航员。她于1977年完成斯坦福大学化学工程学位，1981年取得康奈尔大学医学学位，曾在西非担任和平队医疗官。1987年入选NASA宇航员计划，1992年执行STS-47任务，成为首位进入太空的非裔美国女性，并参与空间生命科学实验。","story":"杰米森的教育与职业经历横跨工程、医学和航天。NASA官方履历记载，她于1977年从斯坦福大学取得化学工程学位，1981年在康奈尔大学取得医学学位，之后完成临床实习并从事全科医疗。1983至1985年，她在塞拉利昂和利比里亚担任和平队区域医疗官。\n这项工作包括医疗服务、药房与实验室监督、人员培训和公共卫生相关事务。回到美国后，她继续行医并学习工程课程，1987年入选NASA宇航员计划。其技术任务涉及发射支持和航天飞机软件验证等工作，显示宇航员经历并不只有实际升空的几天。\n1992年9月12日至20日，她作为科学任务专家执行STS-47空间实验室任务，参与美日合作的生命科学与材料实验，并担任骨细胞研究实验的共同研究者。NASA另一篇人物说明确认她是首位进入太空的非裔美国女性。她于1993年离开NASA。本批使用的履历版本截至1993年，不将其中职务误写为现职，也不根据职业跨度推测个人动机或补写训练场景。","achievements":["1981年取得康奈尔大学医学学位。","1992年9月12日至20日作为科学任务专家执行STS-47任务。"],"facts":[{"claim":"1981年取得康奈尔大学医学学位。","sourceUrls":["https://www.nasa.gov/wp-content/uploads/2019/09/jemison_mae.pdf"]},{"claim":"1992年9月12日至20日作为科学任务专家执行STS-47任务。","sourceUrls":["https://www.nasa.gov/wp-content/uploads/2019/09/jemison_mae.pdf"]}],"sources":[{"title":"NASA：Mae C. Jemison官方履历PDF","url":"https://www.nasa.gov/wp-content/uploads/2019/09/jemison_mae.pdf","checkedAt":"2026-11-09"},{"title":"NASA：首位进入太空的非裔美国女性","url":"https://www.nasa.gov/image-article/mae-jemison-first-african-american-woman-space/","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1981,"description":"1981年取得康奈尔大学医学学位。","sourceUrls":["https://www.nasa.gov/wp-content/uploads/2019/09/jemison_mae.pdf"]},{"year":1992,"description":"1992年9月12日至20日作为科学任务专家执行STS-47任务。","sourceUrls":["https://www.nasa.gov/wp-content/uploads/2019/09/jemison_mae.pdf"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('virginia-apgar','virginia-apgar','弗吉尼娅·阿普加','Virginia Apgar','verified','{"id":"virginia-apgar","slug":"virginia-apgar","nameZh":"弗吉尼娅·阿普加","nameEn":"Virginia Apgar","fields":["医学"],"regions":["美国"],"occupation":"麻醉科医生、医学研究者","keywords":["医学","麻醉科医生、医学研究者"],"summary":"弗吉尼娅·阿普加是美国麻醉科医生和医学研究者，1933年毕业于哥伦比亚大学医学院。她于1952年提出评估新生儿状况的阿普加评分，1953年发表相关方法。她在1949年成为该医学院首位女性正教授，后来参与出生缺陷研究与公共卫生倡议，推动对新生儿健康的关注。","story":"阿普加1933年从哥伦比亚大学医学院毕业，早期接受外科训练，随后转向麻醉学。哥伦比亚医学中心与美国国家医学图书馆的档案记载，她于1938年回到哥伦比亚负责麻醉部门，在这一专业逐渐制度化的过程中参与教学和临床工作。1949年，她成为该医学院首位女性正教授。\n她在产科麻醉实践中关注新生儿出生后的状态，提出一种按照肤色、心率、反射、肌张力和呼吸进行观察的评分方法。该方法于1952年在会议上介绍，1953年正式发表。这里区分提出与发表时间，不把校方某些简略时间线中的年份口径直接混用。\n1959年离开哥伦比亚后，她参与March of Dimes有关出生缺陷的研究项目，并取得公共卫生硕士学位，继续通过写作和公共活动关注婴儿健康。人物故事呈现的是临床观察、标准化记录和公共卫生工作的联系；它不提供个体诊断建议，也不将评分效果夸大为对所有新生儿结局的保证，未使用未经独立核对的挽救生命数量。","achievements":["1952年介绍阿普加评分，1953年发表。","1949年成为哥伦比亚大学医学院首位女性正教授。"],"facts":[{"claim":"1952年介绍阿普加评分，1953年发表。","sourceUrls":["https://www.cuimc.columbia.edu/news/virginia-apgars-legacy-continues-50-years-after-her-death"]},{"claim":"1949年成为哥伦比亚大学医学院首位女性正教授。","sourceUrls":["https://www.cuimc.columbia.edu/news/virginia-apgars-legacy-continues-50-years-after-her-death"]}],"sources":[{"title":"Columbia CUIMC：Virginia Apgar研究遗产","url":"https://www.cuimc.columbia.edu/news/virginia-apgars-legacy-continues-50-years-after-her-death","checkedAt":"2026-11-09"},{"title":"NLM：Virginia Apgar传记","url":"https://www.nlm.nih.gov/exhibition/changing-the-face-of-medicine/physicians/biography_virginia_apgar.html","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1949,"description":"1949年成为哥伦比亚大学医学院首位女性正教授。","sourceUrls":["https://www.cuimc.columbia.edu/news/virginia-apgars-legacy-continues-50-years-after-her-death"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('jackie-joyner-kersee','jackie-joyner-kersee','杰姬·乔伊纳-克西','Jackie Joyner-Kersee','verified','{"id":"jackie-joyner-kersee","slug":"jackie-joyner-kersee","nameZh":"杰姬·乔伊纳-克西","nameEn":"Jackie Joyner-Kersee","fields":["体育"],"regions":["美国"],"occupation":"田径运动员","keywords":["体育","田径运动员"],"summary":"杰姬·乔伊纳-克西是美国田径运动员，主要参加七项全能和跳远。她在1988年首尔奥运会夺得两项金牌，并在七项全能比赛取得7291分。1992年，她在巴塞罗那卫冕七项全能冠军。她曾在加利福尼亚大学洛杉矶分校参加田径与篮球，退役后参与青少年教育和公益活动。","story":"乔伊纳-克西出生于美国伊利诺伊州东圣路易斯，后来进入加利福尼亚大学洛杉矶分校，在田径和篮球项目训练与比赛。她的官方档案记录，1984年洛杉矶奥运会，她获得七项全能银牌。七项全能需要在多个田径项目中累积积分，与单独的跳远比赛应分别记录。\n1988年首尔奥运会，她在七项全能取得7291分并夺冠，同时赢得跳远金牌。1992年巴塞罗那奥运会，她成功卫冕七项全能，并获得跳远铜牌；1996年亚特兰大奥运会，她又取得跳远铜牌。这些具体的项目与年份，能够比笼统的冠军数量更清楚地呈现其竞技轨迹。\n职业经历之外，官方资料还记录了她1997年出版自传，以及参与青少年教育、健康和公益活动的工作。本档案只将1988年的积分写为当届成绩，不依据旧网页中仍然保持的说法断言今天的纪录状态；也不把个人网站中的最高、最伟大等评价写成事实。人物故事依据公开比赛记录整理，未添加训练时的对话、动机或身体感受。","achievements":["1988年首尔奥运会获七项全能和跳远金牌，七项全能成绩7291分。","1992年巴塞罗那奥运会卫冕七项全能冠军。"],"facts":[{"claim":"1988年首尔奥运会获七项全能和跳远金牌，七项全能成绩7291分。","sourceUrls":["https://www.jackiejoynerkersee.com/about/"]},{"claim":"1992年巴塞罗那奥运会卫冕七项全能冠军。","sourceUrls":["https://www.jackiejoynerkersee.com/about/"]}],"sources":[{"title":"Jackie Joyner-Kersee：官方人物与比赛档案","url":"https://www.jackiejoynerkersee.com/about/","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1988,"description":"1988年首尔奥运会获七项全能和跳远金牌，七项全能成绩7291分。","sourceUrls":["https://www.jackiejoynerkersee.com/about/"]},{"year":1992,"description":"1992年巴塞罗那奥运会卫冕七项全能冠军。","sourceUrls":["https://www.jackiejoynerkersee.com/about/"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('mary-kay-ash','mary-kay-ash','玫琳凯·艾施','Mary Kay Ash','verified','{"id":"mary-kay-ash","slug":"mary-kay-ash","nameZh":"玫琳凯·艾施","nameEn":"Mary Kay Ash","fields":["商业"],"regions":["美国"],"occupation":"企业家","keywords":["商业","企业家"],"summary":"玫琳凯·艾施是美国企业家，1963年9月13日与家人建立Beauty by Mary Kay，经营护肤和彩妆产品。公司档案记录了早期产品组合、销售激励与业务发展。她的自传《Mary Kay》于1981年出版。她的企业经历涉及美容产品销售、组织管理和女性从事商业活动的机会。","story":"艾施的商业档案主要来自她创办的公司，因此需要将企业历史事件与品牌评价分开阅读。公司时间线记载，她于1963年9月13日与子女建立Beauty by Mary Kay，推出包含护肤和彩妆的产品组合。这是本批可以确认的创办事件，不延伸为对所有销售参与者收入或职业结果的承诺。\n公司后来发展出以汽车等方式表彰销售表现的激励制度，时间线将首批凯迪拉克奖励列在1969年。1976年，公司在纽约证券交易所上市。对这类记录，本档案保留制度与事件，而不复述最先、最好或完全改变行业等宣传性的比较判断。\n1981年，她的自传《Mary Kay》由Harper and Row出版，使企业经历也通过个人写作进入公共传播。公司后来开设纪念博物馆保存相关历史。这里不采用官网对创业心理和家庭谈话的戏剧化复述，也不使用后来的员工或销售规模作为创办人当年的个人成绩。人物资料记录的是来源能够支持的创办、产品与出版脉络，图像仍使用统一占位图。","achievements":["1963年9月13日与家人建立Beauty by Mary Kay。","1981年出版自传《Mary Kay》。"],"facts":[{"claim":"1963年9月13日与家人建立Beauty by Mary Kay。","sourceUrls":["https://marykayglobal.com/our-founder-mary-kay-ash/"]},{"claim":"1981年出版自传《Mary Kay》。","sourceUrls":["https://marykayglobal.com/our-founder-mary-kay-ash/"]}],"sources":[{"title":"Mary Kay Global：Mary Kay Ash创办人时间线","url":"https://marykayglobal.com/our-founder-mary-kay-ash/","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1963,"description":"1963年9月13日与家人建立Beauty by Mary Kay。","sourceUrls":["https://marykayglobal.com/our-founder-mary-kay-ash/"]},{"year":1981,"description":"1981年出版自传《Mary Kay》。","sourceUrls":["https://marykayglobal.com/our-founder-mary-kay-ash/"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('maya-angelou','maya-angelou','玛雅·安吉洛','Maya Angelou','verified','{"id":"maya-angelou","slug":"maya-angelou","nameZh":"玛雅·安吉洛","nameEn":"Maya Angelou","fields":["文学"],"regions":["美国"],"occupation":"作家、诗人、表演者、教师","keywords":["文学","作家、诗人、表演者、教师"],"summary":"玛雅·安吉洛是美国作家、诗人、表演者和教师，原名玛格丽特·约翰逊。她于1969年出版自传《我知道笼中鸟为何歌唱》，后来继续撰写诗歌、散文和回忆录。2013年，她获得美国国家图书基金会文学贡献奖。她也曾从事舞台表演、新闻编辑及民权相关工作，创作跨越多种形式。","story":"安吉洛1928年出生于美国密苏里州，原名玛格丽特·约翰逊。美国国家图书基金会的传记将她介绍为作家、诗人、表演者和教师，而官方传记也记录了她的多重创作身份。这样的职业跨度提醒读者，不宜只用一本书或一种文学体裁概括其生涯。\n1969年，她出版自传《我知道笼中鸟为何歌唱》，后来继续以回忆录、诗歌、散文和儿童文学等形式写作。基金会档案还记载她在开罗与加纳从事新闻工作，参与舞台演出，并担任南方基督教领袖会议的北方协调员。这些公共经历与她的文学创作并存，但不能把作品里的每个场景直接当作无需核对的个人事实。\n2013年，她获得国家图书基金会的Literarian Award，同年出版另一部回忆录《Mom & Me & Mom》。这里记录可核对的出版与机构表彰，不采用页面中有待另行核对的总统就职朗诵年份，也不重复不同来源对自由勋章授予时间的混合口径。没有复制诗歌、采访或名言，故事使用独立中文转述。","achievements":["1969年出版自传《我知道笼中鸟为何歌唱》。","2013年获美国国家图书基金会Literarian Award。"],"facts":[{"claim":"1969年出版自传《我知道笼中鸟为何歌唱》。","sourceUrls":["https://www.nationalbook.org/people/dr-maya-angelou/"]},{"claim":"2013年获美国国家图书基金会Literarian Award。","sourceUrls":["https://www.nationalbook.org/people/dr-maya-angelou/"]}],"sources":[{"title":"National Book Foundation：Maya Angelou人物档案","url":"https://www.nationalbook.org/people/dr-maya-angelou/","checkedAt":"2026-11-09"},{"title":"Caged Bird Legacy：官方传记","url":"https://www.mayaangelou.com/biography/","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1969,"description":"1969年出版自传《我知道笼中鸟为何歌唱》。","sourceUrls":["https://www.nationalbook.org/people/dr-maya-angelou/"]},{"year":2013,"description":"2013年获美国国家图书基金会Literarian Award。","sourceUrls":["https://www.nationalbook.org/people/dr-maya-angelou/"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('yayoi-kusama','yayoi-kusama','草间弥生','Yayoi Kusama','verified','{"id":"yayoi-kusama","slug":"yayoi-kusama","nameZh":"草间弥生","nameEn":"Yayoi Kusama","fields":["艺术"],"regions":["日本","美国"],"occupation":"艺术家、小说家","keywords":["艺术","艺术家、小说家"],"summary":"草间弥生是日本艺术家和小说家，1929年出生于松本。她于1957年前往美国，在纽约开展网状绘画、软雕塑及使用镜面和灯光的装置创作。1973年返回日本后，她继续绘画、雕塑与文学写作。其作品常使用圆点、网格和重复形式，并通过大型装置与国际展览获得关注。","story":"草间弥生出生于日本松本，早年使用水彩、粉彩和油画等媒介。她的官方英文传记记载，1957年她前往美国，次年在纽约陆续展示网状绘画、软雕塑和结合镜面与灯光的装置。她的创作形式同时扩展到行为、服装、电影与出版活动。\n森美术馆的专题将《无限网》和软雕塑列为理解她早期工作的线索，说明重复、增殖和积累如何通过画面与物体进入空间。专题也展出她在1993年威尼斯双年展日本馆呈现的作品，显示她的艺术生涯经历了不同阶段的国际展示与重新评价。\n1973年返回日本后，她继续文学写作、户外雕塑和大型装置。2009年开始的《我永恒的灵魂》系列又纳入人物与植物形象。这里按机构和官方资料呈现媒介、作品与展览脉络，不将心理健康标签当作解释所有作品的唯一原因，也不采用未经本批充分核对的最新生命状态信息。作品图像与人物照片仍有版权，本批没有下载或转载，网站继续使用原创占位图。","achievements":["1957年前往美国，随后在纽约开展网状绘画、软雕塑及镜面装置创作。","1973年返回日本后继续小说、诗歌和装置创作。"],"facts":[{"claim":"1957年前往美国，随后在纽约开展网状绘画、软雕塑及镜面装置创作。","sourceUrls":["https://yayoi-kusama.jp/en/biography/"]},{"claim":"1973年返回日本后继续小说、诗歌和装置创作。","sourceUrls":["https://yayoi-kusama.jp/en/biography/"]}],"sources":[{"title":"Yayoi Kusama：官方英文传记","url":"https://yayoi-kusama.jp/en/biography/","checkedAt":"2026-11-09"},{"title":"Mori Art Museum：STARS艺术家专题","url":"https://www.mori.art.museum/en/exhibitions/stars/02/index.html","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1957,"description":"1957年前往美国，随后在纽约开展网状绘画、软雕塑及镜面装置创作。","sourceUrls":["https://yayoi-kusama.jp/en/biography/"]},{"year":1973,"description":"1973年返回日本后继续小说、诗歌和装置创作。","sourceUrls":["https://yayoi-kusama.jp/en/biography/"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('mary-mcleod-bethune','mary-mcleod-bethune','玛丽·麦克劳德·贝休恩','Mary McLeod Bethune','verified','{"id":"mary-mcleod-bethune","slug":"mary-mcleod-bethune","nameZh":"玛丽·麦克劳德·贝休恩","nameEn":"Mary McLeod Bethune","fields":["教育"],"regions":["美国"],"occupation":"教育家、民权活动家","keywords":["教育","教育家、民权活动家"],"summary":"玛丽·麦克劳德·贝休恩是美国教育家和民权活动家。她于1904年在佛罗里达州代托纳比奇创办面向非裔女孩的学校，该校后来与库克曼学院合并。1935年，她建立全国黑人妇女理事会并任首任主席。她也参与青年教育、就业及公共事务，推动非裔美国女性的组织与教育机会。","story":"贝休恩出生于美国南卡罗来纳州，接受教育后曾在佐治亚和南卡罗来纳的学校任教。美国国家公园管理局的历史资料记载，她后来迁往佛罗里达，1904年10月3日在代托纳比奇创办一所面向非裔女孩的学校。教育事业由此成为她长期公共工作的基础。\n学校在1923年与库克曼学院合并，后来发展为贝休恩—库克曼学院。她同时参与地方与全国女性组织，1924年当选全国有色妇女协会主席，在教育、健康和公民权议题上建立组织网络。1935年，她创办全国黑人妇女理事会并担任首任主席，将不同团体的行动连接起来。\n她随后还在全国青年管理局承担公共职务，关注非裔青年的教育与就业机会，并持续写作和开展社会倡议。本档案保留建校、机构合并和组织创立的具体事实，不采用来源中需要更广泛比较才能支持的首位大学女校长等绝对称谓，也不把组织整体成果写成个人单独完成。中文译名与英文全名一并保留，避免与其他姓Bethune的人物混淆。","achievements":["1904年10月3日在代托纳比奇创办面向非裔女孩的学校。","1935年12月5日创立全国黑人妇女理事会并任首任主席。"],"facts":[{"claim":"1904年10月3日在代托纳比奇创办面向非裔女孩的学校。","sourceUrls":["https://www.nps.gov/mamc/learn/historyculture/mary-mcleod-bethune.htm"]},{"claim":"1935年12月5日创立全国黑人妇女理事会并任首任主席。","sourceUrls":["https://www.nps.gov/mamc/learn/historyculture/mary-mcleod-bethune.htm"]}],"sources":[{"title":"NPS：Mary McLeod Bethune人物历史","url":"https://www.nps.gov/mamc/learn/historyculture/mary-mcleod-bethune.htm","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1904,"description":"1904年10月3日在代托纳比奇创办面向非裔女孩的学校。","sourceUrls":["https://www.nps.gov/mamc/learn/historyculture/mary-mcleod-bethune.htm"]},{"year":1935,"description":"1935年12月5日创立全国黑人妇女理事会并任首任主席。","sourceUrls":["https://www.nps.gov/mamc/learn/historyculture/mary-mcleod-bethune.htm"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('rosa-parks','rosa-parks','罗莎·帕克斯','Rosa Parks','verified','{"id":"rosa-parks","slug":"rosa-parks","nameZh":"罗莎·帕克斯","nameEn":"Rosa Parks","fields":["公共事务"],"regions":["美国"],"occupation":"民权活动家","keywords":["公共事务","民权活动家"],"summary":"罗莎·帕克斯是美国民权活动家，1943年加入蒙哥马利全国有色人种协进会并当选秘书。1955年12月1日，她因拒绝在公交车上让座而被捕，事件推动蒙哥马利公交抵制。她继续参与交通协调、筹款和民权倡议，后来迁居底特律，并于1987年创办青年与长者学习相关机构。","story":"帕克斯的公共行动早于1955年的公交事件。斯坦福大学金研究所的资料记载，她于1943年加入蒙哥马利的全国有色人种协进会并当选秘书，后来指导青年组织活动。把她只描述为偶然卷入事件的乘客，会遗漏其长期参与公民权工作的背景。\n1955年12月1日，她因拒绝在蒙哥马利公交车上向白人乘客让座而被捕。随后展开的公交抵制持续一年多，涉及大量居民、组织者与法律行动。抵制期间，她还协助协调接送、筹款并宣传相关组织。这里保留集体行动的规模和角色区别，不将制度改变归于一次个人行为独力完成。\n1957年，她迁往底特律，后来在国会议员约翰·科尼尔斯的办公室工作，直到1988年退休。1987年，她创办罗莎与雷蒙德·帕克斯自我发展研究所，为青年与长者提供学习和领导力机会。本档案不复写自传中的长段引文，也不添加公交车内的对白或私人感受；研究依据大学机构档案，并保留原先国会图书馆页面访问失败的记录。","achievements":["1943年加入蒙哥马利NAACP并当选秘书。","1955年12月1日因拒绝在蒙哥马利公交车上让座而被捕。"],"facts":[{"claim":"1943年加入蒙哥马利NAACP并当选秘书。","sourceUrls":["https://kinginstitute.stanford.edu/parks-rosa"]},{"claim":"1955年12月1日因拒绝在蒙哥马利公交车上让座而被捕。","sourceUrls":["https://kinginstitute.stanford.edu/parks-rosa"]}],"sources":[{"title":"Stanford King Institute：Rosa Parks人物档案","url":"https://kinginstitute.stanford.edu/parks-rosa","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1943,"description":"1943年加入蒙哥马利NAACP并当选秘书。","sourceUrls":["https://kinginstitute.stanford.edu/parks-rosa"]},{"year":1955,"description":"1955年12月1日因拒绝在蒙哥马利公交车上让座而被捕。","sourceUrls":["https://kinginstitute.stanford.edu/parks-rosa"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('valentina-tereshkova','valentina-tereshkova','瓦莲京娜·捷列什科娃','Valentina Tereshkova','verified','{"id":"valentina-tereshkova","slug":"valentina-tereshkova","nameZh":"瓦莲京娜·捷列什科娃","nameEn":"Valentina Tereshkova","fields":["探索"],"regions":["苏联","俄罗斯"],"occupation":"宇航员","keywords":["探索","宇航员"],"summary":"瓦莲京娜·捷列什科娃是苏联宇航员，入选前曾从事纺织工作并参加业余跳伞。她于1963年6月16日乘东方六号升空，成为首位进入太空的女性。任务持续近三天，绕地球飞行48圈。她在飞行中记录身体反应并拍摄地球，是早期载人航天探索中具有历史意义的人物。","story":"捷列什科娃出生于俄罗斯雅罗斯拉夫尔地区，成为宇航员之前是纺织工人，也参加业余跳伞。欧洲航天局的历史资料记载，她于1962年入选女性宇航员训练队，随后接受失重飞行、离心机、隔离及跳伞等训练。跳伞经验与训练构成了她进入东方号计划的职业背景。\n1963年6月16日，她乘东方六号升空，成为世界首位进入太空的女性。她的任务与比科夫斯基驾驶的东方五号处在同一时期，但并非两人乘坐同一飞船。飞行期间，她维护日志、记录身体对太空环境的反应，并拍摄地球与地平线。\n任务持续近三天，NASA的科普档案记载东方六号绕地球48圈。两份机构资料对精确飞行时长和训练队人数的表述并不完全相同，因此本档案只采用近三天这一概括，不填入未经进一步核对的小时分钟数。人物故事聚焦选拔、训练与任务事实，不将早期航天纪录扩展成对其后来所有公共立场的评价，也不编造座舱内的对话与心理体验。","achievements":["1963年6月16日乘东方六号升空，成为首位进入太空的女性。","飞行持续近三天，并记录身体反应与拍摄地球。"],"facts":[{"claim":"1963年6月16日乘东方六号升空，成为首位进入太空的女性。","sourceUrls":["https://www.esa.int/articles/about-us/who-we-are/history/first-woman-in-space-valentina"]},{"claim":"飞行持续近三天，并记录身体反应与拍摄地球。","sourceUrls":["https://www.esa.int/articles/about-us/who-we-are/history/first-woman-in-space-valentina"]},{"claim":"东方六号绕地球48圈。","sourceUrls":["https://starchild.gsfc.nasa.gov/docs/StarChild/whos_who_level2/tereshkova.html"]}],"sources":[{"title":"ESA：First woman in space历史档案","url":"https://www.esa.int/articles/about-us/who-we-are/history/first-woman-in-space-valentina","checkedAt":"2026-11-09"},{"title":"NASA StarChild：Valentina Tereshkova","url":"https://starchild.gsfc.nasa.gov/docs/StarChild/whos_who_level2/tereshkova.html","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1963,"description":"1963年6月16日乘东方六号升空，成为首位进入太空的女性。","sourceUrls":["https://www.esa.int/articles/about-us/who-we-are/history/first-woman-in-space-valentina"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('gertrude-elion','gertrude-elion','格特鲁德·埃利恩','Gertrude Elion','verified','{"id":"gertrude-elion","slug":"gertrude-elion","nameZh":"格特鲁德·埃利恩","nameEn":"Gertrude Elion","fields":["医学"],"regions":["美国"],"occupation":"化学家、药物研究者","keywords":["医学","化学家、药物研究者"],"summary":"格特鲁德·埃利恩是美国化学家和药物研究者，1937年毕业于亨特学院，1941年取得纽约大学化学硕士学位。她长期与乔治·希钦斯合作，研究嘌呤相关化合物及药物用途。她于1988年获诺贝尔生理学或医学奖，1997年获勒梅尔森—麻省理工终身成就奖，也曾在杜克大学参与研究教学。","story":"埃利恩1918年出生于纽约，1937年从亨特学院毕业。麻省理工学院勒梅尔森项目的档案记载，她在教学与实验室助理工作后进入纽约大学，1941年取得化学硕士学位。她随后从食品企业质量控制工作转入药物研究，1944年开始在伯勒斯—韦尔康实验室与希钦斯合作。\n她的研究涉及嘌呤类化合物及其生物作用。资料将这些研究与抗癌、免疫抑制及其他药物用途联系起来，也记录她从实验研究走向部门管理的经历：1967年至1983年，她负责实验治疗部门，退休后继续担任科研顾问。这里不将长期合作的药物研发简化成单个人的一次发明。\n1988年，她获得诺贝尔生理学或医学奖；1997年，获得勒梅尔森—麻省理工终身成就奖。她还在杜克大学从事研究教学并参与多个健康机构工作。本批诺贝尔奖网页直接访问失败，因此以已读取的MIT正文确认获奖；未采用该页中需要另行核对的具体化合物命名和专利对应关系，也没有编写采访、家庭动机或疗效承诺。","achievements":["1941年取得纽约大学化学硕士学位。","1988年获得诺贝尔生理学或医学奖。"],"facts":[{"claim":"1941年取得纽约大学化学硕士学位。","sourceUrls":["https://lemelson.mit.edu/resources/gertrude-elion"]},{"claim":"1988年获得诺贝尔生理学或医学奖。","sourceUrls":["https://lemelson.mit.edu/resources/gertrude-elion"]}],"sources":[{"title":"Lemelson-MIT：Gertrude Elion人物档案","url":"https://lemelson.mit.edu/resources/gertrude-elion","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1941,"description":"1941年取得纽约大学化学硕士学位。","sourceUrls":["https://lemelson.mit.edu/resources/gertrude-elion"]},{"year":1988,"description":"1988年获得诺贝尔生理学或医学奖。","sourceUrls":["https://lemelson.mit.edu/resources/gertrude-elion"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('nadia-comaneci','nadia-comaneci','纳迪娅·科马内奇','Nadia Comăneci','verified','{"id":"nadia-comaneci","slug":"nadia-comaneci","nameZh":"纳迪娅·科马内奇","nameEn":"Nadia Comăneci","fields":["体育"],"regions":["罗马尼亚"],"occupation":"竞技体操运动员","keywords":["体育","竞技体操运动员"],"summary":"纳迪娅·科马内奇是罗马尼亚竞技体操运动员。1976年蒙特利尔奥运会，她在高低杠获得奥运体操首个满分10分，并夺得全能、平衡木和高低杠金牌。1980年莫斯科奥运会，她再获平衡木与自由体操两金。她于1984年获奥林匹克勋章，1993年入选国际体操名人堂。","story":"科马内奇的竞技履历可以从赛事和项目分别展开。国际体操名人堂档案记录，她在1975年欧洲锦标赛赢得全能冠军。1976年蒙特利尔奥运会，她在高低杠取得满分10分，这一成绩成为当时体操计分制度中的历史记录。\n同届奥运会，她获得女子全能、平衡木和高低杠三枚金牌，并随罗马尼亚队获得团体银牌、取得自由体操铜牌。1980年莫斯科奥运会，她又赢得平衡木和自由体操金牌，同时获得全能和团体银牌。将奖牌按项目列明，可以避免把团体名次误写为个人单项结果，也避免把某一次满分理解为整个职业生涯每场比赛的分数。\n1984年，她获得国际奥委会授予的奥林匹克勋章；1993年入选国际体操名人堂。这里采用该馆的比赛和表彰记录，不复述最高、无法超越等评价。她的成绩属于当时的规则和历史环境，本档案不据此推演现代计分体系下的比较，也不补写训练中的对白、个人心理或未核实的私人经历。人物照片仍使用统一占位图。","achievements":["1976年蒙特利尔奥运会高低杠获得首个奥运体操满分10分，并夺三金。","1980年莫斯科奥运会获平衡木与自由体操金牌。"],"facts":[{"claim":"1976年蒙特利尔奥运会高低杠获得首个奥运体操满分10分，并夺三金。","sourceUrls":["https://www.ighof.com/inductees/1993_Nadia_Comaneci.php"]},{"claim":"1980年莫斯科奥运会获平衡木与自由体操金牌。","sourceUrls":["https://www.ighof.com/inductees/1993_Nadia_Comaneci.php"]}],"sources":[{"title":"International Gymnastics Hall of Fame：Nadia Comaneci","url":"https://www.ighof.com/inductees/1993_Nadia_Comaneci.php","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1976,"description":"1976年蒙特利尔奥运会高低杠获得首个奥运体操满分10分，并夺三金。","sourceUrls":["https://www.ighof.com/inductees/1993_Nadia_Comaneci.php"]},{"year":1980,"description":"1980年莫斯科奥运会获平衡木与自由体操金牌。","sourceUrls":["https://www.ighof.com/inductees/1993_Nadia_Comaneci.php"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('gabrielle-chanel','gabrielle-chanel','嘉柏丽尔·香奈儿','Gabrielle Chanel','verified','{"id":"gabrielle-chanel","slug":"gabrielle-chanel","nameZh":"嘉柏丽尔·香奈儿","nameEn":"Gabrielle Chanel","fields":["商业"],"regions":["法国"],"occupation":"服装设计师、企业创办人","keywords":["商业","服装设计师、企业创办人"],"summary":"嘉柏丽尔·香奈儿是法国服装设计师和企业创办人，也以可可·香奈儿之名为人所知。1910年，她在巴黎康朋街开设帽店，后来扩展至服装与香水业务。1921年，品牌推出她与调香师恩尼斯·鲍合作的五号香水。其设计使用针织面料、简洁轮廓及黑色服饰，是二十世纪时装史的研究对象。","story":"香奈儿的早期经营从帽饰起步。品牌历史记载，1910年她在巴黎康朋街21号以Chanel Modes之名开设帽店，后来扩展服装业务。1915年，比亚里茨的高级定制服工作室建立；1918年，她购入康朋街31号建筑，将店铺、沙龙和工坊设在同一空间。\nV&A博物馆从现存服装讨论她对针织面料、简洁结构与日常穿着的运用。其文章也提醒读者，她并非唯一推广黑色时装的设计师，因此本档案不采用独力发明小黑裙的绝对说法。设计史中的影响，需要通过服装、材料、版型与同期实践来理解。\n1921年，品牌推出五号香水，官方历史明确记录了调香师恩尼斯·鲍的合作角色。这里将这一事实映射到1920年代页面，避免把品牌创办人写成所有产品的独立技术作者。人物故事聚焦本批读取资料所支持的早期商业和设计活动，不将品牌宣传当作完整生平评价，也不添加私人动机与名言；其他时期经历尚需独立专题研究。","achievements":["1910年在巴黎康朋街21号开设Chanel Modes帽店。","1915年在比亚里茨开设高级定制服工作室。"],"facts":[{"claim":"1910年在巴黎康朋街21号开设Chanel Modes帽店。","sourceUrls":["https://www.chanel.com/gb/about-chanel/the-house-of-chanel/1910/"]},{"claim":"1915年在比亚里茨开设高级定制服工作室。","sourceUrls":["https://www.chanel.com/gb/about-chanel/the-house-of-chanel/1910/"]},{"claim":"1921年与调香师恩尼斯·鲍合作推出五号香水。","sourceUrls":["https://www.chanel.com/gb/about-chanel/the-house-of-chanel/1920/"]}],"sources":[{"title":"CHANEL：1910年代品牌历史","url":"https://www.chanel.com/gb/about-chanel/the-house-of-chanel/1910/","checkedAt":"2026-11-09"},{"title":"CHANEL：1920年代品牌历史","url":"https://www.chanel.com/gb/about-chanel/the-house-of-chanel/1920/","checkedAt":"2026-11-09"},{"title":"V&A：Chanel设计专题","url":"https://www.vam.ac.uk/articles/what-makes-chanel-so-iconic","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1910,"description":"1910年在巴黎康朋街21号开设Chanel Modes帽店。","sourceUrls":["https://www.chanel.com/gb/about-chanel/the-house-of-chanel/1910/"]},{"year":1915,"description":"1915年在比亚里茨开设高级定制服工作室。","sourceUrls":["https://www.chanel.com/gb/about-chanel/the-house-of-chanel/1910/"]},{"year":1921,"description":"1921年与调香师恩尼斯·鲍合作推出五号香水。","sourceUrls":["https://www.chanel.com/gb/about-chanel/the-house-of-chanel/1920/"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('virginia-woolf','virginia-woolf','弗吉尼亚·伍尔夫','Virginia Woolf','verified','{"id":"virginia-woolf","slug":"virginia-woolf","nameZh":"弗吉尼亚·伍尔夫","nameEn":"Virginia Woolf","fields":["文学"],"regions":["英国"],"occupation":"小说家、散文家、出版人","keywords":["文学","小说家、散文家、出版人"],"summary":"弗吉尼亚·伍尔夫是英国小说家、散文家和出版人，原名阿德琳·弗吉尼亚·斯蒂芬。她曾在伦敦国王学院女子部学习语言和历史，是布卢姆斯伯里群体的重要成员。作品包括《达洛维夫人》《到灯塔去》《奥兰多》及《一间自己的房间》。她也与丈夫伦纳德共同创办霍加斯出版社。","story":"伍尔夫的写作经历与教育、艺术交往和出版工作相连。伦敦国王学院人物档案记载，她于1897至1902年在女子部学习，课程包括希腊语、拉丁语、德语和历史。她后来成为布卢姆斯伯里群体的重要成员，参与二十世纪英国文学与文化生活。\n她创作的小说包括《达洛维夫人》《到灯塔去》和《奥兰多》，也撰写讨论女性与文学的《一间自己的房间》。这些作品使用不同叙事和论述形式，不能仅按某一部小说的主人公解释作者本人。理解其写作还需要区分作品文本、评论与个人史料。\n她与丈夫伦纳德共同创办霍加斯出版社，最初在家中使用手动印刷机。哥伦比亚大学图书馆的馆藏说明补充，早期出版物《Two Stories》分别收录两人的故事，展现她作为作者之外的出版实践。本档案根据大学与图书馆资料整理学习、作品和出版活动，不采用未经核对的心理诊断或私人动机，也不复制小说中的长段文字或将文学场景当作真实经历。","achievements":["1897至1902年在伦敦国王学院女子部学习语言和历史。","与伦纳德·伍尔夫共同创办霍加斯出版社。"],"facts":[{"claim":"1897至1902年在伦敦国王学院女子部学习语言和历史。","sourceUrls":["https://www.kcl.ac.uk/people/virginia-woolf"]},{"claim":"与伦纳德·伍尔夫共同创办霍加斯出版社。","sourceUrls":["https://www.kcl.ac.uk/people/virginia-woolf"]}],"sources":[{"title":"King’s College London：Virginia Woolf人物档案","url":"https://www.kcl.ac.uk/people/virginia-woolf","checkedAt":"2026-11-09"},{"title":"Columbia Libraries：Hogarth Press馆藏说明","url":"https://online-exhibitions.library.columbia.edu/exhibits/show/jewels/themes/literature/208","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('barbara-hepworth','barbara-hepworth','芭芭拉·赫普沃思','Barbara Hepworth','verified','{"id":"barbara-hepworth","slug":"barbara-hepworth","nameZh":"芭芭拉·赫普沃思","nameEn":"Barbara Hepworth","fields":["艺术"],"regions":["英国"],"occupation":"雕塑家、艺术家","keywords":["艺术","雕塑家、艺术家"],"summary":"芭芭拉·赫普沃思是英国雕塑家和艺术家，曾在利兹艺术学校及皇家艺术学院学习，探索石材、木材与抽象形式。她于1939年前往康沃尔圣艾夫斯，1949年购入特鲁温工作室。1964年，其大型雕塑《单一形式》在纽约联合国总部揭幕。她也从事绘画、版画和艺术写作。","story":"赫普沃思出生于英国约克郡韦克菲尔德，先后在利兹艺术学校和皇家艺术学院学习雕塑。剑桥大学Kettle’s Yard的介绍指出，她属于直接在石材和木材上雕刻的学生群体，1924年获旅行奖学金赴意大利。材料与形式由此成为理解她工作的重要线索。\n1939年，她与家人前往康沃尔圣艾夫斯，后来在当地长期创作。1949年，她购入特鲁温工作室，并参与当地艺术组织。官方时间线将工作室、展览、绘画和雕塑实践并列呈现，说明她的艺术活动并不限于某一种尺寸或媒介。\n1964年，她为纪念联合国秘书长哈马舍尔德创作的大型《单一形式》在纽约联合国总部揭幕。1968年，泰特美术馆举办其重要回顾展。这里保留公共委托与展览的具体事实，不从作品的孔洞、曲线或材质推断未经记录的心理含义。官网标明图文受版权保护，本批只作独立中文转述，未下载作品或人物图像，也没有将可浏览的图片视为自由授权。","achievements":["1939年前往康沃尔圣艾夫斯，1949年购入特鲁温工作室。","1964年大型雕塑《单一形式》在纽约联合国总部揭幕。"],"facts":[{"claim":"1939年前往康沃尔圣艾夫斯，1949年购入特鲁温工作室。","sourceUrls":["https://barbarahepworth.org.uk/biography/"]},{"claim":"1964年大型雕塑《单一形式》在纽约联合国总部揭幕。","sourceUrls":["https://barbarahepworth.org.uk/biography/"]}],"sources":[{"title":"Barbara Hepworth：官方生平时间线","url":"https://barbarahepworth.org.uk/biography/","checkedAt":"2026-11-09"},{"title":"University of Cambridge Kettle’s Yard：艺术家档案","url":"https://www.kettlesyard.cam.ac.uk/bio/barbara-hepworth/","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1964,"description":"1964年大型雕塑《单一形式》在纽约联合国总部揭幕。","sourceUrls":["https://barbarahepworth.org.uk/biography/"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('anne-sullivan','anne-sullivan','安妮·沙利文','Anne Sullivan','verified','{"id":"anne-sullivan","slug":"anne-sullivan","nameZh":"安妮·沙利文","nameEn":"Anne Sullivan","fields":["教育"],"regions":["美国"],"occupation":"教师、聋盲教育工作者","keywords":["教育","教师、聋盲教育工作者"],"summary":"安妮·沙利文是美国教师和聋盲教育工作者。她于1886年从帕金斯学校毕业并发表毕业生代表演说，1887年赴阿拉巴马州开始教授海伦·凯勒。她学习早期聋盲教育经验，将手指拼写融入学生感兴趣的日常活动，并长期支持凯勒的学习。相关书信与学校档案保留了其教学历程。","story":"沙利文早年进入帕金斯学校学习，在那里接触劳拉·布里奇曼，并学习手语字母。学校历史资料记载，她于1886年毕业，担任毕业生代表发表演说。随后，校长收到凯勒家人的求助，推荐她承担教学工作；1887年3月，她前往阿拉巴马州塔斯坎比亚。\n开始任教前，她研读了豪及其他教师教授布里奇曼的记录。帕金斯的传记指出，她早期采用较固定的课程安排，后来逐步围绕凯勒的兴趣与日常活动教授词汇，并通过在手掌中拼写进行持续交流。这一变化可以从教学记录理解，而不必编造一次突然解决所有学习问题的奇迹场景。\n学校保存并介绍她与同事及凯勒相关的书信和照片，为研究教学方法提供材料。她与凯勒的关系涉及长期合作和学生自身的学习，不能把后者的全部成就仅归于教师。这里使用学校史料概括求学、准备和课堂方法，不复写传记中的长段引语，也不将舞台或影视改编的对白写成事实。所有图片继续采用统一占位图。","achievements":["1886年从帕金斯学校毕业并发表毕业生代表演说。","1887年3月前往阿拉巴马州开始教授海伦·凯勒。"],"facts":[{"claim":"1886年从帕金斯学校毕业并发表毕业生代表演说。","sourceUrls":["https://www.perkins.org/anne-sullivan/"]},{"claim":"1887年3月前往阿拉巴马州开始教授海伦·凯勒。","sourceUrls":["https://www.perkins.org/anne-sullivan/"]}],"sources":[{"title":"Perkins School for the Blind：Anne Sullivan传记","url":"https://www.perkins.org/anne-sullivan/","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1886,"description":"1886年从帕金斯学校毕业并发表毕业生代表演说。","sourceUrls":["https://www.perkins.org/anne-sullivan/"]},{"year":1887,"description":"1887年3月前往阿拉巴马州开始教授海伦·凯勒。","sourceUrls":["https://www.perkins.org/anne-sullivan/"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('frances-perkins','frances-perkins','弗朗西丝·珀金斯','Frances Perkins','verified','{"id":"frances-perkins","slug":"frances-perkins","nameZh":"弗朗西丝·珀金斯","nameEn":"Frances Perkins","fields":["公共事务"],"regions":["美国"],"occupation":"劳工政策改革者、政府官员","keywords":["公共事务","劳工政策改革者、政府官员"],"summary":"弗朗西丝·珀金斯是美国劳工政策改革者和政府官员，1933至1945年担任劳工部长，是美国首位女性内阁成员。她早年在纽约从事社会工作与州级劳工行政，后来参与失业救济、最低工资和社会保险改革，推动1935年社会保障立法。其职业经历连接社会调查、行政管理与公共政策。","story":"珀金斯早年在纽约从事社会工作，并通过消费者组织推动工厂相关立法。美国劳工部的部门历史记载，她曾在州工业委员会工作，后来担任纽约州劳工行政负责人，参与工伤补偿和失业问题的政策工作。这些经历构成她进入联邦政府之前的职业背景。\n1933年，她获任劳工部长，成为美国首位女性内阁成员，并任职至1945年。在经济大萧条期间，她参与失业救济、公共工程、最低工资与社会保险等政策讨论和行政工作。部门资料特别记录了她推动养老保险制度的活动，以及1935年社会保障法的通过。\n这些政策涉及总统、国会、州政府、专家与社会组织，不能把复杂的立法过程写成部长个人独力完成。人物故事因此将她的倡议和协调角色与最终制度结果区分开来，也不把历史制度覆盖范围描述为所有人当时都能受益。这里依据政府历史资料保留职务、年代与政策事项，未复制来源对其性格的评价或增写私人会议对白，未将历史叙述当作当前法律说明。","achievements":["1933至1945年担任美国劳工部长，为美国首位女性内阁成员。","参与推动养老保险与1935年社会保障立法。"],"facts":[{"claim":"1933至1945年担任美国劳工部长，为美国首位女性内阁成员。","sourceUrls":["https://www.dol.gov/general/aboutdol/history/dolchp03"]},{"claim":"参与推动养老保险与1935年社会保障立法。","sourceUrls":["https://www.dol.gov/general/aboutdol/history/dolchp03"]}],"sources":[{"title":"U.S. Department of Labor：1933–1945部门历史","url":"https://www.dol.gov/general/aboutdol/history/dolchp03","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1935,"description":"参与推动养老保险与1935年社会保障立法。","sourceUrls":["https://www.dol.gov/general/aboutdol/history/dolchp03"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('eileen-collins','eileen-collins','艾琳·柯林斯','Eileen Collins','verified','{"id":"eileen-collins","slug":"eileen-collins","nameZh":"艾琳·柯林斯","nameEn":"Eileen Collins","fields":["探索"],"regions":["美国"],"occupation":"飞行员、宇航员","keywords":["探索","飞行员、宇航员"],"summary":"艾琳·柯林斯是美国飞行员和宇航员，1990年入选NASA，1991年完成宇航员训练。她于1995年执行STS-63，成为航天飞机首位女性驾驶员；1999年执行STS-93，成为航天飞机首位女性指令长。她还参加STS-84并指挥STS-114，共执行四次飞行，2006年从NASA退休。","story":"柯林斯在美国空军试飞员学校学习期间，于1990年被NASA选入宇航员计划，1991年完成训练。NASA履历记载，她最初从事轨道器工程支持，后来承担发射前检查、乘员进出、着陆回收和任务控制通信等工作。宇航员的职业活动因此不只包括实际飞行。\n1995年，她在STS-63担任驾驶员，成为航天飞机首位女性驾驶员；1997年，她在STS-84再次担任这一职务。1999年，她在STS-93出任指令长，成为航天飞机首位女性指令长。这里分别记录驾驶员与指令长，避免将两项任务角色混为同一职位。\n2005年，她指挥STS-114，这次任务是哥伦比亚号事故后航天飞机恢复飞行的一部分。她总共执行四次航天飞行，并于2006年5月从NASA退休。官方页面中一些旧新闻仍使用当前唯一等历史时态，本档案不将其当作今天的断言；对不同资料中的发射日期口径，采用已确认的任务年份，不补写座舱对话、个人动机或未经核对的飞行细节。","achievements":["1995年执行STS-63，成为航天飞机首位女性驾驶员。","1999年执行STS-93，成为航天飞机首位女性指令长。"],"facts":[{"claim":"1995年执行STS-63，成为航天飞机首位女性驾驶员。","sourceUrls":["https://www.nasa.gov/former-astronaut-eileen-collins/"]},{"claim":"1999年执行STS-93，成为航天飞机首位女性指令长。","sourceUrls":["https://www.nasa.gov/former-astronaut-eileen-collins/"]}],"sources":[{"title":"NASA：Eileen Collins官方履历与任务档案","url":"https://www.nasa.gov/former-astronaut-eileen-collins/","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1995,"description":"1995年执行STS-63，成为航天飞机首位女性驾驶员。","sourceUrls":["https://www.nasa.gov/former-astronaut-eileen-collins/"]},{"year":1999,"description":"1999年执行STS-93，成为航天飞机首位女性指令长。","sourceUrls":["https://www.nasa.gov/former-astronaut-eileen-collins/"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('emmy-noether','emmy-noether','埃米·诺特','Emmy Noether','verified','{"id":"emmy-noether","slug":"emmy-noether","nameZh":"埃米·诺特","nameEn":"Emmy Noether","fields":["数学"],"regions":["德国","美国"],"occupation":"数学家","keywords":["数学","数学家"],"summary":"埃米·诺特是德国数学家，研究抽象代数，尤其是环与理想的结构。她1921年发表有关环中理想理论的论文，推动现代代数发展。1933年，纳粹迫害使她失去哥廷根的职位，随后赴美国布林莫尔学院工作，并在普林斯顿高等研究院讲学。她的研究也通过学生与合作者的著作传播。","story":"诺特的数学工作以抽象代数为重要方向。圣安德鲁斯大学数学史档案记载，她在1921年的论文中研究环的理想理论，对现代代数的发展产生影响。她的工作涉及从具体计算转向结构与条件的研究，也通过学生及同事的论文和教材传播，不能只按署名论文的数量衡量。\n1932年，她受邀在苏黎世国际数学家大会报告，并与阿廷共同获得阿克曼—托伊布纳纪念奖。次年，纳粹政权因其犹太身份将她逐出哥廷根大学。她接受美国布林莫尔学院的访问职位，于1933年前往美国，在新的学术环境中继续教学和研究。\n1934年，她开始到普林斯顿高等研究院讲学。该院保存的讲课笔记及相关档案，与大学数学史资料共同记录了这段跨机构交流。她1935年在美国去世。这里保留论文、报告、迁移与教学的事实，不把她写成高等研究院的正式教授，也不根据后人评价编造她与其他数学家的私人对话。","achievements":["1921年发表有关环中理想理论的论文。","1933年前往布林莫尔学院，1934年开始在普林斯顿高等研究院讲学。"],"facts":[{"claim":"1921年发表有关环中理想理论的论文。","sourceUrls":["https://mathshistory.st-andrews.ac.uk/Biographies/Noether_Emmy/"]},{"claim":"1933年前往布林莫尔学院，1934年开始在普林斯顿高等研究院讲学。","sourceUrls":["https://mathshistory.st-andrews.ac.uk/Biographies/Noether_Emmy/"]}],"sources":[{"title":"University of St Andrews MacTutor：Emmy Noether","url":"https://mathshistory.st-andrews.ac.uk/Biographies/Noether_Emmy/","checkedAt":"2026-11-09"},{"title":"IAS：Honoring the Legacy of Emmy Noether","url":"https://www.ias.edu/news/2023/honoring-legacy-emmy-noether","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1921,"description":"1921年发表有关环中理想理论的论文。","sourceUrls":["https://mathshistory.st-andrews.ac.uk/Biographies/Noether_Emmy/"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('lise-meitner','lise-meitner','莉泽·迈特纳','Lise Meitner','verified','{"id":"lise-meitner","slug":"lise-meitner","nameZh":"莉泽·迈特纳","nameEn":"Lise Meitner","fields":["科学"],"regions":["奥地利","德国","瑞典"],"occupation":"物理学家","keywords":["科学","物理学家"],"summary":"莉泽·迈特纳是奥地利物理学家，长期参与放射性研究。1938年，她因纳粹迫害离开德国前往瑞典，仍与奥托·哈恩通信讨论研究。1939年，她与外甥奥托·弗里施对铀受到中子轰击后产生钡的结果作出物理解释，相关论文在《自然》发表。其工作是理解核裂变历史的重要部分。","story":"迈特纳长期从事放射性相关物理研究，并与化学家奥托·哈恩合作。马克斯·普朗克化学研究所的历史文章记录，1938年夏天，她作为受到纳粹迫害的犹太裔研究者离开德国，前往瑞典。离开实验室后，她仍通过通信与哈恩交换研究信息，这一联系延续了物理与化学之间的讨论。\n1938年12月，哈恩和弗里茨·施特拉斯曼在铀受到中子轰击的实验中识别出钡。次年1月，迈特纳与外甥奥托·弗里施对这一结果提出物理解释，将实验现象理解为重原子核分裂。二人的论文在1月交给《自然》，于1939年2月11日发表。\n发现过程涉及实验、化学鉴定和物理解释等不同工作，档案因此分别列明参与者及其角色。这里不将实验全部归于迈特纳，也不因她离开德国便抹去她后续的理论贡献。人物故事依据研究机构的历史叙述整理，不增写雪地谈话、私人感受或未核对的职务年份，避免把后来的纪念评价代替当时的研究证据。","achievements":["1938年夏天离开德国前往瑞典，继续与哈恩通信。","与奥托·弗里施共同解释核裂变，论文于1939年2月11日在《自然》发表。"],"facts":[{"claim":"1938年夏天离开德国前往瑞典，继续与哈恩通信。","sourceUrls":["https://www.mpic.de/4469988/die-entdeckung-der-kernspaltung"]},{"claim":"与奥托·弗里施共同解释核裂变，论文于1939年2月11日在《自然》发表。","sourceUrls":["https://www.mpic.de/4469988/die-entdeckung-der-kernspaltung"]}],"sources":[{"title":"Max Planck Institute for Chemistry：核裂变的发现","url":"https://www.mpic.de/4469988/die-entdeckung-der-kernspaltung","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1938,"description":"1938年夏天离开德国前往瑞典，继续与哈恩通信。","sourceUrls":["https://www.mpic.de/4469988/die-entdeckung-der-kernspaltung"]},{"year":1939,"description":"与奥托·弗里施共同解释核裂变，论文于1939年2月11日在《自然》发表。","sourceUrls":["https://www.mpic.de/4469988/die-entdeckung-der-kernspaltung"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('gerty-cori','gerty-cori','格蒂·科里','Gerty Cori','verified','{"id":"gerty-cori","slug":"gerty-cori","nameZh":"格蒂·科里","nameEn":"Gerty Cori","fields":["医学"],"regions":["美国","捷克"],"occupation":"生物化学研究者、医学博士","keywords":["医学","生物化学研究者、医学博士"],"summary":"格蒂·科里是生物化学研究者，1920年在布拉格取得医学学位，后来赴美国工作。她与卡尔·科里共同研究糖类代谢，1931年进入圣路易斯华盛顿大学医学院，长期开展糖原相关研究。1947年，两人因糖原催化转化研究获得诺贝尔生理学或医学奖。她的职业历程也反映了女性科研任职的障碍。","story":"科里在布拉格学习医学，1920年取得医学学位。美国国家医学图书馆的传记记载，她随后在维也纳工作，1922年前往美国布法罗，担任病理学助理，逐渐将研究重点转向生物化学和糖类代谢。她与卡尔·科里长期合作，也发表过独立署名论文。\n1929年，两人提出后来以科里循环命名的理论，研究身体不同组织之间的糖类代谢联系。1931年，他们进入圣路易斯华盛顿大学医学院。尽管参与共同研究，格蒂最初获得的是研究助理职位，职业晋升与合作者存在差异。这里不采用不同档案中尚有分歧的教授晋升年份。\n1947年，两人因糖原催化转化研究获得诺贝尔生理学或医学奖，这一事实同时见于医学院历史和医学图书馆资料。研究工作涉及长期实验与合作，不能简化为一次偶然发现。人物故事保留求学、任职和研究主题，不采用来源中错误的首对科学诺奖夫妇说法，不提供治疗建议，也不将基础研究直接写成她个人发明某种疗法。","achievements":["1931年进入圣路易斯华盛顿大学医学院药理学部门。","1947年因糖原催化转化研究获得诺贝尔生理学或医学奖。"],"facts":[{"claim":"1931年进入圣路易斯华盛顿大学医学院药理学部门。","sourceUrls":["https://medicine.washu.edu/about/history/"]},{"claim":"1947年因糖原催化转化研究获得诺贝尔生理学或医学奖。","sourceUrls":["https://medicine.washu.edu/about/history/"]}],"sources":[{"title":"WashU Medicine：医学院历史","url":"https://medicine.washu.edu/about/history/","checkedAt":"2026-11-09"},{"title":"National Library of Medicine：Gerty Cori传记","url":"https://www.nlm.nih.gov/exhibition/changing-the-face-of-medicine/physicians/biography_gerty_cori.html?id=item-72","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1931,"description":"1931年进入圣路易斯华盛顿大学医学院药理学部门。","sourceUrls":["https://medicine.washu.edu/about/history/"]},{"year":1947,"description":"1947年因糖原催化转化研究获得诺贝尔生理学或医学奖。","sourceUrls":["https://medicine.washu.edu/about/history/"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('kathrine-switzer','kathrine-switzer','凯瑟琳·斯威策','Kathrine Switzer','verified','{"id":"kathrine-switzer","slug":"kathrine-switzer","nameZh":"凯瑟琳·斯威策","nameEn":"Kathrine Switzer","fields":["体育"],"regions":["美国"],"occupation":"马拉松运动员、体育倡导者、作家","keywords":["体育","马拉松运动员、体育倡导者、作家"],"summary":"凯瑟琳·斯威策是美国马拉松运动员、作家和女性体育参与倡导者。1967年，她正式报名并完成波士顿马拉松，比赛中遭到赛事管理者阻拦。1974年，她赢得纽约城市马拉松冠军。她也从事赛事评论，撰写跑步相关书籍，并推动女性公路跑赛事与参与机会，职业活动跨越比赛和体育组织。","story":"斯威策的运动经历与女性参与公路跑的历史相连。其官方传记记载，1967年，她正式报名参加当时主要面向男性的波士顿马拉松，并佩戴号码布出赛。比赛途中，赛事管理者试图阻止她，她仍完成赛程。这里使用首位正式报名女性的表述，不将其误写为首位曾跑过该赛事的女性。\n此后，她参与推动女性在波士顿马拉松获得正式参赛机会，并在1972年参与组织早期女性公路跑赛事。她的竞技履历还包括1974年纽约城市马拉松冠军。成绩、参赛资格和赛事组织属于不同层面的工作，应分别记录，避免将制度变化全部归功于单个人。\n除了运动员身份，她也是电视赛事评论员和作家，著有《Marathon Woman》等跑步书籍，并创办雅芳女性跑步巡回项目。2011年，她入选美国全国女性名人堂。这里依据人物官网概括比赛与公共活动，未将旧页面的现时比赛数量当作最新统计，也不补写赛道上的对白、训练心理或私人动机。","achievements":["1967年正式报名并完成波士顿马拉松。","1974年赢得纽约城市马拉松冠军。"],"facts":[{"claim":"1967年正式报名并完成波士顿马拉松。","sourceUrls":["https://kathrineswitzer.com/meet-kathrine/"]},{"claim":"1974年赢得纽约城市马拉松冠军。","sourceUrls":["https://kathrineswitzer.com/meet-kathrine/"]}],"sources":[{"title":"Kathrine Switzer：官方完整传记","url":"https://kathrineswitzer.com/meet-kathrine/","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1967,"description":"1967年正式报名并完成波士顿马拉松。","sourceUrls":["https://kathrineswitzer.com/meet-kathrine/"]},{"year":1974,"description":"1974年赢得纽约城市马拉松冠军。","sourceUrls":["https://kathrineswitzer.com/meet-kathrine/"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('oprah-winfrey','oprah-winfrey','奥普拉·温弗瑞','Oprah Winfrey','verified','{"id":"oprah-winfrey","slug":"oprah-winfrey","nameZh":"奥普拉·温弗瑞","nameEn":"Oprah Winfrey","fields":["商业"],"regions":["美国"],"occupation":"媒体企业家、主持人、制片人","keywords":["商业","媒体企业家、主持人、制片人"],"summary":"奥普拉·温弗瑞是美国媒体企业家、主持人和制片人。她1984年在芝加哥主持晨间节目，1986年《奥普拉·温弗瑞秀》向全美播出。她通过Harpo Productions拓展电影、电视与出版相关业务，也出演《紫色》并获奥斯卡提名。她后来设立慈善项目，并在南非创办女子领导力学院。","story":"温弗瑞的媒体生涯从广播电视工作发展到节目制作。美国电影艺术与科学学院的档案记录，她1984年成为芝加哥晨间节目的联合主持人，1986年《奥普拉·温弗瑞秀》向全美播出。该节目持续多年，最后一期于2011年5月25日播出。\n她同时参与电影表演与制作，因1985年电影《紫色》获得奥斯卡女配角提名，后来担任《宠儿》等影片的制片工作。哈佛商学院的商业人物档案介绍，她通过Harpo Productions扩展到电影、有线电视、读书会和杂志等业务。这些活动说明她的角色不仅是镜头前的主持人，也包括企业经营与内容生产。\n学院档案还记录她1987年设立基金会、1998年建立Angel Network，以及2007年在南非创办女子领导力学院。这里分别列明节目、企业与公益活动，不把组织成果全部归为个人独力完成，也不采用未经核实的财富排名、捐赠总额或企业现状。人物故事依据机构资料整理，未编写采访、励志名言或私人经历。","achievements":["1986年《奥普拉·温弗瑞秀》开始向全美播出。","2007年在南非创办女子领导力学院。"],"facts":[{"claim":"1986年《奥普拉·温弗瑞秀》开始向全美播出。","sourceUrls":["https://www.oscars.org/governors-awards/ceremonies/oprah-winfrey"]},{"claim":"2007年在南非创办女子领导力学院。","sourceUrls":["https://www.oscars.org/governors-awards/ceremonies/oprah-winfrey"]}],"sources":[{"title":"Academy of Motion Picture Arts and Sciences：Oprah Winfrey","url":"https://www.oscars.org/governors-awards/ceremonies/oprah-winfrey","checkedAt":"2026-11-09"},{"title":"Harvard Business School：Oprah G. Winfrey","url":"https://www.hbs.edu/leadership/20th-century-leaders/details?profile=oprah_g_winfrey","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1986,"description":"1986年《奥普拉·温弗瑞秀》开始向全美播出。","sourceUrls":["https://www.oscars.org/governors-awards/ceremonies/oprah-winfrey"]},{"year":2007,"description":"2007年在南非创办女子领导力学院。","sourceUrls":["https://www.oscars.org/governors-awards/ceremonies/oprah-winfrey"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('zora-neale-hurston','zora-neale-hurston','佐拉·尼尔·赫斯顿','Zora Neale Hurston','verified','{"id":"zora-neale-hurston","slug":"zora-neale-hurston","nameZh":"佐拉·尼尔·赫斯顿","nameEn":"Zora Neale Hurston","fields":["文学"],"regions":["美国"],"occupation":"作家、人类学与民俗研究者","keywords":["文学","作家、人类学与民俗研究者"],"summary":"佐拉·尼尔·赫斯顿是美国作家、人类学与民俗研究者，出生于阿拉巴马州，在佛罗里达州成长。她1928年获得巴纳德学院学位，1934年出版首部长篇小说《约拿的葫芦藤》，1937年出版《他们眼望上苍》。她的创作包括小说、短篇与散文，也收集和研究非裔美国人的民间文化。","story":"赫斯顿的写作与民俗研究互相联系。美国艺术与科学院的人物档案记载，她出生于阿拉巴马州，在佛罗里达州成长，后来进入纽约的学术与文学环境。1928年，她获得巴纳德学院学位；学院自己的档案进一步记录，她是该校已知首位黑人毕业生，并接触人类学研究。\n1934年，她出版首部长篇小说《约拿的葫芦藤》。次年，《Mules and Men》出版，将民俗材料带入她的著述。1937年，她发表《他们眼望上苍》；1938年的《Tell My Horse》则与她在海地的研究经历有关。不同作品涉及文学创作和文化记录，阅读时需要区分小说叙事与田野材料。\n她也从事教育工作，曾参与贝休恩—库克曼学院的戏剧活动，并在北卡罗来纳州任教。这里以大学和学术机构档案核对学位、作品及职业活动，不把人类学学习直接等同于取得该专业学位，也不采用来源之间存在差异的霍华德大学就读年份。人物故事不复制小说段落，不将书中人物的经历当成作者自传。","achievements":["1928年获得巴纳德学院学位。","1937年出版小说《他们眼望上苍》。"],"facts":[{"claim":"1928年获得巴纳德学院学位。","sourceUrls":["https://www.amacad.org/person/zora-neale-hurston"]},{"claim":"1937年出版小说《他们眼望上苍》。","sourceUrls":["https://www.amacad.org/person/zora-neale-hurston"]}],"sources":[{"title":"American Academy of Arts and Sciences：Zora Neale Hurston","url":"https://www.amacad.org/person/zora-neale-hurston","checkedAt":"2026-11-09"},{"title":"Barnard College：Zora Neale Hurston at Barnard","url":"https://barnard.edu/zora-neale-hurston-at-barnard","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1928,"description":"1928年获得巴纳德学院学位。","sourceUrls":["https://www.amacad.org/person/zora-neale-hurston"]},{"year":1937,"description":"1937年出版小说《他们眼望上苍》。","sourceUrls":["https://www.amacad.org/person/zora-neale-hurston"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('augusta-savage','augusta-savage','奥古斯塔·萨维奇','Augusta Savage','verified','{"id":"augusta-savage","slug":"augusta-savage","nameZh":"奥古斯塔·萨维奇","nameEn":"Augusta Savage","fields":["艺术"],"regions":["美国"],"occupation":"雕塑家、美术教师、社区艺术组织者","keywords":["艺术","雕塑家、美术教师、社区艺术组织者"],"summary":"奥古斯塔·萨维奇是美国雕塑家、美术教师和社区艺术组织者，活跃于哈莱姆文艺复兴时期。她在纽约库珀联盟学习，1929年获得罗森沃尔德资助赴巴黎进修。1932年，她开设艺术与工艺工作室，后来担任哈莱姆社区艺术中心首任主任，并为1939年纽约世界博览会创作大型雕塑《竖琴》。","story":"萨维奇1892年出生于佛罗里达州，后来前往纽约，在库珀联盟学习艺术。史密森美国艺术博物馆的传记记录，她以人物胸像逐渐建立雕塑家的职业身份，作品题材包括哈莱姆的公共人物。她在1929年获得罗森沃尔德资助，前往巴黎继续学习和参展。\n1932年回到纽约后，她建立艺术与工艺工作室，从事教学。1937年，她成为哈莱姆社区艺术中心首任主任。教学、社区组织和个人创作共同构成她的职业活动，不能仅根据今天仍保存的作品数量理解其贡献。\n她受委托为1939年纽约世界博览会创作《竖琴》，以一组歌唱者的形象构成大型雕塑。作品以石膏制作，展后未能转铸为更持久的材料，最终被拆除。馆藏资料保存了其创作和展示的线索，也反映公共艺术保存所受到的经费与空间限制。这里根据博物馆传记整理求学、资助、教学和委托经历，不复制来源引语，不推断人物心理；相关照片与作品图像未取得明确许可，因此继续使用统一占位图。","achievements":["1929年获得罗森沃尔德资助赴巴黎学习。","1937年担任哈莱姆社区艺术中心首任主任。"],"facts":[{"claim":"1929年获得罗森沃尔德资助赴巴黎学习。","sourceUrls":["https://americanart.si.edu/artist/augusta-savage-4269"]},{"claim":"1937年担任哈莱姆社区艺术中心首任主任。","sourceUrls":["https://americanart.si.edu/artist/augusta-savage-4269"]}],"sources":[{"title":"Smithsonian American Art Museum：Augusta Savage","url":"https://americanart.si.edu/artist/augusta-savage-4269","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1929,"description":"1929年获得罗森沃尔德资助赴巴黎学习。","sourceUrls":["https://americanart.si.edu/artist/augusta-savage-4269"]},{"year":1937,"description":"1937年担任哈莱姆社区艺术中心首任主任。","sourceUrls":["https://americanart.si.edu/artist/augusta-savage-4269"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('helen-keller','helen-keller','海伦·凯勒','Helen Keller','verified','{"id":"helen-keller","slug":"helen-keller","nameZh":"海伦·凯勒","nameEn":"Helen Keller","fields":["教育"],"regions":["美国"],"occupation":"作家、残障教育与权利倡导者","keywords":["教育","作家、残障教育与权利倡导者"],"summary":"海伦·凯勒是美国作家、残障教育与权利倡导者。她在沙利文长期支持下求学，1900年进入拉德克利夫学院，1904年以优等成绩取得学士学位，是首位获得学士学位的聋盲人士。她1903年出版《我的生活》，1924年开始为美国盲人基金会工作，长期参与教育、无障碍和公共倡导活动。","story":"凯勒的学习经历涉及个人努力、教师支持与教育资源的共同作用。美国盲人基金会的传记记录，她1900年进入拉德克利夫学院，1904年以优等成绩获得学士学位，成为首位取得这一学位的聋盲人士。沙利文在她长期求学过程中提供支持，但不能因此将凯勒自身的学习和写作能力从叙述中抹去。\n1903年，她出版《我的生活》，其中部分内容此前已在杂志连载。她的职业活动随后延伸至写作与公共倡导，关注残障者的教育和社会参与，也参与妇女参政等公共议题。1915年，她进入一个支持战争致盲者的救援组织董事会。\n1924年，她开始为美国盲人基金会工作，此后与该机构合作约四十年。基金会的历史资料将她的教育经历与持续倡导并列呈现，说明其公共角色不能只由童年学习片段概括。这里保留学位、著作及机构工作等事实，不将舞台改编对白写成史实，也不以奇迹或克服一切的表述替代教育条件与长期合作；人物分类为教育倡导者，不标为学校教师。","achievements":["1904年以优等成绩取得拉德克利夫学院学士学位。","1924年开始为美国盲人基金会工作，合作约四十年。"],"facts":[{"claim":"1904年以优等成绩取得拉德克利夫学院学士学位。","sourceUrls":["https://www.afb.org/about-afb/history/helen-keller/biography-and-chronology/biography"]},{"claim":"1924年开始为美国盲人基金会工作，合作约四十年。","sourceUrls":["https://www.afb.org/about-afb/history/helen-keller/biography-and-chronology/biography"]}],"sources":[{"title":"American Foundation for the Blind：Helen Keller Biography","url":"https://www.afb.org/about-afb/history/helen-keller/biography-and-chronology/biography","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1904,"description":"1904年以优等成绩取得拉德克利夫学院学士学位。","sourceUrls":["https://www.afb.org/about-afb/history/helen-keller/biography-and-chronology/biography"]},{"year":1924,"description":"1924年开始为美国盲人基金会工作，合作约四十年。","sourceUrls":["https://www.afb.org/about-afb/history/helen-keller/biography-and-chronology/biography"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('shirley-chisholm','shirley-chisholm','雪莉·奇泽姆','Shirley Chisholm','verified','{"id":"shirley-chisholm","slug":"shirley-chisholm","nameZh":"雪莉·奇泽姆","nameEn":"Shirley Chisholm","fields":["公共事务"],"regions":["美国"],"occupation":"教育工作者、国会议员","keywords":["公共事务","教育工作者、国会议员"],"summary":"雪莉·奇泽姆是美国教育工作者和政治人物，曾任幼儿教师、托育机构负责人及纽约州议员。她1968年当选联邦众议员，成为首位进入美国国会的黑人女性，1969至1983年连续任职七届。1972年，她竞逐民主党总统候选人提名。她的公共生涯连接幼儿教育、州级立法与联邦政治。","story":"奇泽姆的公共生涯始于教育工作。美国众议院历史档案记载，她1946年毕业于布鲁克林学院，1952年取得哥伦比亚大学硕士学位，先后担任幼儿教师、托育机构负责人和教育顾问。这些职位属于不同阶段，不能笼统地全部写成在同一所学校执教。\n1964至1968年，她担任纽约州议员。1968年，她当选联邦众议员，成为首位进入美国国会的黑人女性，于1969年1月开始履职，持续至1983年1月，共七届。档案将当选年份与实际任期分别记录，有助于避免把1968年写成她已在国会任职的时间。\n1972年，她参加民主党总统候选人提名竞争，未获得提名。她后来曾在众议院规则委员会任职，继续参与联邦立法工作。这里依据官方履历整理教育背景、职业和选举事实，不把竞逐党内提名写成获得主要政党正式总统候选人资格，也不编造竞选现场或私人谈话。她的生平有更多政策与组织活动，仍需通过专题资料继续研究，不能以一项首位纪录代替全部职业经历。","achievements":["1968年当选，成为首位进入美国国会的黑人女性。","1972年竞逐民主党总统候选人提名，未获得提名。"],"facts":[{"claim":"1968年当选，成为首位进入美国国会的黑人女性。","sourceUrls":["https://history.house.gov/People/Detail/10918"]},{"claim":"1972年竞逐民主党总统候选人提名，未获得提名。","sourceUrls":["https://history.house.gov/People/Detail/10918"]}],"sources":[{"title":"U.S. House of Representatives：Shirley Chisholm","url":"https://history.house.gov/People/Detail/10918","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1968,"description":"1968年当选，成为首位进入美国国会的黑人女性。","sourceUrls":["https://history.house.gov/People/Detail/10918"]},{"year":1972,"description":"1972年竞逐民主党总统候选人提名，未获得提名。","sourceUrls":["https://history.house.gov/People/Detail/10918"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('ellen-macarthur','ellen-macarthur','艾伦·麦克阿瑟','Ellen MacArthur','verified','{"id":"ellen-macarthur","slug":"ellen-macarthur","nameZh":"艾伦·麦克阿瑟","nameEn":"Ellen MacArthur","fields":["探索"],"regions":["英国"],"occupation":"远洋帆船航海者、基金会创办人","keywords":["探索","远洋帆船航海者、基金会创办人"],"summary":"艾伦·麦克阿瑟是英国远洋帆船航海者和基金会创办人，2005年完成单人环球航行并创下当时的最快纪录。2010年，她设立以自己名字命名的基金会，推动循环经济理念。基金会资料将她的航海经历与有限资源议题联系起来，其后工作涉及材料使用、产品设计与减少废弃物等方向。","story":"麦克阿瑟的职业经历从远洋帆船航行延伸到资源与经济议题。其基金会的官方介绍记载，2005年，她完成单人环球航行，创下当时最快的单人环球航海纪录。这里保留当时的时间限定，不将这一成绩描述为今天仍未被打破的纪录，也不把单人航行等同于完全没有岸上支持。\n官方页面以航程中携带的食物、燃料及其他物资为线索，解释她后来参与有限资源讨论的背景。这属于机构对其经历的回顾，本档案据此介绍工作主题，不自行补写她在海上某一时刻的心理活动、遭遇或决定。\n2010年，她设立艾伦·麦克阿瑟基金会，推动循环经济。机构资料列出与学校、企业、工程师及专家交流的活动，并把延长材料使用、减少废弃物和自然系统再生作为相关议题。基金会的长期项目由团队和合作伙伴参与，不能全部记为创办人的个人成果。人物故事依据机构自述整理两项明确里程碑，对航海细节、其他比赛成绩和具体环境成效保留进一步研究空间，图片仍使用统一占位图。","achievements":["2005年完成单人环球航行，创下当时最快纪录。","2010年设立艾伦·麦克阿瑟基金会，推动循环经济。"],"facts":[{"claim":"2005年完成单人环球航行，创下当时最快纪录。","sourceUrls":["https://www.ellenmacarthurfoundation.org/about-us/ellens-story"]},{"claim":"2010年设立艾伦·麦克阿瑟基金会，推动循环经济。","sourceUrls":["https://www.ellenmacarthurfoundation.org/about-us/ellens-story"]}],"sources":[{"title":"Ellen MacArthur Foundation：Ellen的经历","url":"https://www.ellenmacarthurfoundation.org/about-us/ellens-story","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":2005,"description":"2005年完成单人环球航行，创下当时最快纪录。","sourceUrls":["https://www.ellenmacarthurfoundation.org/about-us/ellens-story"]},{"year":2010,"description":"2010年设立艾伦·麦克阿瑟基金会，推动循环经济。","sourceUrls":["https://www.ellenmacarthurfoundation.org/about-us/ellens-story"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('sophie-germain','sophie-germain','索菲·热尔曼','Sophie Germain','verified','{"id":"sophie-germain","slug":"sophie-germain","nameZh":"索菲·热尔曼","nameEn":"Sophie Germain","fields":["数学"],"regions":["法国"],"occupation":"数学家","keywords":["数学","数学家"],"summary":"索菲·热尔曼是法国数学家，研究数论、声学与弹性理论。她未能以正式学生身份进入巴黎综合理工学院，而是通过讲义自学，并以勒布朗之名交流研究。1804至1809年，她与高斯通信讨论数论，也参与弹性曲面的数学研究。她关于费马大定理的工作提出了处理素数指数问题的新方向。","story":"热尔曼生活于十八世纪末至十九世纪初的法国，主要通过自学和通信参与数学研究。圣安德鲁斯大学数学史档案记载，她取得巴黎综合理工学院的课程讲义，以勒布朗之名向拉格朗日提交数学讨论。她没有该校正式学籍，后来的研究交流也不能被改写成在校就读经历。\n她与勒让德讨论数论，又在1804至1809年间给高斯写信，研究其《算术研究》中的方法。通信和手稿保留了她对费马方程的长期探索：她尝试借助辅助素数处理一类指数，而非仅逐个检验。这一计划并未完成对费马大定理的一般证明，但其中的结果成为后续数学史研究的对象。\n她同时研究振动板与弹性曲面，多次向法国学术机构的竞赛提交论文。早期稿件存在推导问题，修改后的工作获得奖项，研究也在与同时代学者的讨论中发展。两条研究线索展示了她在数论与数学物理间的活动。本档案保留成果及其局限，不将未完成的计划写成完整证明，也不补写夜间学习的戏剧化场景。","achievements":["通过巴黎综合理工学院讲义学习，并以勒布朗之名向拉格朗日交流数学。","1804至1809年与高斯通信，讨论数论研究。"],"facts":[{"claim":"通过巴黎综合理工学院讲义学习，并以勒布朗之名向拉格朗日交流数学。","sourceUrls":["https://mathshistory.st-andrews.ac.uk/Biographies/Germain/"]},{"claim":"1804至1809年与高斯通信，讨论数论研究。","sourceUrls":["https://mathshistory.st-andrews.ac.uk/Biographies/Germain/"]}],"sources":[{"title":"University of St Andrews MacTutor：Sophie Germain","url":"https://mathshistory.st-andrews.ac.uk/Biographies/Germain/","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('barbara-mcclintock','barbara-mcclintock','芭芭拉·麦克林托克','Barbara McClintock','verified','{"id":"barbara-mcclintock","slug":"barbara-mcclintock","nameZh":"芭芭拉·麦克林托克","nameEn":"Barbara McClintock","fields":["科学"],"regions":["美国"],"occupation":"遗传学家、细胞遗传学研究者","keywords":["科学","遗传学家、细胞遗传学研究者"],"summary":"芭芭拉·麦克林托克是美国遗传学家，以玉米染色体和可移动遗传元件研究著称。她1927年在康奈尔大学取得植物学博士学位，1941年前往冷泉港开展研究，后来长期在那里工作。她通过杂交、籽粒性状和显微观察研究遗传变化，发现转座元件，并于1983年获得诺贝尔生理学或医学奖。","story":"麦克林托克在康奈尔大学学习植物学，1927年取得博士学位，逐渐将研究集中于玉米染色体。她结合植物杂交与显微观察，追踪性状和染色体行为。1936年，她到密苏里大学任教，1941年受邀到冷泉港研究，后来在那里长期工作。\n玉米籽粒上的颜色变化成为她研究的重要材料。她将不同品系的杂交结果与染色体观察相联系，识别出能够改变位置、影响基因表现的遗传元件。这些后来被称为转座元件的片段，使研究者重新思考基因在染色体上是否始终固定于同一位置。\n1950年，她发表相关发现，次年在冷泉港研讨会上报告。研究的接受过程并不一致，不能简单写成所有同行都拒绝了她。1983年，她因可移动遗传元件的发现获得诺贝尔生理学或医学奖。她1967年退休后仍继续研究，直至1992年去世。这里依据研究机构档案整理实验方法与职业历程，不采用来源中将玉米染色体交换误举为人类X、Y染色体的说明，也不编造实验室对白。","achievements":["1941年前往冷泉港研究玉米遗传变化，随后长期在那里工作。","1983年因可移动遗传元件研究获得诺贝尔生理学或医学奖。"],"facts":[{"claim":"1941年前往冷泉港研究玉米遗传变化，随后长期在那里工作。","sourceUrls":["https://www.cshl.edu/archives-blog/womens-history-month-barbara-mcclintock/"]},{"claim":"1983年因可移动遗传元件研究获得诺贝尔生理学或医学奖。","sourceUrls":["https://www.cshl.edu/archives-blog/womens-history-month-barbara-mcclintock/"]}],"sources":[{"title":"Cold Spring Harbor Laboratory：Barbara McClintock","url":"https://www.cshl.edu/archives-blog/womens-history-month-barbara-mcclintock/","checkedAt":"2026-11-09"},{"title":"Carnegie Science：Barbara McClintock研究生涯","url":"https://carnegiescience.edu/news/barbara-mcclintock-visionary-ahead-her-time","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1941,"description":"1941年前往冷泉港研究玉米遗传变化，随后长期在那里工作。","sourceUrls":["https://www.cshl.edu/archives-blog/womens-history-month-barbara-mcclintock/"]},{"year":1983,"description":"1983年因可移动遗传元件研究获得诺贝尔生理学或医学奖。","sourceUrls":["https://www.cshl.edu/archives-blog/womens-history-month-barbara-mcclintock/"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('rita-levi-montalcini','rita-levi-montalcini','丽塔·列维-蒙塔尔奇尼','Rita Levi-Montalcini','verified','{"id":"rita-levi-montalcini","slug":"rita-levi-montalcini","nameZh":"丽塔·列维-蒙塔尔奇尼","nameEn":"Rita Levi-Montalcini","fields":["医学"],"regions":["意大利","美国"],"occupation":"神经生物学家、医学研究者","keywords":["医学","神经生物学家、医学研究者"],"summary":"丽塔·列维-蒙塔尔奇尼是意大利神经生物学家，1936年毕业于都灵医学院。她在种族迫害期间离开大学，仍继续胚胎神经研究，后来长期在圣路易斯华盛顿大学工作。她参与发现神经生长因子，1986年与斯坦利·科恩共同获得诺贝尔生理学或医学奖。退休后，她继续在意大利从事科学工作。","story":"列维-蒙塔尔奇尼1936年毕业于都灵医学院。1938年意大利的种族政策使她离开大学，她在私人实验空间继续研究鸡胚神经发育。华盛顿大学的研究回顾指出，她重复相关实验时，区分了神经细胞最初生成与随后存活的问题，这成为理解生长因子的线索。\n她1947年到圣路易斯华盛顿大学，后来与汉堡格及科恩等研究者合作。实验观察、组织培养与生物化学分析分别提供不同证据，逐步帮助识别神经生长因子。她并非独自完成所有实验，相关成果也不等于已经掌握一切神经系统疾病的治疗方法。\n1986年，她与斯坦利·科恩共同获得诺贝尔生理学或医学奖。大学履历记录，她1958至1977年担任动物学教授，1977年退休后继续在意大利研究。她还于1988年出版自传《赞美不完美》。这里采用大学正文核对学历、任职和获奖，保留合作角色；不复写传记中与农场主的对话，不根据获奖经历推断个人动机，也不把后人的纪念评价当作实验结论。","achievements":["1936年毕业于都灵医学院，1947年开始在华盛顿大学工作。","1986年与斯坦利·科恩共同获得诺贝尔生理学或医学奖。"],"facts":[{"claim":"1936年毕业于都灵医学院，1947年开始在华盛顿大学工作。","sourceUrls":["https://source.washu.edu/2013/01/obituary-nobel-laureate-rita-levimontalcini/"]},{"claim":"1986年与斯坦利·科恩共同获得诺贝尔生理学或医学奖。","sourceUrls":["https://source.washu.edu/2013/01/obituary-nobel-laureate-rita-levimontalcini/"]}],"sources":[{"title":"Washington University：Rita Levi-Montalcini讣告与研究回顾","url":"https://source.washu.edu/2013/01/obituary-nobel-laureate-rita-levimontalcini/","checkedAt":"2026-11-09"},{"title":"WashU Medicine：诺贝尔奖得主档案","url":"https://medicine.washu.edu/research/nobel-prize-winners/","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1986,"description":"1986年与斯坦利·科恩共同获得诺贝尔生理学或医学奖。","sourceUrls":["https://source.washu.edu/2013/01/obituary-nobel-laureate-rita-levimontalcini/"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('serena-williams','serena-williams','塞雷娜·威廉姆斯','Serena Williams','verified','{"id":"serena-williams","slug":"serena-williams","nameZh":"塞雷娜·威廉姆斯","nameEn":"Serena Williams","fields":["体育"],"regions":["美国"],"occupation":"职业网球运动员","keywords":["体育","职业网球运动员"],"summary":"塞雷娜·威廉姆斯是美国职业网球运动员，1999年在巴黎获得首个WTA单打冠军。她在澳网、法网、温网与美网均赢得单打冠军，也与维纳斯·威廉姆斯合作参加双打。WTA于2026年6月发布的统计列出她23个大满贯单打冠军及4枚奥运金牌。她的单打、双打与团体搭档成绩需要分别记录。","story":"威廉姆斯的竞技履历横跨单打与双打。WTA记录，她1999年在巴黎室内赛赢得首个巡回赛单打冠军。随后，她在澳大利亚网球公开赛、法国网球公开赛、温布尔登及美国网球公开赛都获得单打冠军，完成单打全满贯。\nWTA于2026年6月1日发布的统计列出，她获得23个大满贯单打冠军，其中澳网与温网各7个、法网3个、美网6个。统计还列出她曾在五个赛季成为年终单打世界第一。这里明确统计来源的时间，避免把某一篇回顾中的累计数量自动当作此后永不变化的现状。\n她与维纳斯·威廉姆斯共同获得14个大满贯女双冠军。奥运会方面，她在2000年悉尼、2008年北京赢得女双金牌，2012年伦敦再获女单和女双金牌。四枚金牌涉及两种比赛形式，不能全部写为单打。人物故事依据官方赛事组织资料整理职业成绩，不添加训练对白、伤病诊断或私人家庭动机，也不从同页的复出预告推定本批未研究的后续比赛结果。","achievements":["1999年在巴黎室内赛赢得首个WTA单打冠军。","2012年伦敦奥运会获得女子单打及女子双打金牌。"],"facts":[{"claim":"1999年在巴黎室内赛赢得首个WTA单打冠军。","sourceUrls":["https://www.wtatennis.com/news/4512405/the-numbers-behind-serena-williams-remarkable-career"]},{"claim":"2012年伦敦奥运会获得女子单打及女子双打金牌。","sourceUrls":["https://www.wtatennis.com/news/4512405/the-numbers-behind-serena-williams-remarkable-career"]}],"sources":[{"title":"WTA：Serena Williams生涯统计，2026年6月1日","url":"https://www.wtatennis.com/news/4512405/the-numbers-behind-serena-williams-remarkable-career","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1999,"description":"1999年在巴黎室内赛赢得首个WTA单打冠军。","sourceUrls":["https://www.wtatennis.com/news/4512405/the-numbers-behind-serena-williams-remarkable-career"]},{"year":2012,"description":"2012年伦敦奥运会获得女子单打及女子双打金牌。","sourceUrls":["https://www.wtatennis.com/news/4512405/the-numbers-behind-serena-williams-remarkable-career"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('sara-blakely','sara-blakely','萨拉·布莱克利','Sara Blakely','verified','{"id":"sara-blakely","slug":"sara-blakely","nameZh":"萨拉·布莱克利","nameEn":"Sara Blakely","fields":["商业"],"regions":["美国"],"occupation":"服装企业创办人、企业家","keywords":["商业","服装企业创办人、企业家"],"summary":"萨拉·布莱克利是美国企业家和服装品牌SPANX创办人。她在销售传真机期间开发内衣产品，2000年创办品牌，后来扩展服装业务。2021年，黑石管理的基金完成对SPANX的多数股权投资，她保留重要股权并担任执行董事长。其经历涉及产品开发、品牌经营与企业股权结构变化，职位以当年公告为准。","story":"布莱克利的创业起点与内衣产品开发有关。SPANX的品牌历史将早期原型追溯至1998年，黑石的交易公告则明确写明品牌由她于2000年创办。两者分别描述原型和企业创立，不能把所有年份混为同一事件。她在此前从事传真机销售，以个人积蓄投入早期开发。\n产品从原型走向商业品牌，涉及设计、知识产权与销售渠道。官方公告记载，她在没有早期外部投资的情况下发展企业；这里保留来源的表述范围，不根据品牌宣传推断每一款产品都由她独立设计，也不采用改变所有女性生活等无法据此验证的评价。\n2021年11月，黑石管理的基金宣布完成多数股权投资，公告估值为12亿美元。布莱克利保留重要股权，并在该次交易时担任执行董事长。企业估值与个人净资产并不相同，历史职位也不能直接当作今天的职位。人物故事采用交易双方资料梳理产品和经营里程碑，不编造融资谈判、采访或私人动机，不据此提供投资判断。","achievements":["2000年创办SPANX。","2021年多数股权交易完成时保留重要股权，并担任执行董事长。"],"facts":[{"claim":"2000年创办SPANX。","sourceUrls":["https://www.blackstone.com/news/press/spanx-inc-and-blackstone-close-majority-sale-secure-new-investors-including-oprah-winfrey-reese-witherspoon-and-whitney-wolfe-herd/"]},{"claim":"2021年多数股权交易完成时保留重要股权，并担任执行董事长。","sourceUrls":["https://www.blackstone.com/news/press/spanx-inc-and-blackstone-close-majority-sale-secure-new-investors-including-oprah-winfrey-reese-witherspoon-and-whitney-wolfe-herd/"]}],"sources":[{"title":"Blackstone：SPANX多数股权交易完成公告，2021年11月18日","url":"https://www.blackstone.com/news/press/spanx-inc-and-blackstone-close-majority-sale-secure-new-investors-including-oprah-winfrey-reese-witherspoon-and-whitney-wolfe-herd/","checkedAt":"2026-11-09"},{"title":"SPANX：品牌历史","url":"https://spanx.com/en-nl/pages/about-us","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":2000,"description":"2000年创办SPANX。","sourceUrls":["https://www.blackstone.com/news/press/spanx-inc-and-blackstone-close-majority-sale-secure-new-investors-including-oprah-winfrey-reese-witherspoon-and-whitney-wolfe-herd/"]},{"year":2021,"description":"2021年多数股权交易完成时保留重要股权，并担任执行董事长。","sourceUrls":["https://www.blackstone.com/news/press/spanx-inc-and-blackstone-close-majority-sale-secure-new-investors-including-oprah-winfrey-reese-witherspoon-and-whitney-wolfe-herd/"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('selma-lagerlof','selma-lagerlof','塞尔玛·拉格洛夫','Selma Lagerlöf','verified','{"id":"selma-lagerlof","slug":"selma-lagerlof","nameZh":"塞尔玛·拉格洛夫","nameEn":"Selma Lagerlöf","fields":["文学"],"regions":["瑞典"],"occupation":"小说家、作家","keywords":["文学","小说家、作家"],"summary":"塞尔玛·拉格洛夫是瑞典小说家，1858年出生并成长于莫尔巴卡。她1891年出版处女作《古斯塔·贝林的故事》，后来创作《耶路撒冷》和《尼尔斯骑鹅旅行记》。她于1909年成为首位获得诺贝尔文学奖的女性，1914年成为瑞典学院首位女性成员。写作之外，她也参与农业经营和地方公共事务。","story":"拉格洛夫出生并成长于瑞典莫尔巴卡。故居纪念机构的作者档案记载，她1891年出版《古斯塔·贝林的故事》，此后继续小说创作，作品包括《耶路撒冷》和《尼尔斯骑鹅旅行记》。这些作品构成她职业写作的重要部分，不能只以一次获奖概括整个创作生涯。\n1909年，她获得诺贝尔文学奖，成为首位获得该奖项的女性。1914年，她又成为瑞典学院首位女性成员。这两项事件发生在不同年份，获奖并不意味着她当时已经属于评奖学院；档案因此分别记录奖项和机构成员身份。\n她的活动也涉及农业经营与地方公共事务。家庭曾出售莫尔巴卡，她1907年购回房屋及周边建筑，获奖后进一步购回土地。1921至1923年，她安排改建房屋，并在遗嘱中规定将其保存为纪念场所。故居因此既保留生活空间，也成为研究其作品之外活动的线索。本批诺贝尔官网传记返回403，以上事实采用已读取的故居机构资料，不复写小说场景或根据人物经历推断创作动机。","achievements":["1891年出版处女作《古斯塔·贝林的故事》。","1909年成为首位获得诺贝尔文学奖的女性，1914年进入瑞典学院。"],"facts":[{"claim":"1891年出版处女作《古斯塔·贝林的故事》。","sourceUrls":["https://marbacka.com/en/forfattaren/"]},{"claim":"1909年成为首位获得诺贝尔文学奖的女性，1914年进入瑞典学院。","sourceUrls":["https://marbacka.com/en/forfattaren/"]}],"sources":[{"title":"Mårbacka Memorial Estate：Selma Lagerlöf","url":"https://marbacka.com/en/forfattaren/","checkedAt":"2026-11-09"},{"title":"Mårbacka：故居历史","url":"https://marbacka.com/hemmet/","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1891,"description":"1891年出版处女作《古斯塔·贝林的故事》。","sourceUrls":["https://marbacka.com/en/forfattaren/"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('berthe-morisot','berthe-morisot','贝尔特·莫里索','Berthe Morisot','verified','{"id":"berthe-morisot","slug":"berthe-morisot","nameZh":"贝尔特·莫里索","nameEn":"Berthe Morisot","fields":["艺术"],"regions":["法国"],"occupation":"画家","keywords":["艺术","画家"],"summary":"贝尔特·莫里索是法国画家，生活于1841至1895年，是印象派群体的重要成员。她的作品曾在巴黎沙龙展出，1874年参加首次印象派展览。她以风景、女性与儿童题材创作，运用松动笔触和明亮色彩。美国国家美术馆收藏并介绍其《姐妹》《餐室》等作品，为研究其创作提供实物与馆藏记录。","story":"莫里索1841年出生于法国，年轻时开始学习绘画。美国国家美术馆的艺术家档案记载，她的作品曾参加巴黎美术学院支持的年度沙龙展览。1874年，她参加首次印象派展览，与莫奈、塞尚等艺术家共同展示作品。沙龙与印象派展览是不同的展示渠道，两者都属于她的职业经历。\n她创作风景，也画女性和儿童。美术馆介绍的《姐妹》作于1869年，作品以较松动的笔触呈现人物；馆藏还包括1886年的《餐室》和1890年的《画家的女儿与长尾鹦鹉》。这些具体作品显示，她对人物、居室与日常场景的观察贯穿不同阶段，而非只出现在某一次展览中。\n莫里索1895年去世。今天的馆藏记录保存了作品名称、年代、媒材和收藏信息，为理解其创作提供依据。对画面中人物心理的解释仍属于艺术评论，不能直接转化成作者本人的生活事实。本档案只按馆方记录介绍作品与参展经历，不把她简化为其他画家的模特或亲属，也不从可浏览的作品图像推定转载许可，人物图片继续使用统一占位图。","achievements":["作品曾在巴黎年度沙龙展览展出。","1874年参加首次印象派展览。"],"facts":[{"claim":"作品曾在巴黎年度沙龙展览展出。","sourceUrls":["https://www.nga.gov/artists/1733-berthe-morisot"]},{"claim":"1874年参加首次印象派展览。","sourceUrls":["https://www.nga.gov/artists/1733-berthe-morisot"]}],"sources":[{"title":"National Gallery of Art：Berthe Morisot","url":"https://www.nga.gov/artists/1733-berthe-morisot","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1874,"description":"1874年参加首次印象派展览。","sourceUrls":["https://www.nga.gov/artists/1733-berthe-morisot"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('savitribai-phule','savitribai-phule','萨维特里芭伊·普勒','Savitribai Phule','verified','{"id":"savitribai-phule","slug":"savitribai-phule","nameZh":"萨维特里芭伊·普勒","nameEn":"Savitribai Phule","fields":["教育"],"regions":["印度"],"occupation":"教师、教育改革者、诗人","keywords":["教育","教师、教育改革者、诗人"],"summary":"萨维特里芭伊·普勒是印度教师、教育改革者和诗人，生活于1831至1897年。她1848年在浦那的女子学校任教，推动女孩及遭种姓排斥群体的教育机会。1854年，她出版诗集《Kavyaphule》，后来也教授农民与工人。她参与妇女权利、教育与救济工作，其生涯体现学校教学与社会改革的联系。","story":"普勒1831年出生于印度萨塔拉地区，后来接受教育并参与教学。印度高校教育资源平台INFLIBNET的课程章节记载，她1848年在浦那的女子学校任教。这项工作发生在女孩及受种姓排斥群体教育机会受限的环境中，与她和焦蒂拉奥·普勒共同参与的教育改革相关。\n她的工作不止于建立学校。课程资料介绍，她通过助学支持和家长参与来维持学生学习，也关注小学教育应适应儿童的需要。1854年，她出版诗集《Kavyaphule》；1855年，她开始在面向农民和工人的学校教学。写作、儿童教育与成人教育由此成为其公共活动的不同组成部分。\n她还参与妇女支持和救济工作，1897年在瘟疫期间照护患者，并于同年去世。这里采用课程章节中明确记录的任教、著作和活动，不将丈夫的全部理论与制度成果归为她个人，也不采用范围过大的印度第一所女子学校绝对断言。人物故事根据教育研究资料独立转述，没有复制诗歌、编造课堂对白或以未经核实的细节描写她遭受的攻击。","achievements":["1848年在浦那的女子学校任教。","1854年出版诗集《Kavyaphule》。"],"facts":[{"claim":"1848年在浦那的女子学校任教。","sourceUrls":["https://ebooks.inflibnet.ac.in/socp13/chapter/193/"]},{"claim":"1854年出版诗集《Kavyaphule》。","sourceUrls":["https://ebooks.inflibnet.ac.in/socp13/chapter/193/"]}],"sources":[{"title":"INFLIBNET Education and Society：Jyotiba与Savitribai Phule","url":"https://ebooks.inflibnet.ac.in/socp13/chapter/193/","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1848,"description":"1848年在浦那的女子学校任教。","sourceUrls":["https://ebooks.inflibnet.ac.in/socp13/chapter/193/"]},{"year":1854,"description":"1854年出版诗集《Kavyaphule》。","sourceUrls":["https://ebooks.inflibnet.ac.in/socp13/chapter/193/"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('michelle-bachelet','michelle-bachelet','米歇尔·巴切莱特','Michelle Bachelet','verified','{"id":"michelle-bachelet","slug":"michelle-bachelet","nameZh":"米歇尔·巴切莱特","nameEn":"Michelle Bachelet","fields":["公共事务"],"regions":["智利"],"occupation":"政治人物、国际组织负责人","keywords":["公共事务","政治人物、国际组织负责人"],"summary":"米歇尔·巴切莱特是智利政治人物，曾担任智利总统及国际组织负责人。她2006年成为智利首位女性总统，2014年再度出任总统。2010年，她成为联合国妇女署首任执行主任，后来担任联合国人权事务高级专员，任职至2022年。她的公共活动涉及国家治理、女性参与决策与国际人权工作。","story":"巴切莱特的公共生涯横跨国家政府与联合国机构。联合国驻越南机构2023年的活动资料回顾，她2006年成为智利首位女性总统，并于2014年第二次出任总统。这是两次不同的任职经历，不能合并为从2006年起连续担任同一职位。\n2010年，她成为联合国妇女署首任执行主任。妇女署的历任负责人页面也列出她2010至2013年的任职记录。本批采用年份范围，不沿用该地区页面可能混淆机构成立与个人任命的起始月份。国际机构的协调职责与国家总统职权不同，因此档案分别保留职务名称及所属机构。\n她后来担任联合国人权事务高级专员，任职至2022年。2023年4月，她参与在越南举行的女性领导力对话，与学生和公共事务参与者讨论女性进入决策岗位的问题。活动介绍提供了这一公共交流的背景，但不能据此把主办方的评价或整场发言写成她的个人名言。这里根据可读取的联合国正文记录职务与活动，没有将旧作者页面的现任总统表述当作今日身份，也不补写政治谈判和私人经历。","achievements":["2006年成为智利首位女性总统，2014年第二次出任总统。","2010年成为联合国妇女署首任执行主任。"],"facts":[{"claim":"2006年成为智利首位女性总统，2014年第二次出任总统。","sourceUrls":["https://vietnam.un.org/en/226075-women%E2%80%99s-leadership-dialogue-series-dialogue-ms-michelle-bachelet"]},{"claim":"2010年成为联合国妇女署首任执行主任。","sourceUrls":["https://vietnam.un.org/en/226075-women%E2%80%99s-leadership-dialogue-series-dialogue-ms-michelle-bachelet"]}],"sources":[{"title":"United Nations in Viet Nam：Michelle Bachelet领导力对话，2023年4月3日","url":"https://vietnam.un.org/en/226075-women%E2%80%99s-leadership-dialogue-series-dialogue-ms-michelle-bachelet","checkedAt":"2026-11-09"},{"title":"UN Women Chile：历任执行主任","url":"https://chile.unwomen.org/es/about-us/directorate","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":2010,"description":"2010年成为联合国妇女署首任执行主任。","sourceUrls":["https://vietnam.un.org/en/226075-women%E2%80%99s-leadership-dialogue-series-dialogue-ms-michelle-bachelet"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('junko-tabei','junko-tabei','田部井淳子','Junko Tabei','verified','{"id":"junko-tabei","slug":"junko-tabei","nameZh":"田部井淳子","nameEn":"Junko Tabei","fields":["探索"],"regions":["日本"],"occupation":"登山家、山地环境倡导者","keywords":["探索","登山家、山地环境倡导者"],"summary":"田部井淳子是日本登山家，1962年毕业于昭和女子大学，1969年建立女子登山组织。1975年，她作为日本女子珠峰远征队成员登顶珠穆朗玛峰，成为首位完成这一攀登的女性。1992年，她成为首位完成七大洲最高峰攀登的女性。她也研究喜马拉雅垃圾问题，并参与山地环境保护与公众教育。","story":"田部井淳子1939年出生于日本福岛县，1962年从昭和女子大学毕业，所学为英美文学。她随后参加登山组织，1969年建立日本女子登山俱乐部。其官方基金会档案将组织工作与海外攀登并列记录，说明她的经历不仅包括到达山顶，也涉及团队和远征活动。\n1975年，她在日本女子珠峰远征队中担任副队长及攀登队负责人，成功登顶珠穆朗玛峰，成为首位登顶女性。她继续前往不同大陆攀登，1992年完成七大洲最高峰，成为首位达成这一目标的女性。这里保留团队身份，不把远征写成单人无协作的行动，也不采用存在日期差异的大学纪念文章。\n她后来将研究兴趣延伸至山地环境，2000年完成九州大学比较社会文化领域硕士课程，研究喜马拉雅垃圾问题。她还在日本喜马拉雅探险信托组织中参与环境宣传与教育。人物故事依据基金会履历整理学习、攀登和环境活动，不补写雪崩现场、攀登对白或内心独白；旧页面保留的现时旅行频率不作为今天的活动状态。","achievements":["1975年登顶珠穆朗玛峰，成为首位登顶女性。","1992年成为首位完成七大洲最高峰攀登的女性。"],"facts":[{"claim":"1975年登顶珠穆朗玛峰，成为首位登顶女性。","sourceUrls":["https://junko-tabei.jp/junko-tabei/english"]},{"claim":"1992年成为首位完成七大洲最高峰攀登的女性。","sourceUrls":["https://junko-tabei.jp/junko-tabei/english"]}],"sources":[{"title":"Junko Tabei Fund：官方英文人物档案","url":"https://junko-tabei.jp/junko-tabei/english","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1975,"description":"1975年登顶珠穆朗玛峰，成为首位登顶女性。","sourceUrls":["https://junko-tabei.jp/junko-tabei/english"]},{"year":1992,"description":"1992年成为首位完成七大洲最高峰攀登的女性。","sourceUrls":["https://junko-tabei.jp/junko-tabei/english"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('sofia-kovalevskaya','sofia-kovalevskaya','索菲娅·科瓦列夫斯卡娅','Sofia Kovalevskaya','verified','{"id":"sofia-kovalevskaya","slug":"sofia-kovalevskaya","nameZh":"索菲娅·科瓦列夫斯卡娅","nameEn":"Sofia Kovalevskaya","fields":["数学"],"regions":["俄罗斯","德国","瑞典"],"occupation":"数学家","keywords":["数学","数学家"],"summary":"索菲娅·科瓦列夫斯卡娅是出生于俄罗斯的数学家，研究偏微分方程、积分及力学问题。她曾在海德堡旁听，并接受魏尔斯特拉斯的私人指导，1874年获哥廷根大学博士学位。1884年，她开始在斯德哥尔摩讲授偏微分方程，并获高等分析教授职位。其求学与任教经历跨越俄罗斯、德国和瑞典。","story":"科瓦列夫斯卡娅在俄罗斯接受早期数学教育，1869年前往海德堡学习。当地大学当时不允许女性正式注册，她在获得教师许可后旁听数学与自然科学课程。后来，她到柏林接受魏尔斯特拉斯的私人指导，大学仍未允许她进入正式课堂。\n到1874年，她完成关于偏微分方程、阿贝尔积分和土星环的三篇论文。同年，哥廷根大学依据论文及学者评议授予她博士学位。圣安德鲁斯大学的数学史档案明确区分了授予学位的机构和她接受指导的地点，因此不能将这段经历写成在柏林取得博士。\n回到俄罗斯后，她未能立即获得学术职位，后来重返研究。1884年，她在斯德哥尔摩开始用德语讲授偏微分方程，当年6月获得为期五年的高等分析教授职位，随后按要求用瑞典语教学。她1891年在斯德哥尔摩去世。本档案以课程、论文和任职记录呈现其数学活动，不根据私人书信增写婚姻动机，也不将历史职位名称笼统改为今天的终身教职。","achievements":["1874年获哥廷根大学博士学位。","1884年在斯德哥尔摩开始讲授偏微分方程，并获高等分析教授职位。"],"facts":[{"claim":"1874年获哥廷根大学博士学位。","sourceUrls":["https://mathshistory.st-andrews.ac.uk/Biographies/Kovalevskaya/"]},{"claim":"1884年在斯德哥尔摩开始讲授偏微分方程，并获高等分析教授职位。","sourceUrls":["https://mathshistory.st-andrews.ac.uk/Biographies/Kovalevskaya/"]}],"sources":[{"title":"University of St Andrews MacTutor：Sofia Kovalevskaya","url":"https://mathshistory.st-andrews.ac.uk/Biographies/Kovalevskaya/","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1874,"description":"1874年获哥廷根大学博士学位。","sourceUrls":["https://mathshistory.st-andrews.ac.uk/Biographies/Kovalevskaya/"]},{"year":1884,"description":"1884年在斯德哥尔摩开始讲授偏微分方程，并获高等分析教授职位。","sourceUrls":["https://mathshistory.st-andrews.ac.uk/Biographies/Kovalevskaya/"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('dorothy-hodgkin','dorothy-hodgkin','多萝西·霍奇金','Dorothy Hodgkin','verified','{"id":"dorothy-hodgkin","slug":"dorothy-hodgkin","nameZh":"多萝西·霍奇金","nameEn":"Dorothy Hodgkin","fields":["科学"],"regions":["英国"],"occupation":"化学家、晶体学家","keywords":["科学","化学家、晶体学家"],"summary":"多萝西·霍奇金是英国化学家和晶体学家，长期在牛津大学萨默维尔学院研究与教学。她利用X射线衍射研究青霉素、维生素B12等生物分子结构，1964年获得诺贝尔化学奖。1969年，她与团队解析胰岛素结构。她也支持女性学者的职业发展，并参与学院托儿设施的建立。","story":"霍奇金在牛津萨默维尔学院学习化学，随后到剑桥从事研究，1935年取得博士学位。她1934年已受邀返回萨默维尔，后来长期承担研究与教学。X射线衍射为她提供了从实验数据认识分子空间结构的方法，这项工作依赖测量、计算与模型之间的反复核对。\n她研究青霉素和维生素B12的结构，并于1964年获得诺贝尔化学奖。胰岛素是另一项持续多年的研究：学院资料记载，她1934年开始相关探索，直到1969年才与团队解析其结构。因此，不能把1969年的成果写成1964年获奖时已经完成。\n她1955年获大学高级教职，1960年成为沃尔夫森研究教授，1970年获选布里斯托大学校监。她也支持萨默维尔的托儿设施，为女性学者提供工作条件。学院保存的论文与分子模型成为后续研究和教学材料。本档案将学位、奖项与不同分子的结构研究分开记录，不把解析分子结构写成发现或发明这些物质，也不从基础研究直接推出具体治疗成效。","achievements":["1964年获得诺贝尔化学奖。","1969年与团队解析胰岛素结构。"],"facts":[{"claim":"1964年获得诺贝尔化学奖。","sourceUrls":["https://www.some.ox.ac.uk/news/somerville-student-rebuilds-dorothy-hodgkins-insulin-model/"]},{"claim":"1969年与团队解析胰岛素结构。","sourceUrls":["https://www.some.ox.ac.uk/news/somerville-student-rebuilds-dorothy-hodgkins-insulin-model/"]}],"sources":[{"title":"Somerville College Oxford：霍奇金胰岛素模型与研究史","url":"https://www.some.ox.ac.uk/news/somerville-student-rebuilds-dorothy-hodgkins-insulin-model/","checkedAt":"2026-11-09"},{"title":"Somerville College Oxford：霍奇金纪念牌与生平","url":"https://www.some.ox.ac.uk/news/blue-plaque-unveiled-honouring-dorothy-hodgkin-1910-1994/","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1964,"description":"1964年获得诺贝尔化学奖。","sourceUrls":["https://www.some.ox.ac.uk/news/somerville-student-rebuilds-dorothy-hodgkins-insulin-model/"]},{"year":1969,"description":"1969年与团队解析胰岛素结构。","sourceUrls":["https://www.some.ox.ac.uk/news/somerville-student-rebuilds-dorothy-hodgkins-insulin-model/"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('patricia-bath','patricia-bath','帕特里夏·巴斯','Patricia Bath','verified','{"id":"patricia-bath","slug":"patricia-bath","nameZh":"帕特里夏·巴斯","nameEn":"Patricia Bath","fields":["医学"],"regions":["美国"],"occupation":"眼科医生、激光研究者、发明人","keywords":["医学","眼科医生、激光研究者、发明人"],"summary":"帕特里夏·巴斯是美国眼科医生、激光研究者和发明人，毕业于霍华德大学医学院，接受眼科与角膜相关训练。她提出社区眼科理念，关注医疗资源不足群体的视力照护。1977年，她与同事创办美国防盲研究所；1983年负责Drew-UCLA眼科住院医师培训项目，并研究用于白内障手术的激光设备。","story":"巴斯在霍华德大学取得医学学位，随后于哈莱姆医院实习，并在哥伦比亚大学、纽约大学接受进一步眼科训练。她观察不同机构服务人群的视力问题，通过回顾性研究关注眼科服务可及性的差异，将临床工作与公共卫生问题联系起来。\n她提出社区眼科理念，结合基层医疗、社区服务与专科检查，面向缺乏常规照护的人群。1977年，她与三位同事创办美国防盲研究所。美国国家医学图书馆的传记将该机构的教育、筛查与服务活动并列介绍，说明她的工作不限于手术室和大学实验室。\n1983年，她负责Drew-UCLA的眼科住院医师培训项目，成为美国首位担任此类项目负责人的女性。她还研究用于白内障手术的laserphaco设备与方法，并在欧美机构开展激光研究。1993年从UCLA医疗中心退休后，她继续倡导远程医疗。本档案区分任职、设备构想、研究测试和专利，不把来源里不同UCLA岗位的1974、1975年合并为一项任命，也不添加治愈承诺、采访对白或未核实的专利日期。","achievements":["1977年与三位同事创办美国防盲研究所。","1983年负责Drew-UCLA眼科住院医师培训项目，为美国首位担任此类负责人的女性。"],"facts":[{"claim":"1977年与三位同事创办美国防盲研究所。","sourceUrls":["https://www.nlm.nih.gov/exhibition/changing-the-face-of-medicine/physicians/biography_patricia-bath.html?id=item-25"]},{"claim":"1983年负责Drew-UCLA眼科住院医师培训项目，为美国首位担任此类负责人的女性。","sourceUrls":["https://www.nlm.nih.gov/exhibition/changing-the-face-of-medicine/physicians/biography_patricia-bath.html?id=item-25"]}],"sources":[{"title":"National Library of Medicine：Patricia E. Bath传记","url":"https://www.nlm.nih.gov/exhibition/changing-the-face-of-medicine/physicians/biography_patricia-bath.html?id=item-25","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1977,"description":"1977年与三位同事创办美国防盲研究所。","sourceUrls":["https://www.nlm.nih.gov/exhibition/changing-the-face-of-medicine/physicians/biography_patricia-bath.html?id=item-25"]},{"year":1983,"description":"1983年负责Drew-UCLA眼科住院医师培训项目，为美国首位担任此类负责人的女性。","sourceUrls":["https://www.nlm.nih.gov/exhibition/changing-the-face-of-medicine/physicians/biography_patricia-bath.html?id=item-25"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('alice-coachman','alice-coachman','艾丽斯·科奇曼','Alice Coachman','verified','{"id":"alice-coachman","slug":"alice-coachman","nameZh":"艾丽斯·科奇曼","nameEn":"Alice Coachman","fields":["体育"],"regions":["美国"],"occupation":"田径运动员、教师","keywords":["体育","田径运动员、教师"],"summary":"艾丽斯·科奇曼是美国田径运动员，擅长跳高，也参加短跑和接力。她1939至1948年连续十次获得全国跳高冠军，1948年赢得伦敦奥运会跳高金牌，成为首位获得奥运金牌的黑人女性。退役后，她从事学校教育，并建立基金会支持青年运动员和经济困难的前运动员，延续与体育教育的联系。","story":"科奇曼出生于美国佐治亚州奥尔巴尼，在种族隔离环境中成长，训练与参赛机会受到限制。美国田径协会的档案记录，她后来在塔斯基吉和奥尔巴尼州立学院学习，逐步建立全国赛成绩。她不仅参加跳高，也在短跑及接力项目中夺冠。\n1939至1948年，她连续十次赢得全国跳高冠军。第二次世界大战限制了此前的国际比赛机会，1948年伦敦奥运会成为她的重要国际赛事。她以1.68米赢得女子跳高金牌并创造当时奥运纪录，成为首位获得奥运金牌的黑人女性。这里保留纪录的历史时间，不写成至今仍保持的世界纪录。\n她在该届奥运会后退役，后来担任学校教师和教练，并创办艾丽斯·科奇曼田径基金会，支持青年运动员及有经济困难的前运动员。协会同时保留逐年全国赛和奥运成绩，便于将不同项目分开核对。本档案不采用与其他官方简介存在差异的出生年份，不复写训练中的戏剧性对白，也不将基金会的全部工作归为她个人完成。","achievements":["1939至1948年连续十次获得全国跳高冠军。","1948年伦敦奥运会以1.68米夺女子跳高金牌，成为首位获得奥运金牌的黑人女性。"],"facts":[{"claim":"1939至1948年连续十次获得全国跳高冠军。","sourceUrls":["https://www.usatf.org/athlete-bios/alice-coachman"]},{"claim":"1948年伦敦奥运会以1.68米夺女子跳高金牌，成为首位获得奥运金牌的黑人女性。","sourceUrls":["https://www.usatf.org/athlete-bios/alice-coachman"]}],"sources":[{"title":"USA Track & Field：Alice Coachman官方档案","url":"https://www.usatf.org/athlete-bios/alice-coachman","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1948,"description":"1948年伦敦奥运会以1.68米夺女子跳高金牌，成为首位获得奥运金牌的黑人女性。","sourceUrls":["https://www.usatf.org/athlete-bios/alice-coachman"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('mary-barra','mary-barra','玛丽·博拉','Mary Barra','verified','{"id":"mary-barra","slug":"mary-barra","nameZh":"玛丽·博拉","nameEn":"Mary Barra","fields":["商业"],"regions":["美国"],"occupation":"汽车行业企业管理者、工程师","keywords":["商业","汽车行业企业管理者、工程师"],"summary":"玛丽·博拉是美国汽车行业企业管理者，拥有电气工程与工商管理教育背景。她1980年以工学合作学生身份进入通用汽车，后来负责产品开发、采购与供应链等工作。她于2014年出任通用汽车首席执行官，2016年获选董事会主席。其职业经历连接工程学习、制造企业运营和大型公司的管理职责。","story":"博拉1980年以通用汽车学院工学合作学生身份进入通用汽车庞蒂亚克部门。公司履历记载，她1985年获得电气工程理学学士学位，1990年取得斯坦福大学商学院工商管理硕士学位。学习与企业实践由此构成她早期职业发展的两条线索。\n在成为首席执行官之前，她承担全球产品开发相关管理工作，后来负责产品开发、采购及供应链。这些职责涉及汽车从工程设计到生产交付的多个环节，不能将公司全部产品或技术成果归为某位高管个人发明。2014年，她出任通用汽车首席执行官；2016年，获选董事会主席。\n首席执行官与董事会主席是不同职务，生效年份也不同。这里根据公司官方履历分别记录任命，不将两个职位都写成2014年取得，也不从旧页列举的董事席位推断今天仍兼任相同职务。人物故事聚焦教育、工程和企业管理路径，没有采用品牌宣传中的创新成效作为独立验证结论，也不编造董事会谈判、私人动机、财富排名或未来经营预测。","achievements":["1980年以工学合作学生身份进入通用汽车庞蒂亚克部门。","2014年出任通用汽车首席执行官，2016年获选董事会主席。"],"facts":[{"claim":"1980年以工学合作学生身份进入通用汽车庞蒂亚克部门。","sourceUrls":["https://www.gm.com/company/leadership.detail.html/Pages/bios/global/en/corporate-officers/Mary-Barra"]},{"claim":"2014年出任通用汽车首席执行官，2016年获选董事会主席。","sourceUrls":["https://www.gm.com/company/leadership.detail.html/Pages/bios/global/en/corporate-officers/Mary-Barra"]}],"sources":[{"title":"General Motors：Mary T. Barra官方履历","url":"https://www.gm.com/company/leadership.detail.html/Pages/bios/global/en/corporate-officers/Mary-Barra","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1980,"description":"1980年以工学合作学生身份进入通用汽车庞蒂亚克部门。","sourceUrls":["https://www.gm.com/company/leadership.detail.html/Pages/bios/global/en/corporate-officers/Mary-Barra"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('gabriela-mistral','gabriela-mistral','加夫列拉·米斯特拉尔','Gabriela Mistral','verified','{"id":"gabriela-mistral","slug":"gabriela-mistral","nameZh":"加夫列拉·米斯特拉尔","nameEn":"Gabriela Mistral","fields":["文学"],"regions":["智利","墨西哥","美国"],"occupation":"诗人、教育工作者、外交官","keywords":["文学","诗人、教育工作者、外交官"],"summary":"加夫列拉·米斯特拉尔是智利诗人、教育工作者和外交官，原名露西拉·戈多伊·阿尔卡亚加。她曾在智利多地任教，1922年前往墨西哥参与教育改革，同年在纽约出版首部诗集《绝望》。她1945年获得诺贝尔文学奖，1951年获智利国家文学奖。作品还包括《柔情》《塔拉》和《压榨机》。","story":"米斯特拉尔1889年出生于智利比库尼亚，原名露西拉·戈多伊·阿尔卡亚加。智利国家图书馆的专题记录，她约1905年开始担任学校助教，后来在智利不同城市工作。教学与诗歌写作同时发展，地方报刊传播了她的早期文章和诗作。\n1922年，她受邀前往墨西哥，参与教育改革与公共图书馆建设。同年，她的首部诗集《绝望》在纽约出版。她随后在墨西哥、西班牙及阿根廷等地出版作品，1938年发表《塔拉》。这些版本跨越不同国家，馆藏中某一版本的印刷年份不能直接当作作品首次发表年份。\n1945年，她获得诺贝尔文学奖，六年后获得智利国家文学奖。她也从事领事与公共文化工作，1954年出版《压榨机》，去世后仍有未刊诗文被整理成书。这里依据图书馆对作品与职业经历的梳理，不将其文学身份仅归结为母亲或教师的形象，也不根据私人生活解释每一首诗。人物故事独立转述出版、教育和获奖事实，没有复制诗歌或编造与其他作家的对话。","achievements":["1922年在纽约出版首部诗集《绝望》。","1945年获得诺贝尔文学奖，1951年获智利国家文学奖。"],"facts":[{"claim":"1922年在纽约出版首部诗集《绝望》。","sourceUrls":["https://www.memoriachilena.gob.cl/602/w3-article-3429.html"]},{"claim":"1945年获得诺贝尔文学奖，1951年获智利国家文学奖。","sourceUrls":["https://www.memoriachilena.gob.cl/602/w3-article-3429.html"]}],"sources":[{"title":"Biblioteca Nacional de Chile Memoria Chilena：Gabriela Mistral","url":"https://www.memoriachilena.gob.cl/602/w3-article-3429.html","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1922,"description":"1922年在纽约出版首部诗集《绝望》。","sourceUrls":["https://www.memoriachilena.gob.cl/602/w3-article-3429.html"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('alma-thomas','alma-thomas','阿尔玛·托马斯','Alma Thomas','verified','{"id":"alma-thomas","slug":"alma-thomas","nameZh":"阿尔玛·托马斯","nameEn":"Alma Thomas","fields":["艺术"],"regions":["美国"],"occupation":"画家、美术教师","keywords":["艺术","画家、美术教师"],"summary":"阿尔玛·托马斯是美国画家和美术教师，1924年成为霍华德大学首位美术专业毕业生，后来长期在华盛顿公立学校任教。她在退休后发展出以鲜明色块和节奏性排列构成的抽象绘画，题材联系自然与太空时代。1972年，她成为首位在惠特尼美国艺术博物馆举办个展的黑人女性，作品由多家机构收藏。","story":"托马斯1891年出生于美国佐治亚州，1907年随家人迁居华盛顿。史密森美国艺术博物馆的传记记录，她1924年成为霍华德大学首位美术专业毕业生，1934年在哥伦比亚大学获得艺术教育硕士学位，长期在肖初中从事教学。\n她在教学之外继续学习与创作，1950年代在美利坚大学学习艺术，并参与华盛顿的艺术组织和画廊活动。1960年退休后，她逐渐形成标志性的抽象风格，用小块鲜明色彩组成有节奏的图案。花园、公园与自然形态，以及早期太空探索带来的视觉经验，成为理解部分作品的线索。\n1972年，她在惠特尼美国艺术博物馆举办个展，是首位在那里举办个展的黑人女性。《日食》《心宿二》等作品呈现其成熟阶段的绘画。今天的馆藏与档案保留作品、教学及展览信息，不能把晚年成名误写成此前没有创作。这里采用馆方2024年传记，不强行统一同页不同旧传记对任教年数的口径，不根据画面推断私人情绪，也未下载许可不明的人物或作品图片。","achievements":["1924年成为霍华德大学首位美术专业毕业生。","1972年成为首位在惠特尼美国艺术博物馆举办个展的黑人女性。"],"facts":[{"claim":"1924年成为霍华德大学首位美术专业毕业生。","sourceUrls":["https://americanart.si.edu/artist/alma-thomas-4778"]},{"claim":"1972年成为首位在惠特尼美国艺术博物馆举办个展的黑人女性。","sourceUrls":["https://americanart.si.edu/artist/alma-thomas-4778"]}],"sources":[{"title":"Smithsonian American Art Museum：Alma Thomas","url":"https://americanart.si.edu/artist/alma-thomas-4778","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1924,"description":"1924年成为霍华德大学首位美术专业毕业生。","sourceUrls":["https://americanart.si.edu/artist/alma-thomas-4778"]},{"year":1972,"description":"1972年成为首位在惠特尼美国艺术博物馆举办个展的黑人女性。","sourceUrls":["https://americanart.si.edu/artist/alma-thomas-4778"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('mary-lyon','mary-lyon','玛丽·莱昂','Mary Lyon','verified','{"id":"mary-lyon","slug":"mary-lyon","nameZh":"玛丽·莱昂","nameEn":"Mary Lyon","fields":["教育"],"regions":["美国"],"occupation":"教育家、学校创办人","keywords":["教育","教育家、学校创办人"],"summary":"玛丽·莱昂是美国教育家和学校创办人。她曾在伊普斯威奇女子学校担任助理校长，后来筹建蒙特霍利约克女子学院的前身。学校1837年开学，她担任负责人至1849年。她推动严格入学考试、较低学费与广泛募资，并将课程、寄宿生活和学生劳动结合起来，扩大女性接受较高层次教育的机会。","story":"莱昂在创办蒙特霍利约克之前，曾担任伊普斯威奇女子学校助理校长。1834年，她决定集中力量建立新的女性教育机构。学院的创校档案记录，她筹款、访问学校、制定课程、选择地点，并参与校舍建设和师资招募；这是一项持续多年的组织工作。\n1837年11月8日，蒙特霍利约克女子学校开学，首批约80名学生入学。她设置入学考试，要求学生具备相应学习基础，同时以较低学费和广泛社会捐助维持学校。学生参与部分日常劳动，以控制运营成本。课程、住宿和财务安排共同构成这一办学模式，不能只用创始人的个人意志解释其延续。\n学院图书馆的历任负责人表将她列为1837至1849年的创办人和校长。今天的学院名称与早期机构名称不同，档案因此保留历史语境。这里依据学校与图书馆资料叙述筹建、开学和制度安排，不采用美国此前完全没有女性高等教育机构的绝对说法，也不把十九世纪的seminary理解为今天单一类型的神学院；人物故事未添加募款谈判或课堂对白。","achievements":["1837年创办的蒙特霍利约克女子学校开学，首批约80名学生入学。","1837至1849年担任蒙特霍利约克创办人和校长。"],"facts":[{"claim":"1837年创办的蒙特霍利约克女子学校开学，首批约80名学生入学。","sourceUrls":["https://connect.mtholyoke.edu/marketing-and-communications/Mary-lyon/founding"]},{"claim":"1837至1849年担任蒙特霍利约克创办人和校长。","sourceUrls":["https://lits.mtholyoke.edu/archives-special-collections/asc-research/research-guides/presidents-mount-holyoke"]}],"sources":[{"title":"Mount Holyoke College：创校与早期历史","url":"https://connect.mtholyoke.edu/marketing-and-communications/Mary-lyon/founding","checkedAt":"2026-11-09"},{"title":"Mount Holyoke LITS：历任负责人档案","url":"https://lits.mtholyoke.edu/archives-special-collections/asc-research/research-guides/presidents-mount-holyoke","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1837,"description":"1837年创办的蒙特霍利约克女子学校开学，首批约80名学生入学。","sourceUrls":["https://connect.mtholyoke.edu/marketing-and-communications/Mary-lyon/founding"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('ellen-johnson-sirleaf','ellen-johnson-sirleaf','埃伦·约翰逊·瑟利夫','Ellen Johnson Sirleaf','verified','{"id":"ellen-johnson-sirleaf","slug":"ellen-johnson-sirleaf","nameZh":"埃伦·约翰逊·瑟利夫","nameEn":"Ellen Johnson Sirleaf","fields":["公共事务"],"regions":["利比里亚"],"occupation":"政治人物、经济与发展政策工作者","keywords":["公共事务","政治人物、经济与发展政策工作者"],"summary":"埃伦·约翰逊·瑟利夫是利比里亚政治人物，早年从事财政、金融和发展政策工作。她2005年当选总统，2006年就职，成为非洲首位经民主选举产生的女性国家元首，2011年赢得连任。她也于2011年获得诺贝尔和平奖。其职业经历包括政府财政部门、国际银行和联合国开发计划署的工作。","story":"瑟利夫的职业路径连接利比里亚政府、金融机构和国际发展组织。以她命名的总统中心履历记载，她1965年进入财政部门，1979年担任财政部长，后来在银行及国际机构工作。她也曾负责联合国开发计划署非洲地区事务，并取得哈佛大学公共管理硕士学位。\n2005年，她当选利比里亚总统，于2006年1月16日就职，成为非洲首位经民主选举产生的女性国家元首。选举与就职属于两个年份，不能互相替代。她2011年赢得连任，并于同年获得诺贝尔和平奖；本档案不将获奖写成她独自完成和平建设。\n她的任内工作涉及战后重建和公共治理，2016年还获选西非国家经济共同体主席，任期一年。总统中心的介绍同时具有纪念与倡导性质，经济成效和评价仍需独立数据支持，因此这里只保留明确的职务、日期和活动。她2008年出版回忆录《This Child Will Be Great》，为研究个人经历提供另一类材料；本批未将回忆录内容当作已读取证据，也没有编造竞选对白、私人动机或政策谈判场景。","achievements":["2005年当选利比里亚总统，2006年1月16日就职。","2011年赢得总统连任，并获诺贝尔和平奖。"],"facts":[{"claim":"2005年当选利比里亚总统，2006年1月16日就职。","sourceUrls":["https://ejscenter.org/our-teams/ellen-johnson-sirleaf/"]},{"claim":"2011年赢得总统连任，并获诺贝尔和平奖。","sourceUrls":["https://ejscenter.org/our-teams/ellen-johnson-sirleaf/"]}],"sources":[{"title":"Ellen Johnson Sirleaf Presidential Center：官方人物履历","url":"https://ejscenter.org/our-teams/ellen-johnson-sirleaf/","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":2011,"description":"2011年赢得总统连任，并获诺贝尔和平奖。","sourceUrls":["https://ejscenter.org/our-teams/ellen-johnson-sirleaf/"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('jessica-watson','jessica-watson','杰西卡·沃森','Jessica Watson','verified','{"id":"jessica-watson","slug":"jessica-watson","nameZh":"杰西卡·沃森","nameEn":"Jessica Watson","fields":["探索"],"regions":["澳大利亚"],"occupation":"帆船航海者、作家","keywords":["探索","帆船航海者、作家"],"summary":"杰西卡·沃森是澳大利亚帆船航海者和作家。她16岁时进行单人不间断远洋航行，历时210天，于2010年5月返回悉尼。她以《True Spirit》记录航程，2011年获澳大利亚年度青年人物称号。她也创作青少年小说，并参与青年帆船团队及世界粮食计划署青年代表活动。","story":"沃森的远洋经历在个人官网和澳大利亚年度人物档案中均有记录。她16岁时驾驶帆船进行单人不间断航行，经过南大洋和合恩角等海域，历时210天后于2010年5月返回悉尼。航行中，她通过博客与岸上读者保持信息联系，因此单人驾驶不应被解释为完全没有外部通信。\n她在《True Spirit》中叙述航程，作品后来获得澳大利亚图书业奖项。2011年，她被评为澳大利亚年度青年人物。官网还介绍她后来参与青年团队的悉尼至霍巴特帆船赛，以及通过世界粮食计划署青年代表活动前往不同地区的经历。\n写作成为她航海之外的另一项工作，她还创作面向青少年读者的小说《Indigo Blue》。官网上的年龄和职业措辞可能保留较早更新时间，本档案不直接当作今日状态。对于航程，记录完成时间和持续天数，不使用最年轻环球纪录已获认证等需要另行核对规则的断言，也不将影视改编或小说人物的经历混入真实生平；未补写海上对白、心理独白和未核实的惊险场景。","achievements":["历时210天的单人航行于2010年5月15日返回陆地。","2011年获澳大利亚年度青年人物称号。"],"facts":[{"claim":"历时210天的单人航行于2010年5月15日返回陆地。","sourceUrls":["https://www.jessicawatson.com.au/books"]},{"claim":"2011年获澳大利亚年度青年人物称号。","sourceUrls":["https://australianoftheyear.org.au/recipients/jessica-watson-oam"]}],"sources":[{"title":"Jessica Watson：官方图书与航程介绍","url":"https://www.jessicawatson.com.au/books","checkedAt":"2026-11-09"},{"title":"Australian of the Year：Jessica Watson OAM获奖档案","url":"https://australianoftheyear.org.au/recipients/jessica-watson-oam","checkedAt":"2026-11-09"},{"title":"Jessica Watson：官方人物简介","url":"https://www.jessicawatson.com.au/about","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":2010,"description":"历时210天的单人航行于2010年5月15日返回陆地。","sourceUrls":["https://www.jessicawatson.com.au/books"]},{"year":2011,"description":"2011年获澳大利亚年度青年人物称号。","sourceUrls":["https://australianoftheyear.org.au/recipients/jessica-watson-oam"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('karen-uhlenbeck','karen-uhlenbeck','凯伦·乌伦贝克','Karen Uhlenbeck','verified','{"id":"karen-uhlenbeck","slug":"karen-uhlenbeck","nameZh":"凯伦·乌伦贝克","nameEn":"Karen Uhlenbeck","fields":["数学"],"regions":["美国"],"occupation":"数学家","keywords":["数学","数学家"],"summary":"凯伦·乌伦贝克是美国数学家，研究几何偏微分方程、规范理论和可积系统。她在密歇根大学学习后，于布兰代斯大学取得数学博士学位，曾在芝加哥和得克萨斯等地任教。1990年，她在国际数学家大会作大会报告，2000年获美国国家科学奖章，2019年获阿贝尔奖，其研究连接分析、几何与数学物理。","story":"乌伦贝克在密歇根大学学习，1964年毕业，随后到布兰代斯大学从事数学博士研究，方向涉及变分法。阿贝尔奖的官方传记将她的学习与后续研究联系起来：她也接触广义相对论和时空几何，发展出横跨分析、几何及理论物理的研究路径。\n1971年，她在伊利诺伊大学厄巴纳—香槟分校任助理教授，后来转到芝加哥的学术机构，1987年前往得克萨斯大学奥斯汀分校。她的工作包括研究四维空间中的杨—米尔斯方程，并与丹·弗里德合著《Instantons and 4-Manifolds》。这些活动涉及独立论文、合作写作与长期教学。\n1990年，她在京都国际数学家大会作大会报告；2000年，获得美国国家科学奖章；2019年，获得阿贝尔奖。颁奖说明强调她在几何偏微分方程、规范理论和可积系统方面的贡献。她也倡导数学领域更广泛的女性参与。本档案按官方材料保留研究方向和职业里程碑，不将传记中的心理解释改写成个人独白，也不把复杂数学贡献简化成一项未经限定的万能解法。","achievements":["2019年获得阿贝尔奖，获奖工作涉及几何偏微分方程、规范理论与可积系统。","1990年在京都国际数学家大会作大会报告。"],"facts":[{"claim":"2019年获得阿贝尔奖，获奖工作涉及几何偏微分方程、规范理论与可积系统。","sourceUrls":["https://abelprize.no/abel-prize-laureates/2019"]},{"claim":"1990年在京都国际数学家大会作大会报告。","sourceUrls":["https://abelprize.no/sites/default/files/2021-04/biography_English_Karen_Uhlenbeck_2019_abel.pdf"]}],"sources":[{"title":"The Abel Prize：2019年得主Karen Keskulla Uhlenbeck","url":"https://abelprize.no/abel-prize-laureates/2019","checkedAt":"2026-11-09"},{"title":"The Abel Prize：Karen Uhlenbeck官方传记","url":"https://abelprize.no/sites/default/files/2021-04/biography_English_Karen_Uhlenbeck_2019_abel.pdf","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1990,"description":"1990年在京都国际数学家大会作大会报告。","sourceUrls":["https://abelprize.no/sites/default/files/2021-04/biography_English_Karen_Uhlenbeck_2019_abel.pdf"]},{"year":2019,"description":"2019年获得阿贝尔奖，获奖工作涉及几何偏微分方程、规范理论与可积系统。","sourceUrls":["https://abelprize.no/abel-prize-laureates/2019"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('cecilia-payne-gaposchkin','cecilia-payne-gaposchkin','塞西莉亚·佩恩-加波施金','Cecilia Payne-Gaposchkin','verified','{"id":"cecilia-payne-gaposchkin","slug":"cecilia-payne-gaposchkin","nameZh":"塞西莉亚·佩恩-加波施金","nameEn":"Cecilia Payne-Gaposchkin","fields":["科学"],"regions":["英国","美国"],"occupation":"天文学家、天体物理学家","keywords":["科学","天文学家、天体物理学家"],"summary":"塞西莉亚·佩恩-加波施金是出生于英国的天文学家，1923年前往哈佛天文台，1925年获拉德克利夫学院博士学位。她通过恒星光谱研究指出氢和氦在恒星大气中的重要地位，改变了对恒星组成的认识。1956年，她晋升哈佛正教授，随后担任天文学系负责人，长期从事研究、教学与学术合作。","story":"佩恩-加波施金在剑桥纽纳姆学院学习，1923年前往美国哈佛天文台继续研究。天文台保存的观测底片和光谱材料为她提供了分析对象，她结合物理知识研究恒星大气中不同元素的丰度。光谱并不直接展示物质清单，需要通过理论与计算解释。\n1925年，她获得拉德克利夫学院博士学位，论文讨论恒星组成。她的计算指出氢和氦远比其他元素丰富，与当时认为恒星组成近似地球的看法不同。这一结论起初受到质疑，后来得到进一步确认。研究史因此既包含她的计算，也包含结果被讨论和接受的过程。\n她留在哈佛继续研究与教学，并与天文学家谢尔盖·加波施金长期合作。1956年，她晋升正教授，随后担任系负责人，直至晚年仍持续发表研究。这里采用哈佛2026年人物回顾和天文学系历史核对学位、研究及职位，不将拉德克利夫授予学位笼统改写为当时哈佛直接授予，也不复制来源中的私人信件或以现代身份标签代替具体学术工作。","achievements":["1925年获得拉德克利夫学院博士学位。","1956年晋升哈佛正教授，随后担任天文学系负责人。"],"facts":[{"claim":"1925年获得拉德克利夫学院博士学位。","sourceUrls":["https://current.fas.harvard.edu/stories/harvard-astronomer-our-heroine-20th-century-memorialized-london"]},{"claim":"1956年晋升哈佛正教授，随后担任天文学系负责人。","sourceUrls":["https://current.fas.harvard.edu/stories/harvard-astronomer-our-heroine-20th-century-memorialized-london"]}],"sources":[{"title":"Harvard FAS：Cecilia Payne-Gaposchkin研究与生涯，2026年6月","url":"https://current.fas.harvard.edu/stories/harvard-astronomer-our-heroine-20th-century-memorialized-london","checkedAt":"2026-11-09"},{"title":"Harvard Department of Astronomy：天文台历史","url":"https://astronomy.fas.harvard.edu/history","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1925,"description":"1925年获得拉德克利夫学院博士学位。","sourceUrls":["https://current.fas.harvard.edu/stories/harvard-astronomer-our-heroine-20th-century-memorialized-london"]},{"year":1956,"description":"1956年晋升哈佛正教授，随后担任天文学系负责人。","sourceUrls":["https://current.fas.harvard.edu/stories/harvard-astronomer-our-heroine-20th-century-memorialized-london"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('francoise-barre-sinoussi','francoise-barre-sinoussi','弗朗索瓦丝·巴雷-西努西','Françoise Barré-Sinoussi','verified','{"id":"francoise-barre-sinoussi","slug":"francoise-barre-sinoussi","nameZh":"弗朗索瓦丝·巴雷-西努西","nameEn":"Françoise Barré-Sinoussi","fields":["医学"],"regions":["法国"],"occupation":"逆转录病毒学家、医学研究者","keywords":["医学","逆转录病毒学家、医学研究者"],"summary":"弗朗索瓦丝·巴雷-西努西是法国逆转录病毒学家，自二十世纪七十年代起研究逆转录病毒。她是1983年报告后来称为HIV的病毒发现论文的第一作者，2008年获诺贝尔生理学或医学奖。她1988年开始负责自己的实验室，研究病毒、宿主与感染机制，并参与国际科研、培训和疫苗合作项目。","story":"巴雷-西努西自二十世纪七十年代起参与逆转录病毒研究。巴斯德研究所的官方人物档案记载，她是1983年报告一种与艾滋病相关逆转录病毒发现论文的第一作者，这种病毒后来被命名为HIV。论文署名、病毒发现和命名是相互关联但不同的历史事项，不能写成她独自完成了全部研究。\n1988年，她开始负责自己的实验室，研究HIV感染中病毒因素与宿主因素的作用，也参与疫苗合作研究。她推动研究、培训与资源有限地区公共卫生行动的联系，尤其通过巴斯德研究所网络参与柬埔寨和越南的科研合作。\n2008年，她获得诺贝尔生理学或医学奖，相关获奖工作与吕克·蒙塔尼耶共同进行。她还于2009年当选法国科学院成员。这里保留论文、实验室及国际合作的具体事实，不将旧简介中仍写作现任的协会或实验室职务直接当作今天的任职，也不把参与疫苗研究写成已经发明有效疫苗。人物故事未补写采访、个人动机或临床治疗承诺，图像使用统一占位图。","achievements":["是1983年报告后来命名为HIV的逆转录病毒发现论文的第一作者。","2008年因HIV发现相关工作获得诺贝尔生理学或医学奖。"],"facts":[{"claim":"是1983年报告后来命名为HIV的逆转录病毒发现论文的第一作者。","sourceUrls":["https://www.pasteur.fr/en/about-us/francoise-barre-sinoussi"]},{"claim":"2008年因HIV发现相关工作获得诺贝尔生理学或医学奖。","sourceUrls":["https://www.pasteur.fr/en/about-us/francoise-barre-sinoussi"]}],"sources":[{"title":"Institut Pasteur：Françoise Barré-Sinoussi官方人物档案","url":"https://www.pasteur.fr/en/about-us/francoise-barre-sinoussi","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1983,"description":"是1983年报告后来命名为HIV的逆转录病毒发现论文的第一作者。","sourceUrls":["https://www.pasteur.fr/en/about-us/francoise-barre-sinoussi"]},{"year":2008,"description":"2008年因HIV发现相关工作获得诺贝尔生理学或医学奖。","sourceUrls":["https://www.pasteur.fr/en/about-us/francoise-barre-sinoussi"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('simone-biles','simone-biles','西蒙娜·拜尔斯','Simone Biles','verified','{"id":"simone-biles","slug":"simone-biles","nameZh":"西蒙娜·拜尔斯","nameEn":"Simone Biles","fields":["体育"],"regions":["美国"],"occupation":"竞技体操运动员","keywords":["体育","竞技体操运动员"],"summary":"西蒙娜·拜尔斯是美国竞技体操运动员，参加女子全能与多个单项比赛。她2013年获得世界锦标赛全能和自由体操冠军，2016年里约奥运会获团体、全能、跳马及自由体操金牌。2024年巴黎奥运会，她再获团体、全能、跳马金牌和自由体操银牌。官方履历分别记录奥运、世锦赛与全国赛成绩。","story":"拜尔斯的国际比赛履历始于多个全能与单项成绩。美国体操协会的运动员档案记录，她2013年获得世界锦标赛全能和自由体操冠军，同时取得跳马银牌与平衡木铜牌。2014和2015年，她继续在世锦赛团体、全能及单项比赛中夺冠。\n2016年里约奥运会，她获得女子团体、个人全能、跳马和自由体操金牌，以及平衡木铜牌。东京奥运会，她取得团体银牌和平衡木铜牌。这里沿用赛事的东京2020名称，不把名称中的年份直接等同于实际举办年份，也不将团体奖牌写成个人单项成绩。\n2023年，她再次获得世锦赛全能冠军；2024年巴黎奥运会，她赢得团体、全能和跳马三枚金牌，并获自由体操银牌。官方履历按比赛和项目列明成绩，可用于核对阶段性总数，但累计纪录需要保留统计时间。本档案只写已确认的比赛结果，不采用同页邻近新闻中其他运动员仍有争议的奖牌结论，也不补写心理诊断、训练对白、复出动机或未经研究的后续赛事。","achievements":["2013年获得世界锦标赛女子全能和自由体操冠军。","2024年巴黎奥运会获团体、全能、跳马金牌及自由体操银牌。"],"facts":[{"claim":"2013年获得世界锦标赛女子全能和自由体操冠军。","sourceUrls":["https://members.usagym.org/pages/athletes/athleteListDetailPrint2.html?id=164887"]},{"claim":"2024年巴黎奥运会获团体、全能、跳马金牌及自由体操银牌。","sourceUrls":["https://members.usagym.org/pages/athletes/athleteListDetailPrint2.html?id=164887"]}],"sources":[{"title":"USA Gymnastics：Simone Biles官方运动员履历","url":"https://members.usagym.org/pages/athletes/athleteListDetailPrint2.html?id=164887","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":2013,"description":"2013年获得世界锦标赛女子全能和自由体操冠军。","sourceUrls":["https://members.usagym.org/pages/athletes/athleteListDetailPrint2.html?id=164887"]},{"year":2024,"description":"2024年巴黎奥运会获团体、全能、跳马金牌及自由体操银牌。","sourceUrls":["https://members.usagym.org/pages/athletes/athleteListDetailPrint2.html?id=164887"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('indra-nooyi','indra-nooyi','英德拉·努伊','Indra Nooyi','verified','{"id":"indra-nooyi","slug":"indra-nooyi","nameZh":"英德拉·努伊","nameEn":"Indra Nooyi","fields":["商业"],"regions":["印度","美国"],"occupation":"企业管理者","keywords":["商业","企业管理者"],"summary":"英德拉·努伊是在印度成长的企业管理者，曾任百事公司首席执行官及董事长。她1994年进入百事，2001年担任总裁和首席财务官，后来负责公司整体经营与战略。她于2018年10月卸任首席执行官，继续担任董事长至2019年2月。其职业经历涉及财务、企业战略、产品组合和大型公司的管理交接。","story":"努伊的百事公司职业经历从1994年开始。公司2019年的公告记载，她2001年担任总裁和首席财务官，并进入董事会，后来出任首席执行官及董事长。财务管理、公司战略和最高管理层职责由此构成不同阶段，不能将所有职位写成同年取得。\n在其任内，公司以Performance with Purpose表述经营方向，将业务增长、产品组合及环境议题联系起来。这是公司的战略自述，目标与实际成效仍需分别评估，不能仅凭交接公告将全部环境或健康目标认定为已经实现，也不能把团队研发全部归为高管个人成果。\n2018年，公司宣布拉蒙·拉古阿尔塔接任首席执行官，任命于10月3日生效。努伊继续担任董事长，直至2019年2月1日退休。两份公告明确区分CEO与董事长交接，因此本档案不沿用将CEO任期概括延长至2019年的说法。人物故事只保留已读取的企业履历和历史安排，没有复制公告中的个人评价或编写董事会谈判、财富排名与未来业绩预测。","achievements":["1994年进入百事公司，2001年担任总裁和首席财务官并进入董事会。","2018年10月3日卸任百事CEO，2019年2月1日卸任董事长。"],"facts":[{"claim":"1994年进入百事公司，2001年担任总裁和首席财务官并进入董事会。","sourceUrls":["https://www.pepsico.com/newsroom/press-releases/2019/pepsico-elects-ceo-ramon-laguarta-as-chairman-of-the-board"]},{"claim":"2018年10月3日卸任百事CEO，2019年2月1日卸任董事长。","sourceUrls":["https://www.pepsico.com/newsroom/press-releases/2019/pepsico-elects-ceo-ramon-laguarta-as-chairman-of-the-board"]}],"sources":[{"title":"PepsiCo：2019年董事长交接公告","url":"https://www.pepsico.com/newsroom/press-releases/2019/pepsico-elects-ceo-ramon-laguarta-as-chairman-of-the-board","checkedAt":"2026-11-09"},{"title":"PepsiCo：2018年CEO交接公告","url":"https://www.pepsico.com/newsroom/press-releases/2018/ramon-laguarta-elected-chief-executive-officer-of-pepsico","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('wislawa-szymborska','wislawa-szymborska','维斯瓦娃·辛波丝卡','Wisława Szymborska','verified','{"id":"wislawa-szymborska","slug":"wislawa-szymborska","nameZh":"维斯瓦娃·辛波丝卡","nameEn":"Wisława Szymborska","fields":["文学"],"regions":["波兰"],"occupation":"诗人、编辑、翻译者","keywords":["文学","诗人、编辑、翻译者"],"summary":"维斯瓦娃·辛波丝卡是波兰诗人、编辑和翻译者，1923年出生，长期生活于克拉科夫。她1945年发表诗作，1952年出版首部诗集，后来在文学周刊编辑诗歌并撰写书评。其作品包括《盐》《桥上的人们》《结束与开始》等。她1996年获得诺贝尔文学奖，也从事法语和德语诗歌翻译。","story":"辛波丝卡1923年出生于波兰，后来长期生活于克拉科夫。基金会官方时间线记录，她1945年发表诗作《寻找词语》，并在雅盖隆大学学习波兰文学及社会学，但未完成这些学位课程。她的写作经历因此不能被改写成取得两项大学学位。\n1952年，她出版首部诗集，此后陆续发表《盐》《桥上的人们》《结束与开始》等作品。她还在克拉科夫的文学周刊从事诗歌编辑和书评写作，并翻译法语与德语诗歌。诗集、评论和翻译属于不同文本类型，不能把评论中的叙述直接当成她本人的生活经历。\n1996年，她获得诺贝尔文学奖。她2012年去世后，尚未完成的诗集《Enough》出版。基金会同时保存简传和更详细的年表，本批对其中克拉科夫定居年份与编辑职务时段的不同口径不作强行统一，只保留能够支持的学习、出版与职业事实。人物故事采用独立中文转述，没有复制诗歌或私人书信，也不根据作品主题推断未记载的创作动机。","achievements":["1952年出版首部诗集。","1996年获得诺贝尔文学奖。"],"facts":[{"claim":"1952年出版首部诗集。","sourceUrls":["https://www.szymborska.org.pl/en/wislawa/chronology/"]},{"claim":"1996年获得诺贝尔文学奖。","sourceUrls":["https://www.szymborska.org.pl/en/wislawa/chronology/"]}],"sources":[{"title":"The Wisława Szymborska Foundation：官方生平与时间线","url":"https://www.szymborska.org.pl/en/wislawa/chronology/","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1952,"description":"1952年出版首部诗集。","sourceUrls":["https://www.szymborska.org.pl/en/wislawa/chronology/"]},{"year":1996,"description":"1996年获得诺贝尔文学奖。","sourceUrls":["https://www.szymborska.org.pl/en/wislawa/chronology/"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('zaha-hadid','zaha-hadid','扎哈·哈迪德','Zaha Hadid','verified','{"id":"zaha-hadid","slug":"zaha-hadid","nameZh":"扎哈·哈迪德","nameEn":"Zaha Hadid","fields":["艺术"],"regions":["伊拉克","英国"],"occupation":"建筑师、设计者","keywords":["艺术","建筑师、设计者"],"summary":"扎哈·哈迪德是出生于伊拉克巴格达的建筑师，后来在英国执业。她1972年到伦敦建筑联盟学院学习，毕业后加入OMA，并开展自己的设计实践。其建成作品包括德国维特拉消防站、因斯布鲁克跳台和辛辛那提当代艺术中心。2004年，她成为首位获得普利兹克建筑奖的女性，设计活动也涉及室内与家具。","story":"哈迪德出生于巴格达，曾在贝鲁特学习数学，1972年到伦敦建筑联盟学院学习建筑。1977年毕业后，她进入OMA，也参与教学。普利兹克奖的传记将绘画和图纸列为她早期设计探索的重要方法，说明其建筑实践同时包含空间研究、表达和建造。\n她在伦敦开展独立实践，1983年赢得香港山顶俱乐部设计竞赛。竞赛获选与项目建成是不同状态，本档案不把所有获奖方案都写成已经落成。官方资料列出的建成作品包括1993年德国维特拉消防站、2002年因斯布鲁克跳台和2003年辛辛那提当代艺术中心。\n2004年，她获得普利兹克建筑奖，成为该奖首位女性得主。获奖公告还列出当时处于开发阶段的项目，不能据此推定后来是否建成；建筑本身也需要团队、工程与业主协作。这里依据颁奖机构的传记和公告介绍教育、作品及奖项，不强行统一不同机构对事务所建立年份的口径，也不采用评委赞语代替可核实事实，未下载许可不明的作品照片。","achievements":["2004年成为首位获得普利兹克建筑奖的女性。","已完成作品包括德国维特拉消防站、因斯布鲁克跳台及辛辛那提当代艺术中心。"],"facts":[{"claim":"2004年成为首位获得普利兹克建筑奖的女性。","sourceUrls":["https://www.pritzkerprize.com/announcement-zaha-hadid"]},{"claim":"已完成作品包括德国维特拉消防站、因斯布鲁克跳台及辛辛那提当代艺术中心。","sourceUrls":["https://www.pritzkerprize.com/announcement-zaha-hadid"]}],"sources":[{"title":"The Pritzker Architecture Prize：Zaha Hadid官方获奖公告","url":"https://www.pritzkerprize.com/announcement-zaha-hadid","checkedAt":"2026-11-09"},{"title":"The Pritzker Architecture Prize：Zaha Hadid传记","url":"https://www.pritzkerprize.com/biography-zaha-hadid","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":2004,"description":"2004年成为首位获得普利兹克建筑奖的女性。","sourceUrls":["https://www.pritzkerprize.com/announcement-zaha-hadid"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('umeko-tsuda','umeko-tsuda','津田梅子','Umeko Tsuda','verified','{"id":"umeko-tsuda","slug":"umeko-tsuda","nameZh":"津田梅子","nameEn":"Umeko Tsuda","fields":["教育"],"regions":["日本","美国"],"occupation":"教育家、学校创办人","keywords":["教育","教育家、学校创办人"],"summary":"津田梅子是日本教育家和学校创办人，1871年入选早期赴美女子留学生群体，1882年回到日本。她后来再次赴美，在布林莫尔学院学习，1900年于东京创办女子英学塾，即津田塾大学的前身。学校最初招收10名学生，重视女性高等教育与专业能力，其办学活动连接跨国求学经验和日本女性教育发展。","story":"津田梅子1871年作为五名女子留学生之一赴美，在华盛顿附近生活和学习，1882年返回日本。津田塾大学的创办人资料将这段长期海外学习经历与她后来的教育工作联系起来。1889年，她再次赴美，进入布林莫尔学院学习，接触小班教育。\n1900年，她在东京创办女子英学塾，首批招收10名学生。这是日本早期私立女性高等教育机构之一，不能写成此前日本完全没有女子学校。学校教学与组织的发展依赖教师和支持者，大学资料也保留了创校时参与者的照片和信息。\n1905年，学校取得自主授予相关教师资格的许可，后来经历更名与学制变化，逐步发展成今天的津田塾大学。这些后续制度成果并非都发生于创办人在世时，应与她本人活动区分。这里根据大学英文简介和专题核对留学、归国及创校事实，不从文化差异推演私人心理，也不将2019年纸币设计公告中的未来发行计划直接当作当时已经流通；相关肖像继续使用统一占位图。","achievements":["1871年入选五名赴美女子留学生，1882年返回日本。","1900年在东京创办女子英学塾，首批招收10名学生。"],"facts":[{"claim":"1871年入选五名赴美女子留学生，1882年返回日本。","sourceUrls":["https://www.tsuda.ac.jp/en/profile.html"]},{"claim":"1900年在东京创办女子英学塾，首批招收10名学生。","sourceUrls":["https://www.tsuda.ac.jp/en/profile.html"]}],"sources":[{"title":"Tsuda University：学校简介与创办人历史","url":"https://www.tsuda.ac.jp/en/profile.html","checkedAt":"2026-11-09"},{"title":"Tsuda University：津田梅子生平资料与纸币设计公告","url":"https://www.tsuda.ac.jp/en/20190612.html","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1900,"description":"1900年在东京创办女子英学塾，首批招收10名学生。","sourceUrls":["https://www.tsuda.ac.jp/en/profile.html"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('jeannette-rankin','jeannette-rankin','珍妮特·兰金','Jeannette Rankin','verified','{"id":"jeannette-rankin","slug":"jeannette-rankin","nameZh":"珍妮特·兰金","nameEn":"Jeannette Rankin","fields":["公共事务"],"regions":["美国"],"occupation":"社会工作者、国会议员、参政权倡导者","keywords":["公共事务","社会工作者、国会议员、参政权倡导者"],"summary":"珍妮特·兰金是美国社会工作者、国会议员和女性参政权倡导者。她1902年毕业于蒙大拿大学，随后参与社会工作与多州参政权运动。1916年，她成为首位当选美国国会议员的女性，先后在1917至1919年、1941至1943年担任众议员。她长期参与和平与女性权利事务，两届任期并不连续。","story":"兰金1902年从蒙大拿大学毕业，后来在纽约接受社会工作训练，并参与社区服务。美国众议院历史档案记载，她在华盛顿州、加利福尼亚州及蒙大拿州推动女性参政权，将社会工作经验带入组织和公共倡导。\n1916年，她代表蒙大拿州当选众议员，成为首位当选美国国会的女性。她的首届任期属于1917至1919年的第65届国会，1941至1943年又在第77届国会任职。这两届相隔多年，不能合并成一段连续任职经历；当选年份、法定任期与宣誓时间也属于不同记录。\n她在两次世界大战时期的国会任职中反对美国参战，同时参与劳动条件、妇女与儿童健康等议题。离开国会后，她继续演讲并支持和平与女性权利组织，直至1973年去世。人物故事依据官方履历和研究性长传记整理，不把第一位女性议员等同于当时所有女性已获得完整投票权，也不将倡导活动写成她个人独自推动全国立法；没有复制名言、私人日记或编造竞选场景。","achievements":["1916年成为首位当选美国国会议员的女性。","先后于1917至1919年、1941至1943年担任众议员，两届任期不连续。"],"facts":[{"claim":"1916年成为首位当选美国国会议员的女性。","sourceUrls":["https://history.house.gov/People/Detail/20147"]},{"claim":"先后于1917至1919年、1941至1943年担任众议员，两届任期不连续。","sourceUrls":["https://history.house.gov/People/Detail/20147"]}],"sources":[{"title":"U.S. House of Representatives：Jeannette Rankin官方档案","url":"https://history.house.gov/People/Detail/20147","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1916,"description":"1916年成为首位当选美国国会议员的女性。","sourceUrls":["https://history.house.gov/People/Detail/20147"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('wang-yaping','wang-yaping','王亚平','Wang Yaping','verified','{"id":"wang-yaping","slug":"wang-yaping","nameZh":"王亚平","nameEn":"Wang Yaping","fields":["探索"],"regions":["中国"],"occupation":"航天员、飞行员","keywords":["探索","航天员、飞行员"],"summary":"王亚平是中国航天员和飞行员，1980年出生于山东烟台，1997年入伍，后来完成航天员训练。她2013年执行天宫一号与神舟十号载人飞行任务。2021年，她在神舟十三号任务中与翟志刚共同出舱，成为中国首位进行出舱活动的女航天员。任务还包括机械臂相关安装、测试及舱内外协同工作。","story":"王亚平早年接受飞行训练，后来完成基础理论、航天环境适应性及专业技术等航天员训练。中国载人航天工程办公室的历史简介记载，她2013年入选天宫一号与神舟十号载人飞行任务乘组，并完成任务。飞行员经历与航天员专业训练构成她进入载人航天工作的背景。\n2021年11月7日晚，神舟十三号乘组开展出舱活动，翟志刚和王亚平先后从天和核心舱节点舱出舱。王亚平成为中国首位进行出舱活动的女航天员；叶光富在舱内支持，机械臂与地面系统也参与协同。因此，太空行走不能被写成完全脱离团队保障的单人行动。\n11月8日凌晨，两人安全返回舱内。官方任务通报记录，乘组完成机械臂悬挂装置与转接件安装、舱外典型动作测试等工作，整个出舱活动约6.5小时。这是任务整体持续时间，不等于每名航天员都在舱外停留同样时长。本档案区分出舱与返回的跨日日期，不沿用2015年简介中的军衔作为现状，也不补写舱外对白、个人感受或未读取的后续任务。","achievements":["2013年入选并完成天宫一号与神舟十号载人飞行任务。","2021年11月7日成为中国首位进行出舱活动的女航天员。"],"facts":[{"claim":"2013年入选并完成天宫一号与神舟十号载人飞行任务。","sourceUrls":["https://www.cmse.gov.cn/hty/htyfc/202003/t20200306_41246.html"]},{"claim":"2021年11月7日成为中国首位进行出舱活动的女航天员。","sourceUrls":["https://www.cmse.gov.cn/xwzx/zhxw/202111/t20211108_49032.html"]}],"sources":[{"title":"中国载人航天工程办公室：航天员王亚平历史简介","url":"https://www.cmse.gov.cn/hty/htyfc/202003/t20200306_41246.html","checkedAt":"2026-11-09"},{"title":"中国载人航天工程办公室：神舟十三号乘组成功出舱","url":"https://www.cmse.gov.cn/xwzx/zhxw/202111/t20211108_49032.html","checkedAt":"2026-11-09"},{"title":"中国载人航天工程办公室：神舟十三号首次出舱任务完成","url":"https://www.cmse.gov.cn/xwzx/zhxw/202111/t20211108_49033.html","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":2013,"description":"2013年入选并完成天宫一号与神舟十号载人飞行任务。","sourceUrls":["https://www.cmse.gov.cn/hty/htyfc/202003/t20200306_41246.html"]},{"year":2021,"description":"2021年11月7日成为中国首位进行出舱活动的女航天员。","sourceUrls":["https://www.cmse.gov.cn/xwzx/zhxw/202111/t20211108_49032.html"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('ingrid-daubechies','ingrid-daubechies','英格丽·多贝西','Ingrid Daubechies','verified','{"id":"ingrid-daubechies","slug":"ingrid-daubechies","nameZh":"英格丽·多贝西","nameEn":"Ingrid Daubechies","fields":["数学"],"regions":["比利时","美国"],"occupation":"应用数学家","keywords":["数学","应用数学家"],"summary":"英格丽·多贝西是出生于比利时的应用数学家，早年学习理论物理，1980年取得博士学位。她研究小波理论及其在数字图像压缩中的应用，也与不同学科研究者合作分析心电图、化石扫描和艺术作品。她2011年加入杜克大学，并在2011至2014年担任国际数学联盟主席，研究连接数学、工程与文化遗产。","story":"多贝西在布鲁塞尔自由大学学习理论物理，1980年完成博士研究，随后发展小波理论及相关应用。小波方法能够在不同尺度上描述信号，为数字图像与其他数据的处理提供工具。她的职业经历包括贝尔实验室、密歇根大学、罗格斯大学和普林斯顿大学，2011年加入杜克大学。\n杜克大学2016年的报道介绍了她与化石专家、工程研究者以及艺术史研究者的合作。团队分析三维骨骼和牙齿扫描、心电图以及绘画图像，研究如何从复杂数据中比较形状和识别模式。这些工作涉及不同专业成员，不能将合作成果全部归为一个人，也不能把研究方法直接写成已经普及的临床诊断。\n2011至2014年，她担任国际数学联盟主席，任期由联盟历史名单确认。大学报道中的资助和研究计划按当年背景理解，不延伸为今天仍在执行的承诺。本档案保留教育、研究方向与任职事实，不采用未经限定的所有电影画面均使用其方法的说法，也不补写个人对白或艺术鉴定现场。","achievements":["1980年完成博士研究，随后在小波理论及数字图像处理方面开展研究。","2011至2014年担任国际数学联盟主席。"],"facts":[{"claim":"1980年完成博士研究，随后在小波理论及数字图像处理方面开展研究。","sourceUrls":["https://www.today.duke.edu/2016/08/daubechies"]},{"claim":"2011至2014年担任国际数学联盟主席。","sourceUrls":["https://www.mathunion.org/organization/imu-representatives/imu-leadership-2011-2014"]}],"sources":[{"title":"Duke Today：Of Heartbeats, Bones and Brushstrokes","url":"https://www.today.duke.edu/2016/08/daubechies","checkedAt":"2026-11-09"},{"title":"IMU：2011至2014年领导名单","url":"https://www.mathunion.org/organization/imu-representatives/imu-leadership-2011-2014","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1980,"description":"1980年完成博士研究，随后在小波理论及数字图像处理方面开展研究。","sourceUrls":["https://www.today.duke.edu/2016/08/daubechies"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('vera-rubin','vera-rubin','薇拉·鲁宾','Vera Rubin','verified','{"id":"vera-rubin","slug":"vera-rubin","nameZh":"薇拉·鲁宾","nameEn":"Vera Rubin","fields":["科学"],"regions":["美国"],"occupation":"天文学家","keywords":["科学","天文学家"],"summary":"薇拉·鲁宾是美国天文学家，1954年获乔治敦大学博士学位，1965年加入卡内基研究机构地磁系。她与肯特·福特等人研究星系旋转，通过不同距离处恒星的运动为暗物质研究提供观测证据。她1981年当选美国国家科学院院士，1993年获美国国家科学奖章，也参与推动女性在天文学中的机会与代表性。","story":"鲁宾在瓦萨学院学习，随后取得康奈尔大学硕士学位和乔治敦大学博士学位。1965年，她加入卡内基地磁系，成为该部门首位女性专职科学家。福特发展的观测仪器提高了测量微弱星光的效率，为双方开展星系运动研究提供了技术条件。\n鲁宾与福特研究仙女座星系，并在1970年发表旋转曲线论文。随后，他们与同事观测更多星系，发现外部恒星的运动不能仅由可见物质分布解释。这些结果成为支持暗物质的重要证据。这里描述的是天体运动与质量分布的推断，不等于直接捕获暗物质粒子，也不将此前已有的暗物质讨论从历史中删去。\n她1981年当选美国国家科学院院士，1993年获美国国家科学奖章，长期参与改善女性研究者的学术机会。卡内基页面同时收录较新的回顾和旧讣告，其中对宇宙质量比例的表述存在不同口径，本档案不采用这些数字，也不复制名言。人物图像继续使用占位图，避免把可浏览的馆藏照片直接当成可自由转载的素材。","achievements":["1965年加入卡内基地磁系，成为该部门首位女性专职科学家。","与肯特·福特于1970年发表仙女座星系旋转研究，后续观测为暗物质提供证据。"],"facts":[{"claim":"1965年加入卡内基地磁系，成为该部门首位女性专职科学家。","sourceUrls":["https://carnegiescience.edu/news/who-was-vera-rubin"]},{"claim":"与肯特·福特于1970年发表仙女座星系旋转研究，后续观测为暗物质提供证据。","sourceUrls":["https://carnegiescience.edu/news/who-was-vera-rubin"]}],"sources":[{"title":"Carnegie Science：Who was Vera Rubin?","url":"https://carnegiescience.edu/news/who-was-vera-rubin","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1965,"description":"1965年加入卡内基地磁系，成为该部门首位女性专职科学家。","sourceUrls":["https://carnegiescience.edu/news/who-was-vera-rubin"]},{"year":1970,"description":"与肯特·福特于1970年发表仙女座星系旋转研究，后续观测为暗物质提供证据。","sourceUrls":["https://carnegiescience.edu/news/who-was-vera-rubin"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('rebecca-lee-crumpler','rebecca-lee-crumpler','丽贝卡·李·克伦普勒','Rebecca Lee Crumpler','verified','{"id":"rebecca-lee-crumpler","slug":"rebecca-lee-crumpler","nameZh":"丽贝卡·李·克伦普勒","nameEn":"Rebecca Lee Crumpler","fields":["医学"],"regions":["美国"],"occupation":"医生、医学作者","keywords":["医学","医生、医学作者"],"summary":"丽贝卡·李·克伦普勒是美国医生和医学作者，早年从事护理，1860年进入新英格兰女子医学院，1864年成为美国首位获得医学博士学位的非裔女性。她曾在波士顿和里士满行医，为妇女、儿童及获得自由的原奴隶提供照护。1883年，她出版面向妇女和儿童健康的医学著作，留下其临床经验记录。","story":"克伦普勒1831年出生，后来在马萨诸塞州从事护理。美国国家医学图书馆记载，她1852至1860年在医生指导下工作，1860年进入新英格兰女子医学院，四年后取得医学博士学位，成为美国首位取得这一学位的非裔女性。\n美国内战结束后，她从波士顿前往弗吉尼亚州里士满，与其他黑人医生及相关服务组织一起，为获得自由的原奴隶提供医疗照护。她后来回到波士顿，继续为社区中的妇女和儿童看病。资料说明当时黑人医生面临种族歧视，但不能据此编写某次诊室争执或具体患者的遭遇。\n1883年，她出版《A Book of Medical Discourses》，内容依据多年行医笔记，关注妇女与儿童健康。书籍既是医疗写作，也是后人了解其职业经历的重要线索。现存生平材料有限，国家医学图书馆还明确说明没有存世照片或其他肖像，因此本档案不把页面装饰图当作真实肖像，不补写无法核对的治疗案例，也不将十九世纪书中建议作为今天的医疗指导。","achievements":["1864年成为美国首位获得医学博士学位的非裔女性。","1883年出版医学著作A Book of Medical Discourses。"],"facts":[{"claim":"1864年成为美国首位获得医学博士学位的非裔女性。","sourceUrls":["https://www.nlm.nih.gov/exhibition/changing-the-face-of-medicine/physicians/biography_rebecca_crumpler.html"]},{"claim":"1883年出版医学著作A Book of Medical Discourses。","sourceUrls":["https://www.nlm.nih.gov/exhibition/changing-the-face-of-medicine/physicians/biography_rebecca_crumpler.html"]}],"sources":[{"title":"National Library of Medicine：Rebecca Lee Crumpler传记","url":"https://www.nlm.nih.gov/exhibition/changing-the-face-of-medicine/physicians/biography_rebecca_crumpler.html","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1864,"description":"1864年成为美国首位获得医学博士学位的非裔女性。","sourceUrls":["https://www.nlm.nih.gov/exhibition/changing-the-face-of-medicine/physicians/biography_rebecca_crumpler.html"]},{"year":1883,"description":"1883年出版医学著作A Book of Medical Discourses。","sourceUrls":["https://www.nlm.nih.gov/exhibition/changing-the-face-of-medicine/physicians/biography_rebecca_crumpler.html"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('allyson-felix','allyson-felix','艾莉森·菲利克斯','Allyson Felix','verified','{"id":"allyson-felix","slug":"allyson-felix","nameZh":"艾莉森·菲利克斯","nameEn":"Allyson Felix","fields":["体育"],"regions":["美国"],"occupation":"田径运动员","keywords":["体育","田径运动员"],"summary":"艾莉森·菲利克斯是美国田径运动员，参加过雅典、北京、伦敦、里约和东京五届奥运会。国际奥委会履历记录，她在伦敦2012获得三枚金牌，在里约2016获得两枚金牌，并在东京2020取得金牌与铜牌。她的职业经历还包括世锦赛、体育事务和企业创办，2007年取得南加州大学教育学文学士学位。","story":"菲利克斯的奥运履历横跨五届赛事，从雅典2004延续到东京2020。国际奥委会档案按届列出成绩：雅典获得银牌，北京取得金牌与银牌，伦敦获得三枚金牌，里约取得两枚金牌与一枚银牌，东京取得一枚金牌与一枚铜牌。这些记录合计十一枚奥运奖牌，其中七枚金牌。\n她也参加世界田径锦标赛，官方履历列出从2005到2022年的多项奖牌成绩。奥运会、世锦赛以及不同届次属于各自统计范围，不能把某一赛事的奖牌总数当作全部职业成绩；东京2020是赛事名称，不能直接据此推断实际比赛日期。\n竞技比赛之外，她2007年取得南加州大学教育学文学士学位，2021年参与创办Saysh，2024年进入国际奥委会。这里采用机构档案中可核对的历史节点，没有使用访问超时的美国田协页面作为正文证据，也不据品牌创办经历推算收入或市场排名。故事未编写训练场对白、家庭动机或未读取的比赛细节，肖像保持统一占位图。","achievements":["伦敦2012奥运会获得三枚金牌，里约2016获得两枚金牌。","参加雅典2004至东京2020五届奥运会，官方逐届记录合计十一枚奖牌。"],"facts":[{"claim":"伦敦2012奥运会获得三枚金牌，里约2016获得两枚金牌。","sourceUrls":["https://www.olympics.com/ioc/ms-allyson-felix"]},{"claim":"参加雅典2004至东京2020五届奥运会，官方逐届记录合计十一枚奖牌。","sourceUrls":["https://www.olympics.com/ioc/ms-allyson-felix"]}],"sources":[{"title":"International Olympic Committee：Allyson Felix官方档案","url":"https://www.olympics.com/ioc/ms-allyson-felix","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('kiran-mazumdar-shaw','kiran-mazumdar-shaw','基兰·马宗达尔-肖','Kiran Mazumdar-Shaw','verified','{"id":"kiran-mazumdar-shaw","slug":"kiran-mazumdar-shaw","nameZh":"基兰·马宗达尔-肖","nameEn":"Kiran Mazumdar-Shaw","fields":["商业"],"regions":["印度"],"occupation":"生物技术企业家","keywords":["商业","生物技术企业家"],"summary":"基兰·马宗达尔-肖是印度生物技术企业家，与Biocon的发展密切相关。她1975年在巴拉瑞特高等教育学院完成麦芽与酿造研究生文凭，后来进入生物技术商业领域。澳大利亚联邦大学2004年向她授予荣誉理学博士，2015年以她命名校园道路。其经历连接技术教育、企业管理与对后续学生的教育支持。","story":"马宗达尔-肖在澳大利亚巴拉瑞特高等教育学院接受酿造技术教育，1975年取得麦芽与酿造研究生文凭。澳大利亚联邦大学的校友简介使用Master Brewer描述其专业资格，这里不将该称谓直接翻译成另一个未经证明的学术硕士学位。\n她后来参与创办并发展Biocon，职业活动转向生物技术企业管理。大学资料将可负担的创新列为其商业方向，也介绍企业参与慢性疾病相关产品与研究服务。这些属于机构对业务目标的描述，不能单凭校友介绍推定所有患者已经获得治疗，或将公司的研发全部写成创办人个人发明。\n2004年，大学向她授予荣誉理学博士；2015年，校园一条道路以她命名；以她命名的奖学金于2017年首次颁发。荣誉学位与通过课程取得的学历分别记录。由于Biocon多个官网页面本次超时，创办年份和股权变更暂不写入事实字段，也不沿用网页中缺少统计时点的行业唯一性、财富排名或全球覆盖数字。图片许可尚未确认，继续使用占位图。","achievements":["1975年在巴拉瑞特高等教育学院完成麦芽与酿造研究生文凭。","2004年获澳大利亚联邦大学前身体系授予荣誉理学博士，2015年校园道路以她命名。"],"facts":[{"claim":"1975年在巴拉瑞特高等教育学院完成麦芽与酿造研究生文凭。","sourceUrls":["https://www.federation.edu.au/study/scholarships/details/foundation-scholarships/kiran-mazumdar-shaw-scholarship"]},{"claim":"2004年获澳大利亚联邦大学前身体系授予荣誉理学博士，2015年校园道路以她命名。","sourceUrls":["https://www.federation.edu.au/study/scholarships/details/foundation-scholarships/kiran-mazumdar-shaw-scholarship"]}],"sources":[{"title":"Federation University：Kiran Mazumdar-Shaw奖学金与校友简介","url":"https://www.federation.edu.au/study/scholarships/details/foundation-scholarships/kiran-mazumdar-shaw-scholarship","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1975,"description":"1975年在巴拉瑞特高等教育学院完成麦芽与酿造研究生文凭。","sourceUrls":["https://www.federation.edu.au/study/scholarships/details/foundation-scholarships/kiran-mazumdar-shaw-scholarship"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('octavia-butler','octavia-butler','奥克塔维娅·巴特勒','Octavia Butler','verified','{"id":"octavia-butler","slug":"octavia-butler","nameZh":"奥克塔维娅·巴特勒","nameEn":"Octavia Butler","fields":["文学"],"regions":["美国"],"occupation":"科幻作家","keywords":["文学","科幻作家"],"summary":"奥克塔维娅·巴特勒是美国科幻作家，1947年出生于帕萨迪纳，作品包括《Kindred》及《Parable of the Sower》等。她1976年出版首部长篇小说《Patternmaster》，1995年获得麦克阿瑟奖。亨廷顿图书馆保存她的手稿、研究笔记和通信，为研究其创作过程提供材料；","story":"巴特勒出生于加利福尼亚州帕萨迪纳，青少年时期开始写作。亨廷顿图书馆的研究指南记载，她曾在帕萨迪纳城市学院及加州州立大学洛杉矶分校学习，参加写作工作坊，并通过克拉里昂工作坊售出早期短篇。这些学习经历不等同于已经取得所有相关院校学位。\n1976年，她的首部长篇小说《Patternmaster》由双日出版社出版，1979年发表《Kindred》。此后，她写出1993年的《Parable of the Sower》和1998年的《Parable of the Talents》等作品。小说文本属于文学创作，不能把其中人物的遭遇直接改写成作者亲历，也不凭主题推断未记录的个人动机。\n1995年，她获得麦克阿瑟奖；她的作品也获得雨果奖及星云奖。2006年去世后，其手稿、笔记和通信等材料进入亨廷顿馆藏，研究指南说明档案分批入藏的情况。这里以馆方整理的出版和档案事实为依据，不复制小说段落或未公开信件。档案可供研究不等于其内容与照片均可自由转载，人物展示因此继续采用统一占位图。","achievements":["1976年出版首部长篇小说Patternmaster。","1995年获得麦克阿瑟奖。"],"facts":[{"claim":"1976年出版首部长篇小说Patternmaster。","sourceUrls":["https://researchguides.huntington.org/oeb"]},{"claim":"1995年获得麦克阿瑟奖。","sourceUrls":["https://researchguides.huntington.org/oeb"]}],"sources":[{"title":"The Huntington：Octavia E. Butler研究指南","url":"https://researchguides.huntington.org/oeb","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1976,"description":"1976年出版首部长篇小说Patternmaster。","sourceUrls":["https://researchguides.huntington.org/oeb"]},{"year":1995,"description":"1995年获得麦克阿瑟奖。","sourceUrls":["https://researchguides.huntington.org/oeb"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('louise-bourgeois','louise-bourgeois','路易丝·布尔乔亚','Louise Bourgeois','verified','{"id":"louise-bourgeois","slug":"louise-bourgeois","nameZh":"路易丝·布尔乔亚","nameEn":"Louise Bourgeois","fields":["艺术"],"regions":["法国","美国"],"occupation":"雕塑家、版画艺术家","keywords":["艺术","雕塑家、版画艺术家"],"summary":"路易丝·布尔乔亚是出生于法国巴黎的美国艺术家，创作包括绘画、版画、雕塑与织物作品。她1938年迁居纽约，二十世纪四十年代后期逐步转向雕塑，1982年在纽约现代艺术博物馆举办回顾展。她的作品采用木、石膏和织物等不同材料，晚期创作包括大型蜘蛛与房间尺度的装置，2010年在纽约去世。","story":"布尔乔亚1911年出生于巴黎，父母经营挂毯修复业务，她早年也参与为挂毯缺失部分绘制图案。她曾学习数学，后来转向艺术。1938年，她与艺术史学者罗伯特·戈德沃特结婚并迁往纽约，此后在美国继续创作。\n她最初集中于绘画和版画，四十年代后期开始发展雕塑。1964年的展览呈现有机形态的石膏作品，与较早的木雕形成不同面貌。1982年，纽约现代艺术博物馆为她举办回顾展。此后，她继续制作大型蜘蛛、房间尺度的Cells装置及织物作品，同时保持绘画与版画实践。\nMoMA还编制其版画和书籍作品目录，说明同一构图可能有不同版本、状态和印张。因此，目录条目数量不能直接当作完全不同的独立创作总数。人物故事采用馆方生平与目录解释，不把1982年展览扩大成该馆首位女性艺术家回顾展，也不借作品为她作心理诊断。博物馆对图像复制另设许可要求，本批未取得转载许可，保持占位图，不复制私人言论。","achievements":["1938年从巴黎迁居纽约，早期创作包括绘画和版画，四十年代后期转向雕塑。","1982年在纽约现代艺术博物馆举办回顾展。"],"facts":[{"claim":"1938年从巴黎迁居纽约，早期创作包括绘画和版画，四十年代后期转向雕塑。","sourceUrls":["https://lb.moma.org/about/biography"]},{"claim":"1982年在纽约现代艺术博物馆举办回顾展。","sourceUrls":["https://lb.moma.org/about/biography"]}],"sources":[{"title":"MoMA：Louise Bourgeois传记","url":"https://lb.moma.org/about/biography","checkedAt":"2026-11-09"},{"title":"MoMA：版画与书籍全集目录使用指南","url":"https://lb.moma.org/guide","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1938,"description":"1938年从巴黎迁居纽约，早期创作包括绘画和版画，四十年代后期转向雕塑。","sourceUrls":["https://lb.moma.org/about/biography"]},{"year":1982,"description":"1982年在纽约现代艺术博物馆举办回顾展。","sourceUrls":["https://lb.moma.org/about/biography"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('nannie-helen-burroughs','nannie-helen-burroughs','南妮·海伦·伯勒斯','Nannie Helen Burroughs','verified','{"id":"nannie-helen-burroughs","slug":"nannie-helen-burroughs","nameZh":"南妮·海伦·伯勒斯","nameEn":"Nannie Helen Burroughs","fields":["教育"],"regions":["美国"],"occupation":"教育家、学校创办人","keywords":["教育","教育家、学校创办人"],"summary":"南妮·海伦·伯勒斯是美国教育家，推动黑人女性接受文化与职业教育。她1909年在华盛顿建立女子培训学校，课程涵盖学术学习、缝纫、印刷、公共演说和体育等。学校主要依靠黑人社区的小额捐款筹建，1928年建成教学楼Trades Hall。她长期参与办学，1961年去世，学校后来改以她的名字命名。","story":"伯勒斯成长于弗吉尼亚州和华盛顿，曾以优异成绩完成M街高中学业。她申请公立学校教职未获录用，后来向全国浸礼会大会提出建立女子学校的计划。组织购置土地，黑人社区中的妇女与儿童等以小额捐款支持，学校于1909年开办。\n学校将文化课程与职业技能结合，学生可以学习缝纫、机械操作、公共演说、音乐和体育，也能在校内洗衣房与报纸工作中获得实践经验。美国国家公园管理局的历史介绍记载，学生来自美国之外的不同地区，教育活动因此不局限于一个城市的社区。\n1928年，Trades Hall建成，设有教室、办公室、集会空间及印刷作坊，取代较早的教学建筑。伯勒斯1961年去世，学校1964年改用她的姓名。这里把学校建设作为机构历程，不将支持者和教师的工作全部归于创办人。官方资料对出生年份使用约数，教职被拒的具体原因也有历史推测，本档案均不作确定结论，不编写募捐演说原文或学生个案，图片继续采用占位图。","achievements":["1909年推动在华盛顿开办National Training School for Women and Girls。","其学校的Trades Hall于1928年建成，设有教室及印刷作坊等设施。"],"facts":[{"claim":"1909年推动在华盛顿开办National Training School for Women and Girls。","sourceUrls":["https://www.nps.gov/places/national-training-school-for-women-and-girls.htm"]},{"claim":"其学校的Trades Hall于1928年建成，设有教室及印刷作坊等设施。","sourceUrls":["https://www.nps.gov/places/national-training-school-for-women-and-girls.htm"]}],"sources":[{"title":"National Park Service：National Training School及Trades Hall历史","url":"https://www.nps.gov/places/national-training-school-for-women-and-girls.htm","checkedAt":"2026-11-09"},{"title":"National Park Service：Nannie Helen Burroughs人物档案","url":"https://www.nps.gov/people/nannie-helen-burroughs.htm","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1909,"description":"1909年推动在华盛顿开办National Training School for Women and Girls。","sourceUrls":["https://www.nps.gov/places/national-training-school-for-women-and-girls.htm"]},{"year":1928,"description":"其学校的Trades Hall于1928年建成，设有教室及印刷作坊等设施。","sourceUrls":["https://www.nps.gov/places/national-training-school-for-women-and-girls.htm"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('huda-shaarawi','huda-shaarawi','胡达·沙拉维','Huda Shaarawi','verified','{"id":"huda-shaarawi","slug":"huda-shaarawi","nameZh":"胡达·沙拉维","nameEn":"Huda Shaarawi","fields":["公共事务"],"regions":["埃及"],"occupation":"女性权利倡导者、社会改革者","keywords":["公共事务","女性权利倡导者、社会改革者"],"summary":"胡达·沙拉维是埃及女性权利倡导者和社会改革者，参与二十世纪初的公共事务与女性组织活动。她1923年成为埃及女权联盟首任主席，同年前往罗马参加国际妇女参政权联盟大会。其回忆录与保存在开罗美国大学的档案为研究女性组织、慈善活动及社会改革提供材料，也反映当时公共参与的复杂历史环境。","story":"沙拉维成长于开罗的上层家庭，其后参与女性组织与社会改革。伦敦大学亚非学院所刊研究论文通过她的回忆录讨论女性公共参与，也提醒读者注意阶级、民族运动与性别之间的关系。个体留下的经历不能代表同时代所有埃及女性。\n1923年，她成为埃及女权联盟首任主席，并前往罗马参加国际妇女参政权联盟大会。这是可以核对的组织与国际活动节点。论文也讨论她返程后的公共象征及后世解释，但本档案不以单一服饰举动概括整个女性运动，更不把组织成立直接写成女性立即取得完整政治权利。\n开罗美国大学图书馆保存沙拉维的档案，馆藏介绍说明其中涉及慈善活动和二十世纪初的改革倡议。档案保存地与研究论文构成不同类型的证据，馆藏简介本身不证明每一项传记细节。本批未阅读全文回忆录，也没有确认杂志创办年份，故不补写相关场景、私人对话或日期；故事仅对已读研究段落及机构档案介绍作独立转述，肖像使用占位图。","achievements":["1923年成为埃及女权联盟首任主席。","1923年前往罗马参加国际妇女参政权联盟大会。"],"facts":[{"claim":"1923年成为埃及女权联盟首任主席。","sourceUrls":["https://www.soas.ac.uk/sites/default/files/2022-06/05%20Rereading%20Huda%20Shaarawis%20Harem%20Years%20Bargaining%20with%20the%20Patriarchy%20in%20the%20Changing%20Egypt%20file102674.pdf"]},{"claim":"1923年前往罗马参加国际妇女参政权联盟大会。","sourceUrls":["https://www.soas.ac.uk/sites/default/files/2022-06/05%20Rereading%20Huda%20Shaarawis%20Harem%20Years%20Bargaining%20with%20the%20Patriarchy%20in%20the%20Changing%20Egypt%20file102674.pdf"]}],"sources":[{"title":"SOAS Journal of Postgraduate Research：Julia Lisiecka论Huda Shaarawi回忆录，2015，第52至54页","url":"https://www.soas.ac.uk/sites/default/files/2022-06/05%20Rereading%20Huda%20Shaarawis%20Harem%20Years%20Bargaining%20with%20the%20Patriarchy%20in%20the%20Changing%20Egypt%20file102674.pdf","checkedAt":"2026-11-09"},{"title":"AUC Libraries：埃及社会、艺术与文化档案","url":"https://library.aucegypt.edu/rare-books-special-collections/collections/egyptian-society-arts-culture","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1923,"description":"1923年成为埃及女权联盟首任主席。","sourceUrls":["https://www.soas.ac.uk/sites/default/files/2022-06/05%20Rereading%20Huda%20Shaarawis%20Harem%20Years%20Bargaining%20with%20the%20Patriarchy%20in%20the%20Changing%20Egypt%20file102674.pdf"]},{"year":1923,"description":"1923年前往罗马参加国际妇女参政权联盟大会。","sourceUrls":["https://www.soas.ac.uk/sites/default/files/2022-06/05%20Rereading%20Huda%20Shaarawis%20Harem%20Years%20Bargaining%20with%20the%20Patriarchy%20in%20the%20Changing%20Egypt%20file102674.pdf"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('christina-koch','christina-koch','克里斯蒂娜·科赫','Christina Koch','verified','{"id":"christina-koch","slug":"christina-koch","nameZh":"克里斯蒂娜·科赫","nameEn":"Christina Koch","fields":["探索"],"regions":["美国"],"occupation":"航天员","keywords":["探索","航天员"],"summary":"克里斯蒂娜·科赫是美国航天员，2019年3月14日启程前往国际空间站，2020年2月6日返回地球，完成328天的首次太空飞行。NASA当时将其记为女性单次太空飞行时长纪录。任务期间她进行了六次太空行走，包括最初三次全女性太空行走；她参与的长期驻留也为研究人体适应太空环境提供资料。","story":"科赫于2019年3月14日与尼克·黑格及阿列克谢·奥夫奇宁共同发射升空，开始首次太空飞行。她在国际空间站参与第59至61次远征任务，长期驻留使研究人员能够观察太空环境对人体的影响，也涉及空间站日常运行和科学实验。\n2020年2月6日，她与亚历山大·斯克沃尔佐夫、卢卡·帕尔米塔诺乘联盟MS-13飞船在哈萨克斯坦着陆。NASA返回通报记录她在太空停留328天，并称这是当时女性单次太空飞行的最长纪录。这里为历史纪录保留通报时点，不以旧公告推断今天全部航天员的累计排名。\n这次任务期间，她完成六次太空行走，包括最初三次全女性太空行走，累计舱外活动42小时15分钟。单次驻留时间、整个职业累计时间和舱外活动时长是不同统计，不能相互替代。空间站任务依赖国际乘组与地面团队合作，本档案不将所有实验写成她独立完成，也不把2020年通报中的未来月球与火星计划写成她本人已执行的后续任务；未补写太空感受或私人对白。","achievements":["2019年3月14日发射，2020年2月6日返回，首次太空飞行持续328天。","此次任务期间进行了六次太空行走，包括最初三次全女性太空行走。"],"facts":[{"claim":"2019年3月14日发射，2020年2月6日返回，首次太空飞行持续328天。","sourceUrls":["https://www.nasa.gov/news-release/record-setting-nasa-astronaut-crewmates-return-from-space-station/"]},{"claim":"此次任务期间进行了六次太空行走，包括最初三次全女性太空行走。","sourceUrls":["https://www.nasa.gov/news-release/record-setting-nasa-astronaut-crewmates-return-from-space-station/"]}],"sources":[{"title":"NASA：2020年2月6日科赫与乘组返回地球通报","url":"https://www.nasa.gov/news-release/record-setting-nasa-astronaut-crewmates-return-from-space-station/","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('mary-cartwright','mary-cartwright','玛丽·卡特赖特','Mary Cartwright','verified','{"id":"mary-cartwright","slug":"mary-cartwright","nameZh":"玛丽·卡特赖特","nameEn":"Mary Cartwright","fields":["数学"],"regions":["英国"],"occupation":"数学家、学院负责人","keywords":["数学","数学家、学院负责人"],"summary":"玛丽·卡特赖特是英国数学家，研究复函数与微分方程，并长期参与剑桥格顿学院教学和管理。她1930年加入格顿，1947年成为首位当选英国皇家学会会士的女性数学家，1949至1968年担任学院院长。她与利特尔伍德围绕无线电与雷达模型开展合作，其成果成为后来动力系统研究的重要历史组成部分。","story":"卡特赖特1919年进入牛津大学圣休学院学习数学，1923年毕业，随后在学校任教，再返回牛津从事博士研究。1930年，她到剑桥格顿学院继续研究复函数。研究与教学逐渐连接起来，她也承担数学教学负责人等职务。\n二十世纪三十年代后期，无线电和雷达研究产生的微分方程问题引起她的关注。她与利特尔伍德合作研究方程解的复杂行为，这些成果后来被放入动力系统与混沌研究的发展脉络。它们并不意味着一个人独自建立了整个现代混沌理论，应用背景也不等于她本人制造了雷达设备。\n1947年，她成为首位当选英国皇家学会会士的女性数学家。格顿学院历史记录其院长任期为1949至1968年，1968年获德摩根奖章。数学史传记对院长任命年份另有1948年的写法，本档案采用学院的任期口径，不强行合并；同页学会主席任期也有不同表述，暂不采用。故事不复制回忆录对白或推断私人心理，肖像使用占位图。","achievements":["1947年成为首位当选英国皇家学会会士的女性数学家。","1949至1968年担任格顿学院院长，1968年获德摩根奖章。"],"facts":[{"claim":"1947年成为首位当选英国皇家学会会士的女性数学家。","sourceUrls":["https://www.girton.cam.ac.uk/pioneering-history/girton-community"]},{"claim":"1949至1968年担任格顿学院院长，1968年获德摩根奖章。","sourceUrls":["https://www.girton.cam.ac.uk/pioneering-history/girton-community"]}],"sources":[{"title":"Girton College：Mary Cartwright学院历史","url":"https://www.girton.cam.ac.uk/pioneering-history/girton-community","checkedAt":"2026-11-09"},{"title":"MacTutor：Mary Cartwright数学史传记","url":"https://mathshistory.st-andrews.ac.uk/Biographies/Cartwright/","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1947,"description":"1947年成为首位当选英国皇家学会会士的女性数学家。","sourceUrls":["https://www.girton.cam.ac.uk/pioneering-history/girton-community"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('donna-strickland','donna-strickland','唐娜·斯特里克兰','Donna Strickland','verified','{"id":"donna-strickland","slug":"donna-strickland","nameZh":"唐娜·斯特里克兰","nameEn":"Donna Strickland","fields":["科学"],"regions":["加拿大"],"occupation":"光学物理学家","keywords":["科学","光学物理学家"],"summary":"唐娜·斯特里克兰是加拿大光学物理学家，研究高强度超短激光脉冲与非线性光学。她1981年毕业于麦克马斯特大学，1989年获罗切斯特大学光学博士学位。她与导师热拉尔·穆鲁1985年发表啁啾脉冲放大研究，2018年获诺贝尔物理学奖，1997年加入滑铁卢大学，持续开展激光系统研究与教学。","story":"斯特里克兰1981年取得麦克马斯特大学工程物理学位，后来到罗切斯特大学攻读光学博士。她与导师穆鲁在1985年发表啁啾脉冲放大研究，相关论文时间与1989年完成博士学位是两个不同节点，不能将毕业年份误写成论文发表年份。\n滑铁卢大学官方履历说明，这项方法推动了高强度超短激光脉冲的发展，并在工业加工和医学中形成应用。这里保留研究与应用的联系，不把所有激光手术或制造设备归为她个人发明，也不将研究方向中的潜在治疗用途写成已经证明的临床疗效。\n她先后在加拿大国家研究机构、劳伦斯利弗莫尔国家实验室及普林斯顿大学工作，1997年加入滑铁卢大学。2013年，她担任美国光学学会主席，2018年获得诺贝尔物理学奖。学校履历同时列出研究领域和课程，说明其工作包含研究、教学与学术服务。本档案采用已读取的大学正文，诺贝尔奖事实页本次返回403，失败页面不作证据，不复制采访对白或补写实验现场。","achievements":["1985年与热拉尔·穆鲁发表啁啾脉冲放大研究。","2018年因高强度超短光脉冲相关方法获得诺贝尔物理学奖。"],"facts":[{"claim":"1985年与热拉尔·穆鲁发表啁啾脉冲放大研究。","sourceUrls":["https://uwaterloo.ca/physics-astronomy/profile/strickla"]},{"claim":"2018年因高强度超短光脉冲相关方法获得诺贝尔物理学奖。","sourceUrls":["https://uwaterloo.ca/physics-astronomy/profile/strickla"]}],"sources":[{"title":"University of Waterloo：Donna Strickland官方履历","url":"https://uwaterloo.ca/physics-astronomy/profile/strickla","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1985,"description":"1985年与热拉尔·穆鲁发表啁啾脉冲放大研究。","sourceUrls":["https://uwaterloo.ca/physics-astronomy/profile/strickla"]},{"year":2018,"description":"2018年因高强度超短光脉冲相关方法获得诺贝尔物理学奖。","sourceUrls":["https://uwaterloo.ca/physics-astronomy/profile/strickla"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('katalin-kariko','katalin-kariko','卡塔琳·卡里科','Katalin Karikó','verified','{"id":"katalin-kariko","slug":"katalin-kariko","nameZh":"卡塔琳·卡里科","nameEn":"Katalin Karikó","fields":["医学"],"regions":["匈牙利","美国"],"occupation":"生物化学家、mRNA研究者","keywords":["医学","生物化学家、mRNA研究者"],"summary":"卡塔琳·卡里科是与匈牙利塞格德大学和美国宾夕法尼亚大学相关的生物化学家，长期研究信使RNA。她与德鲁·魏斯曼合作，2005年发表对mRNA进行修饰的关键研究，为后来疫苗平台的发展提供基础。两人共同获得2023年诺贝尔生理学或医学奖，其成果与后续企业开发和临床验证共同组成疫苗研发链条。","story":"卡里科长期研究信使RNA的医学用途，并与宾夕法尼亚大学的魏斯曼建立合作。宾大医学中心2023年公告回顾，两人自二十世纪九十年代后期开始共同研究，将mRNA作为潜在治疗工具。基础分子研究与后来疫苗开发属于相连但不同的工作阶段。\n2005年，他们发表关于修饰mRNA的关键研究。相关技术后来被用于辉瑞与BioNTech、莫德纳的新冠疫苗平台。这段历史包含基础研究、技术许可、企业开发和临床工作，不能写成两位研究者独自完成所有疫苗，也不能将其他疾病的研究前景直接写成已经获准使用的疗法。\n2023年，两人共同获得诺贝尔生理学或医学奖。公告同时披露宾大、研究者与相关产品存在许可收益关系，因此机构的成效介绍需要结合其来源背景理解。本档案保留论文时间、合作关系和奖项，不采用页面中会随时间变化的接种总数、女性获奖者排名或无限扩展的治疗承诺。诺贝尔官网访问失败已记录，没有补写实验室对白或私人动机，图片使用占位图。","achievements":["2005年与德鲁·魏斯曼发表关于修饰mRNA的关键研究。","与德鲁·魏斯曼共同获得2023年诺贝尔生理学或医学奖。"],"facts":[{"claim":"2005年与德鲁·魏斯曼发表关于修饰mRNA的关键研究。","sourceUrls":["https://www.pennmedicine.org/news/katalin-kariko-and-drew-weissman-win-2023-nobel-prize-in-medicine"]},{"claim":"与德鲁·魏斯曼共同获得2023年诺贝尔生理学或医学奖。","sourceUrls":["https://www.pennmedicine.org/news/katalin-kariko-and-drew-weissman-win-2023-nobel-prize-in-medicine"]}],"sources":[{"title":"Penn Medicine：Karikó与Weissman获2023年诺贝尔奖公告","url":"https://www.pennmedicine.org/news/katalin-kariko-and-drew-weissman-win-2023-nobel-prize-in-medicine","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":2005,"description":"2005年与德鲁·魏斯曼发表关于修饰mRNA的关键研究。","sourceUrls":["https://www.pennmedicine.org/news/katalin-kariko-and-drew-weissman-win-2023-nobel-prize-in-medicine"]},{"year":2023,"description":"与德鲁·魏斯曼共同获得2023年诺贝尔生理学或医学奖。","sourceUrls":["https://www.pennmedicine.org/news/katalin-kariko-and-drew-weissman-win-2023-nobel-prize-in-medicine"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('yusra-mardini','yusra-mardini','尤斯拉·马尔迪尼','Yusra Mardini','verified','{"id":"yusra-mardini","slug":"yusra-mardini","nameZh":"尤斯拉·马尔迪尼","nameEn":"Yusra Mardini","fields":["体育"],"regions":["叙利亚","德国"],"occupation":"游泳运动员、难民事务倡导者","keywords":["体育","游泳运动员、难民事务倡导者"],"summary":"尤斯拉·马尔迪尼是出生于叙利亚大马士革的游泳运动员，后来在德国继续训练。她2016年作为首届难民奥运代表队成员参加里约奥运会，2017年获任联合国难民署亲善大使。她的自传《Butterfly》于2018年出版。其公共活动涉及体育参赛和难民处境倡导，参赛经历与奖牌成绩应分别核对。","story":"马尔迪尼1998年出生于大马士革，幼年学习游泳，2012年参加在伊斯坦布尔举行的世界锦标赛。国际奥委会人物档案记录，她2015年离开战乱中的叙利亚，在前往希腊的途中与姐姐及其他同行者帮助发生故障的船只抵达安全地点，随后来到德国。\n她在柏林恢复训练，2016年成为首届难民奥运代表队成员，参加里约奥运会。代表队身份与国籍、居住地属于不同概念，本档案不把难民代表队写成某个国家的代表队，也不把参加奥运会直接写成夺得奖牌。\n2017年，她获任联合国难民署亲善大使，2018年出版自传《Butterfly》。这里根据奥委会机构档案记录历史活动，没有复制自传或采访。难民署多个页面本次返回429，未作为正文证据；奥委会旧简介仍将东京赛事写为未来目标，也包含当时的全球难民数字，均不当作现状沿用。故事不推断今日法律身份，不渲染未经独立核对的海上细节，也不编写个人独白，肖像继续采用统一占位图。","achievements":["作为首届难民奥运代表队成员参加里约2016奥运会。","2017年获任联合国难民署亲善大使，2018年出版自传Butterfly。"],"facts":[{"claim":"作为首届难民奥运代表队成员参加里约2016奥运会。","sourceUrls":["https://www.olympics.com/ioc/olympism-in-action/speakers/yusra-mardini"]},{"claim":"2017年获任联合国难民署亲善大使，2018年出版自传Butterfly。","sourceUrls":["https://www.olympics.com/ioc/olympism-in-action/speakers/yusra-mardini"]}],"sources":[{"title":"International Olympic Committee：Yusra Mardini论坛人物档案","url":"https://www.olympics.com/ioc/olympism-in-action/speakers/yusra-mardini","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":2016,"description":"作为首届难民奥运代表队成员参加里约2016奥运会。","sourceUrls":["https://www.olympics.com/ioc/olympism-in-action/speakers/yusra-mardini"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('melanie-perkins','melanie-perkins','梅拉妮·珀金斯','Melanie Perkins','verified','{"id":"melanie-perkins","slug":"melanie-perkins","nameZh":"梅拉妮·珀金斯","nameEn":"Melanie Perkins","fields":["商业"],"regions":["澳大利亚"],"occupation":"企业家、设计平台共同创办人","keywords":["商业","企业家、设计平台共同创办人"],"summary":"梅拉妮·珀金斯是澳大利亚企业家，参与创办在线设计平台Canva。她与克利夫·奥布雷希特2007年推出面向学校年鉴制作的Fusion Books，后来与卡梅伦·亚当斯共同建设Canva。平台2013年上线，提供网页设计、素材与协作工具；当年的公司公告记载她担任首席执行官，创业经历涉及产品、团队与融资。","story":"珀金斯与奥布雷希特在大学学习期间，于2007年推出学校年鉴设计产品Fusion Books。这段经历先于Canva，两个产品的时间和用途需要分开记录，不能将学校年鉴业务直接当作Canva已经面向所有用户上线。\nCanva的2013年3月公告列出珀金斯、奥布雷希特与亚当斯组成的创办团队，并记载公司完成三百万美元种子融资。8月26日，公司宣布在线设计平台上线，将拖放编辑、素材库和协作放到网页工具中。两份公告均将珀金斯列为首席执行官，但融资完成、产品上线与后续盈利并不是同一事件。\n公司2023年十周年时间线还记录了移动应用、印刷服务与演示文稿工具等产品发展。这些是团队与组织历程，不能都归为共同创办人独自完成。资料来自公司自身公告，用户数量、估值、价格及市场地位只代表当时口径，本档案不作为今天的结论沿用，也不采用宣传性评价替代事实。故事未复制个人笔记或投资人引语，没有补写融资谈判场景，照片继续使用占位图。","achievements":["与克利夫·奥布雷希特于2007年推出学校年鉴设计产品Fusion Books。","作为Canva创办团队成员及当时CEO，参与2013年上线的在线设计平台。"],"facts":[{"claim":"与克利夫·奥布雷希特于2007年推出学校年鉴设计产品Fusion Books。","sourceUrls":["https://www.canva.com/newsroom/news/aussie-startup-canva-announces-3-million-seed-round-world-class-investors/"]},{"claim":"作为Canva创办团队成员及当时CEO，参与2013年上线的在线设计平台。","sourceUrls":["https://www.canva.com/newsroom/news/canva-makes-graphic-design-amazingly-simple-everyone/","https://www.canva.com/newsroom/news/aussie-startup-canva-announces-3-million-seed-round-world-class-investors/"]}],"sources":[{"title":"Canva：2013年种子融资与创办团队公告","url":"https://www.canva.com/newsroom/news/aussie-startup-canva-announces-3-million-seed-round-world-class-investors/","checkedAt":"2026-11-09"},{"title":"Canva：2013年8月26日上线公告","url":"https://www.canva.com/newsroom/news/canva-makes-graphic-design-amazingly-simple-everyone/","checkedAt":"2026-11-09"},{"title":"Canva：2023年十周年时间线","url":"https://www.canva.com/newsroom/news/canva-10-year-timeline/","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":2007,"description":"与克利夫·奥布雷希特于2007年推出学校年鉴设计产品Fusion Books。","sourceUrls":["https://www.canva.com/newsroom/news/aussie-startup-canva-announces-3-million-seed-round-world-class-investors/"]},{"year":2013,"description":"作为Canva创办团队成员及当时CEO，参与2013年上线的在线设计平台。","sourceUrls":["https://www.canva.com/newsroom/news/canva-makes-graphic-design-amazingly-simple-everyone/","https://www.canva.com/newsroom/news/aussie-startup-canva-announces-3-million-seed-round-world-class-investors/"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('pearl-buck','pearl-buck','赛珍珠','Pearl Buck','verified','{"id":"pearl-buck","slug":"pearl-buck","nameZh":"赛珍珠","nameEn":"Pearl Buck","fields":["文学"],"regions":["美国","中国"],"occupation":"作家、人道事务倡导者","keywords":["文学","作家、人道事务倡导者"],"summary":"赛珍珠是美国作家，幼年随父母在中国生活，后来往返中美求学、工作与写作。她1930年出版《东风·西风》，《大地》于1932年获得普利策奖，1938年获诺贝尔文学奖。除小说与传记写作外，她也参与跨文化交流、反歧视和儿童援助，1964年建立以儿童支持为方向的基金会，1973年去世。","story":"赛珍珠1892年出生于美国西弗吉尼亚州，婴儿时期随父母回到中国，成长中接触中文与英文教育。1910年，她到美国伦道夫—梅肯女子学院学习，1914年毕业，后来返回中国。1925年，她在康奈尔大学取得英国文学硕士学位。\n她1930年出版《东风·西风》，之后的《大地》于1932年获得普利策奖。1938年，她获得诺贝尔文学奖，相关认可涉及对中国农民生活的文学描写与传记创作。小说来自文学观察与加工，不能把其中每个场景都当作作者亲身经历，也不能把一个作家的叙述等同于整个中国社会的全部面貌。\n返回美国后，她继续写作并参与反歧视、跨文化交流及儿童援助。1964年，她创办基金会，支持儿童健康与教育等事务。其机构生平页面对Welcome House项目保留旧称仍在运行，同时附注说明项目2014年结束，本档案采用更正，不沿用旧句作为现状。诺贝尔官网本次403，奖项由人物机构正文核对；未复制小说、私人信件或补写动机，图片使用占位图。","achievements":["小说The Good Earth于1932年获得普利策奖。","1938年获得诺贝尔文学奖。"],"facts":[{"claim":"小说The Good Earth于1932年获得普利策奖。","sourceUrls":["https://pearlsbuck.org/about/biography/"]},{"claim":"1938年获得诺贝尔文学奖。","sourceUrls":["https://pearlsbuck.org/about/biography/"]}],"sources":[{"title":"Pearl S. Buck International：创办人生平","url":"https://pearlsbuck.org/about/biography/","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1932,"description":"小说The Good Earth于1932年获得普利策奖。","sourceUrls":["https://pearlsbuck.org/about/biography/"]},{"year":1938,"description":"1938年获得诺贝尔文学奖。","sourceUrls":["https://pearlsbuck.org/about/biography/"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('elizabeth-catlett','elizabeth-catlett','伊丽莎白·卡特利特','Elizabeth Catlett','verified','{"id":"elizabeth-catlett","slug":"elizabeth-catlett","nameZh":"伊丽莎白·卡特利特","nameEn":"Elizabeth Catlett","fields":["艺术"],"regions":["美国","墨西哥"],"occupation":"雕塑家、版画家、艺术教育者","keywords":["艺术","雕塑家、版画家、艺术教育者"],"summary":"伊丽莎白·卡特利特是出生于美国华盛顿的雕塑家和版画家，曾在霍华德大学与爱荷华大学学习，也从事艺术教学。她1946年赴墨西哥，加入大众版画工作坊，作品关注黑人女性及社会议题。她1973年创作菲利斯·惠特利雕像，以青铜和木材表现这位诗人；其跨国创作与教学生涯延续数十年，2012年去世。","story":"卡特利特在华盛顿出生，接受霍华德大学艺术教育，后来在美国南部任教，并到爱荷华大学随格兰特·伍德学习。第二次世界大战期间，她在纽约哈莱姆的乔治·华盛顿·卡弗学校教授艺术，教学与创作构成其早期职业生活的重要部分。\n1946年，她凭罗森沃尔德资助前往墨西哥，加入大众版画工作坊，与当地艺术家共同工作。史密森尼的资料将她的艺术与黑人女性及社会改革议题联系起来，但机构对作品的解释并不等于能据此还原每一次创作时的私人心理。\n1973年，她以青铜和木材制作诗人菲利斯·惠特利的雕像，参考较早的肖像版画，同时加入艺术处理。因此雕像不是艺术家与十八世纪诗人面对面写生的记录，作品人物也不能与创作者混淆。教学页面在生卒日期旁仍保留旧时现在时传记，本档案按2012年去世处理，不沿用继续创作的句子作为现状。作品图标明遗产管理方版权与许可机构，未取得转载许可，采用占位图，不复制名言。","achievements":["1946年前往墨西哥，加入大众版画工作坊Taller de Gráfica Popular。","1973年创作青铜与木材作品Phillis Wheatley。"],"facts":[{"claim":"1946年前往墨西哥，加入大众版画工作坊Taller de Gráfica Popular。","sourceUrls":["https://americanart.si.edu/education/oh-freedom/elizabeth-catlett"]},{"claim":"1973年创作青铜与木材作品Phillis Wheatley。","sourceUrls":["https://americanart.si.edu/education/oh-freedom/elizabeth-catlett"]}],"sources":[{"title":"Smithsonian American Art Museum：Elizabeth Catlett人物与作品教学档案","url":"https://americanart.si.edu/education/oh-freedom/elizabeth-catlett","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1946,"description":"1946年前往墨西哥，加入大众版画工作坊Taller de Gráfica Popular。","sourceUrls":["https://americanart.si.edu/education/oh-freedom/elizabeth-catlett"]},{"year":1973,"description":"1973年创作青铜与木材作品Phillis Wheatley。","sourceUrls":["https://americanart.si.edu/education/oh-freedom/elizabeth-catlett"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('charlotte-hawkins-brown','charlotte-hawkins-brown','夏洛特·霍金斯·布朗','Charlotte Hawkins Brown','verified','{"id":"charlotte-hawkins-brown","slug":"charlotte-hawkins-brown","nameZh":"夏洛特·霍金斯·布朗","nameEn":"Charlotte Hawkins Brown","fields":["教育"],"regions":["美国"],"occupation":"教育家、学校创办人","keywords":["教育","教育家、学校创办人"],"summary":"夏洛特·霍金斯·布朗是美国教育家，1883年出生于北卡罗来纳州，后来在马萨诸塞州成长和学习。她1902年创办帕尔默纪念学院，推动学校从农业与职业训练转向大学预备教育，课程包括音乐、艺术、数学与文学。她1952年退休，1940年出版礼仪著作，长期通过筹款和社区合作支持黑人学生教育。","story":"布朗在马萨诸塞州接受教育，受到教育家爱丽丝·弗里曼·帕尔默支持。1901年，她返回北卡罗来纳州任教，原学校关闭后，在学生家庭和支持者帮助下开展新的办学工作。1902年成立的帕尔默纪念学院以她的导师和资助者命名。\n学校早期包含农业和职业训练，随后逐步发展大学预备与文科课程，音乐、戏剧、美术、数学、文学和语言进入教学。学生也参与校内服务活动。办学需要教师、社区及捐助者合作，不能把课程建设和每位毕业生后来的职业成就都写成创办人独自带来的结果。\n1917年校园遭遇火灾后，布朗继续筹款维持学校；1940年，她出版《The Correct Thing to Do, to Say, to Wear》，1952年结束五十年的学校领导工作，由威廉明娜·克罗森接任。她1961年去世后，校园于1987年成为介绍其教育工作的州立历史场所。这里采用州历史机构与国家公园管理局正文，不把旧展览开放时间当作当前参观信息，也不补写课堂对白或学生个案，图片使用占位图。","achievements":["1902年创办Palmer Memorial Institute，领导学校五十年至1952年退休。","1940年出版The Correct Thing to Do, to Say, to Wear。"],"facts":[{"claim":"1902年创办Palmer Memorial Institute，领导学校五十年至1952年退休。","sourceUrls":["https://historicsites.nc.gov/all-sites/charlotte-hawkins-brown-museum/history/dr-charlotte-hawkins-brown"]},{"claim":"1940年出版The Correct Thing to Do, to Say, to Wear。","sourceUrls":["https://historicsites.nc.gov/all-sites/charlotte-hawkins-brown-museum/history/dr-charlotte-hawkins-brown"]}],"sources":[{"title":"NC Historic Sites：Charlotte Hawkins Brown与Palmer Memorial Institute历史","url":"https://historicsites.nc.gov/all-sites/charlotte-hawkins-brown-museum/history/dr-charlotte-hawkins-brown","checkedAt":"2026-11-09"},{"title":"National Park Service：Palmer Memorial Institute展览历史介绍","url":"https://www.nps.gov/brvb/learn/news/palmermemorial.htm","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1940,"description":"1940年出版The Correct Thing to Do, to Say, to Wear。","sourceUrls":["https://historicsites.nc.gov/all-sites/charlotte-hawkins-brown-museum/history/dr-charlotte-hawkins-brown"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('ruth-bader-ginsburg','ruth-bader-ginsburg','露丝·巴德·金斯伯格','Ruth Bader Ginsburg','verified','{"id":"ruth-bader-ginsburg","slug":"ruth-bader-ginsburg","nameZh":"露丝·巴德·金斯伯格","nameEn":"Ruth Bader Ginsburg","fields":["公共事务"],"regions":["美国"],"occupation":"法学教授、法官、最高法院大法官","keywords":["公共事务","法学教授、法官、最高法院大法官"],"summary":"露丝·巴德·金斯伯格是美国法学教授和法官，曾在罗格斯大学及哥伦比亚大学任教，并参与美国公民自由联盟女性权利项目。她1980年获任哥伦比亚特区巡回上诉法院法官，1993年进入美国最高法院，成为该院第二位女性大法官，任职至2020年去世。其职业经历涉及法律研究、平等权利倡导和司法工作。","story":"金斯伯格在康奈尔大学完成本科学习，曾就读哈佛法学院，并取得哥伦比亚大学法律学位。1959至1961年，她担任联邦地区法院法官助理，随后参与哥伦比亚法学院国际程序研究项目。她先后在罗格斯大学和哥伦比亚大学教授法律。\n最高法院的生平通报记载，她1971年参与推动美国公民自由联盟女性权利项目，1973至1980年任该组织总法律顾问。倡导、学术研究与法庭工作构成不同职业角色，不能把组织集体工作的全部成果或全国法律变化都归于一个人。\n1980年，她成为哥伦比亚特区巡回上诉法院法官；1993年获克林顿总统任命进入最高法院，成为该院第二位女性大法官。2020年9月18日，她去世，任职超过二十七年。这里以法院当年的生平通报核对教育、任职和组织经历，传记旧链接错误已记录，未采用搜索摘要替代正文。故事不复述未经读取的具体判决、不把历史工作写成个人法律建议，也不复制私人言论或补写庭审对白。","achievements":["1980年获任美国哥伦比亚特区巡回上诉法院法官。","1993年获任美国最高法院大法官，是该院第二位女性大法官，任职至2020年。"],"facts":[{"claim":"1980年获任美国哥伦比亚特区巡回上诉法院法官。","sourceUrls":["https://www.supremecourt.gov/publicinfo/press/pressreleases/pr_09-18-20"]},{"claim":"1993年获任美国最高法院大法官，是该院第二位女性大法官，任职至2020年。","sourceUrls":["https://www.supremecourt.gov/publicinfo/press/pressreleases/pr_09-18-20"]}],"sources":[{"title":"Supreme Court of the United States：2020年9月18日生平通报","url":"https://www.supremecourt.gov/publicinfo/press/pressreleases/pr_09-18-20","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1980,"description":"1980年获任美国哥伦比亚特区巡回上诉法院法官。","sourceUrls":["https://www.supremecourt.gov/publicinfo/press/pressreleases/pr_09-18-20"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
insert into public.women_profiles(id,slug,name_zh,name_en,status,source_data) values('ann-bancroft','ann-bancroft','安·班克罗夫特','Ann Bancroft','verified','{"id":"ann-bancroft","slug":"ann-bancroft","nameZh":"安·班克罗夫特","nameEn":"Ann Bancroft","fields":["探索"],"regions":["美国"],"occupation":"极地探险者、教育者","keywords":["探索","极地探险者、教育者"],"summary":"安·班克罗夫特是美国极地探险者和教育者，曾从事体育及特殊教育教学。她1986年随斯特格国际极地探险队跨冰面抵达北极点，1993年率四名女性组成的队伍滑雪前往南极点。她还与丽芙·阿内森于2001年完成南极大陆穿越，并通过基金会将探险经历与教育活动联系起来，相关历程依靠团队合作与长期准备。","story":"班克罗夫特1955年出生于明尼苏达州，在俄勒冈大学取得体育教育学位，后来在明尼阿波利斯和圣保罗从事体育及特殊教育教学，也指导学校运动项目。教育工作与户外活动成为她职业经历中相互联系的部分。\n1986年，她作为斯特格国际极地探险队唯一女性成员，随队使用狗拉雪橇跨越冰面抵达北极点。1993年，她率领四名女性组成的队伍，经过六十七天滑雪抵达南极点。两个任务的路线、交通方式及团队构成不同，不能概括为她独自徒步到达两极，也不能把到达极点等同于完成整个大陆穿越。\n2001年，她与挪威探险者丽芙·阿内森通过滑雪和帆助方式完成南极大陆穿越。基金会资料将这一行程与两人合作及教育传播联系起来，并说明组织早期名为AWE Foundation，后来调整方向和名称。这里依据人物基金会时间线记录历史，不以宣传语推定所有探险纪录在今日仍未被改变，也不混淆同名演员Anne Bancroft。故事未复制采访或补写险境对白，图像采用占位图。","achievements":["1986年作为斯特格国际极地探险队成员跨冰面抵达北极点。","1993年率四名女性组成的队伍，以六十七天滑雪行程抵达南极点。"],"facts":[{"claim":"1986年作为斯特格国际极地探险队成员跨冰面抵达北极点。","sourceUrls":["https://www.annbancroftfoundation.org/about/ann-bancroft"]},{"claim":"1993年率四名女性组成的队伍，以六十七天滑雪行程抵达南极点。","sourceUrls":["https://www.annbancroftfoundation.org/about/ann-bancroft"]}],"sources":[{"title":"Ann Bancroft Foundation：Ann Bancroft官方生平与探险时间线","url":"https://www.annbancroftfoundation.org/about/ann-bancroft","checkedAt":"2026-11-09"}],"image":{"url":"/women-placeholder.svg","license":"original","credit":"HerSpace 原创占位图","sourceUrl":"/women-placeholder.svg","author":"HerSpace","attributionRequired":false},"status":"verified","updatedAt":"2026-11-09","featured":false,"lastVerifiedAt":"2026-11-09","reviewedAt":null,"editorialNotes":[],"timeline":[{"year":1986,"description":"1986年作为斯特格国际极地探险队成员跨冰面抵达北极点。","sourceUrls":["https://www.annbancroftfoundation.org/about/ann-bancroft"]},{"year":1993,"description":"1993年率四名女性组成的队伍，以六十七天滑雪行程抵达南极点。","sourceUrls":["https://www.annbancroftfoundation.org/about/ann-bancroft"]}]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name_zh=excluded.name_zh,name_en=excluded.name_en,status=excluded.status,source_data=excluded.source_data;
